def load_benzene(project_id: str) -> dict:
    path = Path("src/material_studio_mcp_server/examples/benzene_spec.json")
    spec = json.loads(path.read_text(encoding="utf-8"))
    spec["project_id"] = project_id
    return spec


def test_gui_tools_preview_and_status(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    status = server.material_studio_gui_status(working_dir=str(tmp_path))
    assert status["ok"] is True
    assert status["status"] == "ready_for_same_window_live_edit"
    assert status["recommended_tool"] == "material_studio_gui_snapshot"
    assert status["can_apply_current_revision_without_new_window"] is True
    assert status["ready_for_next_live_edit"] is True
    assert status["window_found"] is True

    spec = load_benzene("gui_preview_proj")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    assert created["ok"] is True

    preview = server.material_studio_gui_apply_current_revision("gui_preview_proj", working_dir=str(tmp_path))
    assert preview["ok"] is True
    assert preview["execution_mode"] == "preview"
    assert preview["validation"]["valid"] is True
    assert preview["gui_status"]["window_found"] is True
    assert preview["modeling_health"]["verdict"] == "ready_for_review"
    assert preview["view_audit"]["model"]["atom_count"] == 12
    assert Path(preview["view_audit_report_path"]).exists()
    assert Path(preview["report_json_path"]).exists()
    assert Path(preview["view_bundle_manifest_path"]).exists()
    assert preview["view_bundle_row_counts"]["view_projections"] == 84
    assert preview["modeling_report"]["normality"] == "preview_ready"
    normality_gate = preview["modeling_report"]["normality_gate"]
    assert normality_gate["status"] == "preview_only"
    assert normality_gate["can_claim_model_normal"] is False
    assert normality_gate["can_claim_live_gui_normal"] is False
