def test_noncollinear_crystal_direction_remains_review_gated() -> None:
    plan = infer_modeling_plan("Build beta-Ga2O3 crystal and prepare preview.")
    spec = ModelSpec.model_validate(plan.payload)
    view = model_view_audit(spec, ["crystal_110"])["views"][0]
    mapping = view["crystal_direction_view_onto_plane_mapping"]
    step = gui_module._view_replay_step(view, index=0)
    recipe = gui_module._view_replay_execution_recipe(
        step,
        _verified_view_command_evidence(),
    )

    assert mapping["status"] == "no_exact_integer_plane_within_search_bound"
    assert mapping["automation_eligible"] is False
    assert mapping["angular_error_degrees"] > 0.0
    assert recipe["automation_ready"] is False
    assert recipe["status"] == "deterministic_selection_recipe_required"
    assert (
        "direct_lattice_direction_has_no_exact_collinear_integer_miller_plane_recipe"
        in recipe["block_reasons"]
    )


def test_live_modeling_request_continues_view_replay_without_creating_revision(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )
    monkeypatch.setattr(
        gui_module,
        "_materials_studio_view_command_evidence",
        _verified_view_command_evidence,
    )

    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    project_id = created["project_id"]
    history_before = server.material_studio_project_history(project_id, working_dir=str(tmp_path))["history"]

    continued = server.material_studio_live_modeling_request(
        "Continue the next GUI view replay safely.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
    )

    assert continued["ok"] is True
    assert continued["workflow"] == "continue_view_replay"
    assert continued["nl_plan"]["kind"] == "continue_view_replay"
    assert continued["nl_plan"]["template_id"] == "continue_view_replay"
    assert continued["revision"] == created["revision"]
    assert continued["revision_created"] is False
    assert continued["view_replay_continuation_requested"] is True
    assert continued["view_replay_prepared"] is True
    assert continued["view_replay_prepare"]["ok"] is True
    assert continued["view_replay_continuation"]["status"] == (
        "runtime_accessibility_preflight_required"
    )
    assert continued["view_replay_continuation"]["next_automation_ready_view_name"] is None
    assert continued["view_replay_continuation"]["recommended_mcp_tool"] == (
        "material_studio_gui_prepare_view_replay"
    )
    assert continued["view_replay_continuation"][
        "runtime_accessibility_preflight_required"
    ] is True
    assert continued["view_replay_continuation"][
        "payload_hint_is_directly_callable"
    ] is False
    assert continued["gui_view_replay"]["replay_summary"]["event_count"] == 0
    assert continued["gui_view_replay"]["events_exist"] is False

    resumed_english = server.material_studio_live_modeling_request(
        "Resume view replay.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    assert resumed_english["ok"] is True
    assert resumed_english["workflow"] == "continue_view_replay"
    assert resumed_english["view_replay_prepared"] is False
    assert resumed_english["view_replay_continuation"]["next_automation_ready_view_name"] is None

    resumed_explicit = server.material_studio_live_modeling_request(
        "Continue the next GUI view replay.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    assert resumed_explicit["ok"] is True
    assert resumed_explicit["workflow"] == "continue_view_replay"
    assert resumed_explicit["view_replay_prepared"] is False
    assert resumed_explicit["view_replay_continuation"]["next_automation_ready_view_name"] is None

    resumed = server.material_studio_live_modeling_request(
        "继续验证下一个 GUI 视角",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    assert resumed["ok"] is True
    assert resumed["workflow"] == "continue_view_replay"
    assert resumed["view_replay_prepared"] is False
    assert resumed["view_replay_continuation"]["next_automation_ready_view_name"] is None
    history_after = server.material_studio_project_history(project_id, working_dir=str(tmp_path))["history"]
    assert len(history_after) == len(history_before)


def test_live_view_replay_upgrades_stale_pending_recipe_without_losing_events(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )
    monkeypatch.setattr(
        gui_module,
        "_materials_studio_view_command_evidence",
        _verified_view_command_evidence,
    )

    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    project_id = created["project_id"]
    revision = created["revision"]
    prepared = server.material_studio_gui_prepare_view_replay(
        project_id=project_id,
        revision=revision,
        views=["front", "right"],
        runtime_accessibility_evidence=_complete_view_runtime_accessibility_evidence(
            revision=revision,
            window=backend.window,
            include_movement=False,
        ),
        working_dir=str(tmp_path),
    )
    assert prepared["ok"] is True
    assert prepared["runtime_accessibility_preflight"]["status"] == (
        "verified_partial_control_coverage"
    )
    assert prepared["runtime_accessibility_preflight"][
        "automation_gate_satisfied"
    ] is False
    assert all(
        view["execution_recipe"]["automation_ready"] is True
        for view in prepared["manifest"]["views"]
    )
    assert prepared["recipe_contract"]["status"] == "current"

    front = server.material_studio_gui_record_view_replay(
        view_name="front",
        project_id=project_id,
        revision=revision,
        source="computer_use",
        native_command_id="cmdViewer3DResetView",
        screenshot_path=_crystal_view_screenshot(tmp_path, "front_migration.bmp"),
        crystal_camera_evidence=_complete_crystal_camera_evidence(),
        working_dir=str(tmp_path),
    )
    assert front["ok"] is True
    assert front["accepted"] is True
    accepted_event_id = front["event"]["event_id"]

    manifest_path = Path(prepared["manifest_path"])
    stale_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    right_view = next(
        view for view in stale_manifest["views"] if view["view_name"] == "right"
    )
    right_view["execution_recipe"]["schema_version"] = 0
    manifest_path.write_text(
        json.dumps(stale_manifest, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    stale_manifest_sha256 = hashlib.sha256(manifest_path.read_bytes()).hexdigest()

    status = server.material_studio_live_project_status(
        project_id=project_id,
        include_gui_status=False,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    replay = status["gui_view_replay"]
    assert replay["project_id"] == project_id
    assert replay["revision"] == revision
    assert replay["spec_fingerprint"] == stale_manifest["spec_fingerprint"]
    assert replay["current_spec_fingerprint"] == stale_manifest[
        "spec_fingerprint"
    ]
    assert replay["binding_status"] == "verified_current_revision"
    assert replay["binding_verified"] is True
    assert replay["binding_reasons"] == []
    assert replay["recipe_contract"]["status"] == "pending_recipe_upgrade_required"
    assert replay["recipe_contract"]["pending_upgrade_view_names"] == ["right"]
    assert replay["replay_continuation"]["status"] == "recipe_upgrade_required"
    assert replay["replay_continuation"]["automatic_replay_ready"] is False
    assert replay["replay_continuation"]["recommended_mcp_tool"] == (
        "material_studio_live_modeling_request"
    )
    assert replay["next_action"] == {
        "continuation_status": "recipe_upgrade_required",
        "recommended_tool": "material_studio_live_modeling_request",
        "recommended_action": (
            "regenerate_view_replay_manifest_with_current_safety_recipes_preserving_events"
        ),
        "payload_hint": {
            "user_request": "Continue GUI view replay using the current safety recipe.",
            "project_id": project_id,
        },
        "payload_hint_is_directly_callable": True,
        "source": "replay_continuation",
    }
    resolution = replay["next_action_resolution"]
    assert resolution["status"] == "continuation_safety_override_applied"
    assert resolution["authoritative_source"] == "replay_continuation"
    assert resolution["incoming_action_overridden"] is True
    assert resolution["safety_gate"]["automatic_replay_allowed"] is False
    assert resolution["safety_gate"]["stale_recipe_execution_blocked"] is True
    assert resolution["safety_gate"]["structure_mutation_allowed"] is False
    assert resolution["safety_gate"]["revision_creation_allowed"] is False

    full_status = server.material_studio_live_project_status(
        project_id=project_id,
        include_gui_status=False,
        working_dir=str(tmp_path),
        response_mode="full",
    )
    assert full_status["gui_view_replay"]["next_action"] == replay["next_action"]
    assert full_status["gui_view_replay"]["next_action_resolution"][
        "resolved_recommended_tool"
    ] == resolution["resolved_recommended_tool"]
    assert hashlib.sha256(manifest_path.read_bytes()).hexdigest() == (
        stale_manifest_sha256
    )

    history_before_preflight = server.material_studio_project_history(
        project_id,
        working_dir=str(tmp_path),
    )["history"]
    preflight = server.material_studio_live_session_preflight(
        working_dir=str(tmp_path)
    )
    visual_summary = preflight["latest_project_visual_diagnostics"]
    assert visual_summary["binding_verified"] is True
    assert visual_summary["action_available"] is True
    assert visual_summary["replay_status"] == "partially_confirmed"
    assert visual_summary["continuation_status"] == "recipe_upgrade_required"
    assert visual_summary["next_action_plan_ref"] == (
        "visual_diagnostics_next_action_plan"
    )
    visual_plan = preflight["visual_diagnostics_next_action_plan"]
    assert visual_plan["state"] == "recipe_upgrade_required"
    assert visual_plan["action_id"] == "continue_gui_view_replay"
    assert visual_plan["recommended_tool"] == (
        "material_studio_live_modeling_request"
    )
    assert visual_plan["needs_user_confirmation"] is False
    assert visual_plan["safe_to_call_without_confirmation"] is True
    assert visual_plan["mutates_structure"] is False
    assert visual_plan["creates_revision"] is False
    assert visual_plan["issues_gui_input"] is False
    assert visual_plan["requires_requery_after_call"] is True
    coordinated = preflight["coordinated_next_action_plan"]
    sequence = coordinated["recommended_sequence"]
    visual_step = next(
        step for step in sequence if step["track"] == "visual_diagnostics"
    )
    assert visual_step["plan_ref"] == "visual_diagnostics_next_action_plan"
    assert visual_step["action_id"] == "continue_gui_view_replay"
    modeling_step_indexes = [
        index for index, step in enumerate(sequence) if step["track"] == "modeling"
    ]
    visual_step_index = sequence.index(visual_step)
    assert all(visual_step_index < index for index in modeling_step_indexes)
    assert preflight["next_action_tracks"]["recommended_sequence_ref"] == (
        "coordinated_next_action_plan.recommended_sequence"
    )
    assert preflight["mcp_client_readiness"]["next_action_sequence_ref"] == (
        "coordinated_next_action_plan.recommended_sequence"
    )
    assert len(
        json.dumps(
            preflight,
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
    ) < server.COMPACT_RESPONSE_MAX_BYTES
    assert hashlib.sha256(manifest_path.read_bytes()).hexdigest() == (
        stale_manifest_sha256
    )
    assert server.material_studio_project_history(
        project_id,
        working_dir=str(tmp_path),
    )["history"] == history_before_preflight

    rejected = server.material_studio_gui_record_view_replay(
        view_name="right",
        project_id=project_id,
        revision=revision,
        source="computer_use",
        native_command_id="cmdViewer3DResetView",
        key_sequence=["Up", "Up", "Left", "Left"],
        reset_before_key_sequence=True,
        rotation_increment_degrees=45,
        modifier_keys=[],
        working_dir=str(tmp_path),
    )
    assert rejected["ok"] is False
    assert "view replay recipe is not current" in rejected["error"]
    persisted_stale = json.loads(manifest_path.read_text(encoding="utf-8"))
    assert [event["event_id"] for event in persisted_stale["replay_events"]] == [
        accepted_event_id
    ]

    history_before = server.material_studio_project_history(
        project_id,
        working_dir=str(tmp_path),
    )["history"]
    activated_before = list(backend.activated_handles)
    opened_before = list(backend.opened)
    continued = server.material_studio_live_modeling_request(
        "Continue the next GUI view replay safely.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    assert continued["ok"] is True
    assert continued["workflow"] == "continue_view_replay"
    assert continued["revision"] == revision
    assert continued["revision_created"] is False
    assert continued["view_replay_prepared"] is True
    assert continued["view_replay_prepare"]["recipe_migration"]["performed"] is True
    assert continued["view_replay_prepare"]["recipe_migration"][
        "preserved_replay_event_count"
    ] == 1
    assert continued["view_replay_continuation"]["status"] == (
        "automatic_recipe_ready"
    )
    assert continued["view_replay_continuation"]["next_pending_view_name"] == "right"
    assert continued["gui_view_replay"]["recipe_contract"]["status"] == "current"
    assert backend.activated_handles == activated_before
    assert backend.opened == opened_before

    migrated_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    migrated_right = next(
        view for view in migrated_manifest["views"] if view["view_name"] == "right"
    )
    assert migrated_right["execution_recipe"]["schema_version"] == (
        gui_module.CRYSTAL_STANDARD_VIEW_RECIPE_SCHEMA_VERSION
    )
    assert migrated_right["execution_recipe"]["recipe_kind"] == (
        "crystal_standard_view_with_native_in_plane_roll"
    )
    assert [event["event_id"] for event in migrated_manifest["replay_events"]] == [
        accepted_event_id
    ]
    history_after = server.material_studio_project_history(
        project_id,
        working_dir=str(tmp_path),
    )["history"]
    assert len(history_after) == len(history_before)


