def test_crystal_cif_roundtrip_blocks_tampered_artifact_and_rematerializes_same_revision(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    controller = MaterialsStudioGuiController(tmp_path, backend=backend)
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: controller)
    created = server.material_studio_live_modeling_request(
        "Build silicon crystal and hot-load it in Materials Studio.",
        take_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True
    assert created["revision"] == 0
    assert created["structure_artifact_validation"]["status"] == "matched"
    assert created["structure_artifact_validation"]["ok"] is True
    structure_path = Path(created["planned_outputs"]["structure"])
    original = structure_path.read_text(encoding="utf-8")
    structure_path.write_text(
        original.replace("_cell_length_a    5.431", "_cell_length_a    9.9", 1),
        encoding="utf-8",
    )

    status = server.material_studio_live_project_status(
        project_id=created["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
    )

    assert status["ok"] is True
    assert status["revision"] == 0
    assert status["structure_artifact_validation_status"] == "mismatch"
    assert status["structure_artifact_validation_ok"] is False
    assert status["modeling_health"]["verdict"] == "failed"
    assert status["normality"] == "failed"
    next_action = status["next_action_plan"]
    assert next_action["action_id"] == "verify_single_window_gui_preflight"
    assert next_action["recommended_tool"] == "material_studio_gui_status"
    assert next_action["needs_user_confirmation"] is False
    assert next_action["safe_to_call_without_confirmation"] is True
    assert next_action["gui_preflight_required"] is True
    assert next_action["deferred_hotload_action"] == {
        "action_id": "rematerialize_current_structure_artifact",
        "recommended_tool": "material_studio_gui_apply_current_revision",
        "recommended_action": "rematerialize_current_revision_from_model_spec_then_hotload_and_reaudit",
        "needs_user_confirmation": True,
        "payload_hint": {
            "project_id": created["project_id"],
            "execution_mode": "execute",
            "open_in_gui": True,
            "take_snapshot": True,
            "export_view_audit": True,
        },
    }
    assert status["live_summary"]["next_action_id"] == "verify_single_window_gui_preflight"
    assert status["live_summary"]["next_action_tool"] == "material_studio_gui_status"

    exported = server.material_studio_model_export_view_bundle(
        project_id=created["project_id"],
        include_gui_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert exported["ok"] is True
    assert exported["modeling_health"]["verdict"] == "failed"
    assert exported["view_bundle_row_counts"]["structure_artifact_validation"] == 1
    artifact_json = Path(exported["view_bundle_files"]["structure_artifact_validation_json"])
    artifact_csv = Path(exported["view_bundle_files"]["structure_artifact_validation_csv"])
    assert json.loads(artifact_json.read_text(encoding="utf-8"))["status"] == "mismatch"
    assert "mismatch" in artifact_csv.read_text(encoding="utf-8")

    rematerialized = server.material_studio_gui_apply_current_revision(
        project_id=created["project_id"],
        execution_mode="execute",
        open_in_gui=True,
        take_snapshot=False,
        export_view_audit=True,
        working_dir=str(tmp_path),
    )

    assert rematerialized["ok"] is True
    assert rematerialized["revision"] == 0
    assert rematerialized["structure_artifact_validation_status"] == "matched"
    assert rematerialized["structure_artifact_validation_ok"] is True
    assert rematerialized["result"]["structure_artifact_validation"]["status"] == "matched"
    assert rematerialized["gui_status"]["process_count"] == 1
    assert rematerialized["gui_status"]["window_count"] == 1
    history = server.material_studio_project_history(created["project_id"], working_dir=str(tmp_path))
    assert len(history["history"]) == 1


