def test_live_capabilities_lists_templates_patches_and_schemas() -> None:
    capabilities = server.material_studio_live_capabilities()

    assert capabilities["ok"] is True
    assert capabilities["live_preflight_tool"] == "material_studio_live_session_preflight"
    assert capabilities["live_entry_tool"] == "material_studio_live_modeling_request"
    assert capabilities["live_status_tool"] == "material_studio_live_project_status"
    assert capabilities["live_status_project_id_optional"] is True
    assert capabilities["live_update_tool"] == "material_studio_live_update_with_patch"
    assert (
        capabilities["dopant_metadata_reconcile_tool"]
        == "material_studio_project_reconcile_dopant_metadata"
    )
    assert capabilities["dopant_metadata_reconcile_operation"] == "reconcile_dopant_metadata"
    assert (
        capabilities["dopant_metadata_reconcile_confirmation_field"]
        == "confirm_metadata_reconciliation"
    )
    assert capabilities["dopant_metadata_reconcile_requires_explicit_confirmation"] is True
    assert capabilities["recommended_kpoint_remediation_action_id"] == (
        "apply_recommended_semiconductor_kpoint_grid"
    )
    assert capabilities["recommended_calculation_settings_confirmation_field"] == (
        "confirm_recommended_calculation_settings"
    )
    assert (
        capabilities[
            "recommended_calculation_settings_requires_explicit_confirmation"
        ]
        is True
    )
    handoff = capabilities["castep_calculation_preview_handoff"]
    assert handoff["receipt_field"] == "calculation_preview.execution_handoff"
    assert handoff["preview_actions_are_workspace_bound"] is True
    assert handoff["preview_actions_are_revision_bound"] is True
    assert handoff["revision_binding_parameter"] == "expected_revision"
    assert handoff["task_execution_tools"]["Energy"] == (
        "material_studio_castep_run_current"
    )
    assert handoff["task_execution_tools"]["GeometryOptimization"] == (
        "material_studio_castep_relax_current"
    )
    assert handoff["task_execution_tools"]["Optics"] is None
    assert handoff["execute_requires_explicit_confirmation"] is True
    assert capabilities[
        "recommended_calculation_settings_receipt_recovery_field"
    ] == "recommended_calculation_settings_receipt_recovery"
    recovery_policy = capabilities[
        "recommended_calculation_settings_receipt_recovery_policy"
    ]
    assert recovery_policy["read_only"] is True
    assert recovery_policy["requires_current_report_binding"] is True
    assert recovery_policy["requires_current_history_binding"] is True
    assert recovery_policy["requires_base_current_spec_delta"] is True
    assert recovery_policy["requires_recomputed_reciprocal_status_ok"] is True
    assert recovery_policy["invalid_receipts_are_not_restored"] is True
    assert capabilities["live_update_project_id_optional"] is True
    assert capabilities["live_update_base_revision_optional"] is True
    assert capabilities["live_update_context_resolution_order"] == [
        "project_id argument",
        "patch.project_id",
        "latest current project",
    ]
