def test_live_modeling_request_exposes_p_gan_hemt_virtual_template_profile(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )

    result = server.material_studio_live_modeling_request(
        "Build a p-GaN gate AlGaN/GaN HEMT and export 2DEG and p-GaN gate diagnostics.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    virtual_id = "aluminum_gallium_nitride_gallium_nitride_0001_heterostructure_p_gan_gate"
    base_id = "aluminum_gallium_nitride_gallium_nitride_0001_heterostructure"
    assert result["ok"] is True
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["template_id"] == base_id
    assert result["semiconductor_template_profile"]["template_id"] == base_id
    assert result["semiconductor_virtual_template_id"] == virtual_id
    assert result["semiconductor_virtual_template_profile"]["base_template_id"] == base_id
    assert result["semiconductor_virtual_template_profile"]["inline_modifiers"] == ["p_gan_gate_cap"]
    assert result["semiconductor_virtual_template_default_diagnostic_focuses"] == result["modeling_report"][
        "semiconductor_virtual_template_default_diagnostic_focuses"
    ]
    assert "dopant_site_preflight" in result["recommended_diagnostic_focuses"]
    assert "semiconductor_p_gan_gate_cap_csv" in result["semiconductor_virtual_template_profile"]["required_csv_keys"]
    assert result["view_bundle_row_counts"]["semiconductor_p_gan_gate_cap"] == 4
    assert Path(result["view_bundle_files"]["semiconductor_p_gan_gate_cap_csv"]).exists()

    report = result["modeling_report"]
    assert report["semiconductor_virtual_template_id"] == virtual_id
    assert report["change_receipt"]["semiconductor_virtual_template_id"] == virtual_id
    assert report["live_summary"]["semiconductor_virtual_template_id"] == virtual_id
    assert report["live_summary"]["mcp_semiconductor_virtual_template_id"] == virtual_id
    assert report["diagnostic_focus_plan"]["recommended_focuses"] == result["recommended_diagnostic_focuses"]

    summary_rows = list(
        csv.DictReader(Path(result["view_bundle_files"]["modeling_report_summary_csv"]).open(encoding="utf-8"))
    )
    assert summary_rows[0]["semiconductor_virtual_template_id"] == virtual_id
    assert "dopant_site_preflight" in json.loads(summary_rows[0]["recommended_diagnostic_focuses"])


def test_live_session_preflight_reports_ready_new_session(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))
    monkeypatch.setattr(server, "runner", FakeRunner())

    result = server.material_studio_live_session_preflight(working_dir=str(tmp_path))

    assert result["ok"] is True
    assert result["state"] == "ready_for_new_model"
    assert result["readiness"]["preview_ready"] is True
    assert result["readiness"]["semiconductor_templates_ready"] is True
    assert result["readiness"]["runner_ready"] is True
    assert result["readiness"]["gui_window_found"] is True
    assert result["readiness"]["gui_process_count"] == 1
    assert result["readiness"]["gui_window_count"] == 1
    assert result["readiness"]["gui_target_window_found"] is True
    assert result["readiness"]["gui_target_window_handle"] == 101
    assert result["readiness"]["gui_target_window_title"] == "Untitled - Materials Studio"
    assert result["readiness"]["gui_target_window_is_selected"] is True
    assert result["readiness"]["gui_must_reuse_existing_window"] is True
    assert result["readiness"]["gui_auto_launch_during_hotload_allowed"] is False
    assert result["readiness"]["gui_single_window_policy_ok"] is True
    assert result["readiness"]["gui_single_window_violation_reasons"] == []
    assert result["readiness"]["live_hotload_ready"] is True
    assert result["readiness"]["latest_project_available"] is False
    assert result["latest_project"] == {"available": False, "reason": "no_current_project"}
    assert result["recommended_tool"] == "material_studio_live_modeling_request"
    assert result["next_action_plan"]["action_id"] == "create_new_live_model_from_template_or_model_spec"
    assert result["next_action_plan"]["recommended_tool"] == "material_studio_live_modeling_request"
    assert result["next_action_plan"]["safe_to_call_without_confirmation"] is True
    client = result["mcp_client_readiness"]
    assert client["status"] == "ready_for_live_modeling"
    assert client["can_accept_modeling_request"] is True
    assert client["can_accept_preview_request"] is True
    assert client["can_accept_hotload_request_without_new_window"] is True
    assert client["can_apply_current_revision_without_new_window"] is False
    assert "current_revision_loaded_in_gui" not in client
    assert client["visible_followup_ready"] is False
    assert client["visible_followup_status"] == "no_current_project"
    assert client["visible_followup_blocking_reasons"] == ["no_current_project"]
    assert client["visible_followup_recommended_tool"] == "material_studio_live_modeling_request"
    assert client["visible_followup_recommended_action"] == "create_new_live_model_from_template_or_model_spec"
    assert client["visible_followup_payload_hint"] == {
        "working_dir": str(tmp_path.resolve())
    }
    assert result["visible_followup_contract"]["visible_followup_ready"] is False
    assert result["visible_followup_contract"]["visible_followup_status"] == "no_current_project"
    assert result["visible_followup_contract"]["visible_followup_recommended_tool"] == "material_studio_live_modeling_request"
