def test_live_session_preflight_summarizes_latest_semiconductor_project(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))
    monkeypatch.setattr(server, "runner", FakeRunner())

    created = server.material_studio_live_modeling_request("Build silicon crystal.", working_dir=str(tmp_path))
    assert created["ok"] is True

    result = server.material_studio_live_session_preflight(working_dir=str(tmp_path))

    assert result["ok"] is True
    assert result["state"] == "ready_for_live_edit"
    assert result["readiness"]["latest_project_available"] is True
    latest = result["latest_project"]
    assert latest["available"] is True
    assert latest["project_id"] == created["project_id"]
    assert latest["revision"] == created["revision"]
    assert latest["model_type"] == "crystal"
    assert latest["script_exists"] is True
    assert latest["script_valid"] is True
    assert latest["planned_structure"].endswith(".cif")
    assert latest["report_json_exists"] is True
    assert result["recommended_action"] == "send_next_modeling_request_or_execute_current_revision_when_confirmed"
    assert result["next_action_plan"]["action_id"] == "send_follow_up_live_modeling_request"
    assert result["next_action_plan"]["payload_hint"]["project_id"] == created["project_id"]
    assert result["next_action_plan"]["payload_hint"]["working_dir"] == str(
        tmp_path.resolve()
    )
    client = result["mcp_client_readiness"]
    assert client["current_revision_loaded_in_gui"] is False
    assert client["visible_followup_ready"] is False
    assert client["visible_followup_status"] == "current_revision_not_materialized"
    assert client["visible_followup_blocking_reasons"] == ["current_revision_not_materialized"]
    assert client["visible_followup_recommended_tool"] == "material_studio_gui_apply_current_revision"
    assert (
        client["visible_followup_recommended_action"]
        == "execute_current_revision_to_materialize_structure_when_user_confirms"
    )
    assert client["visible_followup_payload_hint"]["project_id"] == created["project_id"]
    assert client["visible_followup_payload_hint"]["execution_mode"] == "execute"
    assert client["visible_followup_payload_hint"]["open_in_gui"] is True
    assert client["visible_followup_payload_hint"]["take_snapshot"] is True
    assert client["visible_followup_payload_hint"]["export_view_audit"] is True
    assert client["visible_followup_payload_hint"]["working_dir"] == str(
        tmp_path.resolve()
    )
    assert result["visible_followup_contract"]["visible_followup_status"] == "current_revision_not_materialized"
    assert result["visible_followup_contract"]["project_id"] == created["project_id"]
    assert result["visible_followup_contract"]["revision"] == created["revision"]
    assert result["mcp_visible_followup_status"] == "current_revision_not_materialized"
    assert result["mcp_visible_followup_payload_hint"] == client["visible_followup_payload_hint"]

    planned_structure = Path(latest["planned_structure"])
    planned_structure.parent.mkdir(parents=True, exist_ok=True)
    planned_structure.write_text("data_model\n", encoding="utf-8")
    rechecked = server.material_studio_live_session_preflight(working_dir=str(tmp_path))
    rechecked_client = rechecked["mcp_client_readiness"]
    assert rechecked_client["current_revision_loaded_in_gui"] is False
    assert rechecked_client["visible_followup_ready"] is False
    assert rechecked_client["visible_followup_status"] == "needs_current_revision_reload"
    assert rechecked_client["visible_followup_blocking_reasons"] == ["current_revision_not_loaded_in_gui"]
    assert rechecked_client["visible_followup_recommended_tool"] == "material_studio_gui_open_structure"
    assert rechecked_client["visible_followup_recommended_action"] == "reload_current_revision_in_gui_and_snapshot"
    assert rechecked_client["visible_followup_payload_hint"]["structure_path"] == latest["planned_structure"]
    assert rechecked_client["visible_followup_payload_hint"]["project_id"] == created["project_id"]
    assert rechecked_client["visible_followup_payload_hint"]["revision"] == created["revision"]
    assert rechecked_client["visible_followup_payload_hint"]["reuse_existing_window_only"] is True
    assert rechecked_client["visible_followup_payload_hint"]["working_dir"] == str(
        tmp_path.resolve()
    )
    assert rechecked["visible_followup_contract"]["visible_followup_status"] == "needs_current_revision_reload"
    assert rechecked["visible_followup_contract"]["visible_followup_payload_hint"] == rechecked_client["visible_followup_payload_hint"]
    assert rechecked["visible_followup_status"] == "needs_current_revision_reload"
    assert rechecked["mcp_visible_followup_status"] == "needs_current_revision_reload"
    assert rechecked["mcp_visible_followup_payload_hint"] == rechecked_client["visible_followup_payload_hint"]

    reloaded = server.material_studio_gui_open_structure(
        **rechecked_client["visible_followup_payload_hint"],
    )
    assert reloaded["ok"] is True
    assert reloaded["reuse_existing_window_only"] is True
    assert reloaded["structured_sync"]["persisted"] is True
    assert reloaded["structured_sync"]["project_id"] == created["project_id"]
    assert reloaded["structured_sync"]["revision"] == created["revision"]


