def test_live_session_preflight_requires_single_window_before_activating_target_window(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = MultiWindowFakeGuiBackend()
    controller = MaterialsStudioGuiController(tmp_path, backend=backend)
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: controller)
    monkeypatch.setattr(server, "runner", FakeRunner())

    created = server.material_studio_live_modeling_request("Build silicon crystal.", working_dir=str(tmp_path))
    assert created["ok"] is True
    planned_structure = Path(created["planned_outputs"]["structure"])
    planned_structure.parent.mkdir(parents=True, exist_ok=True)
    planned_structure.write_text("data_model\n", encoding="utf-8")
    wrapper = controller._create_project_wrapper(
        planned_structure.resolve(),
        project_id=created["project_id"],
        revision=created["revision"],
    )
    target_window = WindowInfo(
        handle=303,
        title=f"{wrapper['project_name']} - Materials Studio",
        pid=2222,
        rect=(0, 0, 1024, 768),
    )
    backend.windows = [backend.window, target_window]

    result = server.material_studio_live_session_preflight(working_dir=str(tmp_path))

    assert result["ok"] is True
    assert result["state"] == "preview_ready_gui_single_window_policy_review"
    assert result["recommended_tool"] == "material_studio_gui_status"
    assert result["recommended_action"] == "close_save_extra_matstudio_windows_or_activate_target_window_then_retry_live_session_preflight"
    latest_gui = result["latest_project_gui"]
    assert latest_gui["loaded_current_revision"] is True
    assert latest_gui["matching_window_count"] == 1
    assert latest_gui["target_window_matched_project_window"] is True
    assert latest_gui["target_window_handle"] == 303
    assert latest_gui["window_management_target_window_is_selected"] is False
    assert latest_gui["window_management_recommended_tool"] == "material_studio_gui_status"
    assert latest_gui["window_management_single_window_policy_ok"] is False
    assert latest_gui["window_management_single_window_violation_reasons"] == ["multiple_matstudio_windows_detected"]
