def test_live_modeling_request_execute_hotload_refuses_multiple_matstudio_windows(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = MultiWindowFakeGuiBackend()
    backend.windows = [
        backend.window,
        WindowInfo(handle=404, title="Extra - Materials Studio", pid=2222, rect=(20, 20, 1024, 768)),
    ]
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is False
    assert result["execution_mode"] == "execute"
    assert result["single_window_hotload_block"]["reason"] == "single_window_policy_violation"
    assert result["single_window_hotload_block"]["single_window_violation_reasons"] == [
        "multiple_matstudio_windows_detected"
    ]
    assert "result" not in result
    assert "gui_open" not in result
    assert backend.opened == []
    readiness = result["modeling_report"]["live_readiness"]
    assert readiness["state"] == "blocked"
    assert readiness["ready_for_hotload"] is False
    assert "gui_single_window_policy_violation" in readiness["blocking_reasons"]
    assert result["live_summary"]["live_action_id"] == "resolve_single_window_materials_studio_session"
    acceptance = result["live_gui_acceptance"]
    assert acceptance == result["modeling_report"]["live_gui_acceptance"]
    assert acceptance["ok"] is False
    assert acceptance["single_window_policy_ok"] is False
    assert acceptance["single_window_violation_reasons"] == ["multiple_matstudio_windows_detected"]
    failure_types = {failure["type"] for failure in acceptance["failures"]}
    assert "single_window_policy_violation" in failure_types
    assert result["live_summary"]["live_gui_acceptance_ok"] is False
    assert result["live_summary"]["live_gui_acceptance_single_window_policy_ok"] is False
    assert result["live_summary"]["live_gui_acceptance_single_window_violation_reasons"] == [
        "multiple_matstudio_windows_detected"
    ]


def test_live_modeling_request_flags_post_open_spawned_matstudio_process(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = PostOpenSpawnProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert result["ok"] is True
    assert result["execution_mode"] == "execute"
    assert result["gui_open"]["same_window_open_used"] is True
    assert result["gui_open"]["open_result"]["spawned_process_ids"] == [8888]
    assert result["structure_path"] == result["planned_outputs"]["structure"]
    assert result["structure_exists"] is True
    assert result["gui_open_method"] == "fake_same_window_open"
    assert result["gui_open_path"] == result["gui_open"]["open_result"]["path"]
    assert result["gui_opened_structure_path"] == result["gui_open"]["structure_path"]
    assert result["gui_project_wrapper_path"] == result["gui_open"]["project_wrapper"]["project_path"]
    assert result["gui_same_window_open_used"] is True
    assert result["gui_open_spawned_process_ids"] == [8888]
    assert result["gui_open"]["single_window_policy_ok"] is False
    assert "multiple_matstudio_processes_detected" in result["gui_open"]["single_window_violation_reasons"]
    assert (
        "matstudio_process_spawned_during_same_window_open"
        in result["gui_open"]["single_window_violation_reasons"]
    )
    report = result["modeling_report"]
    assert report["gui"]["single_window_policy_ok"] is False
    assert report["gui"]["post_open_single_window_policy_ok"] is False
    assert "matstudio_process_spawned_during_same_window_open" in report["gui"]["single_window_violation_reasons"]
    assert report["live_gui_acceptance"]["ok"] is False
    assert report["normality_gate"]["can_claim_live_gui_normal"] is False
    assert "gui_single_window_policy_violation" in report["normality_gate"]["must_not_claim_normal_reasons"]
    assert result["live_summary"]["live_gui_acceptance_ok"] is False
    assert result["live_summary"]["live_gui_acceptance_single_window_policy_ok"] is False
    assert result["live_summary"]["mcp_can_claim_live_gui_normal"] is False
    assert result["live_summary"]["mcp_single_window_policy_ok"] is False
    assert result["live_summary"]["mcp_post_open_single_window_policy_ok"] is False
    assert "multiple_matstudio_processes_detected" in result["live_summary"][
        "mcp_post_open_single_window_violation_reasons"
    ]
    assert "matstudio_process_spawned_during_same_window_open" in result["live_summary"][
        "mcp_post_open_single_window_violation_reasons"
    ]
    assert result["live_summary"]["mcp_post_open_window_management_process_count"] == 2
    assert result["live_summary"]["mcp_post_open_window_management_recommended_tool"] == "material_studio_gui_status"
    summary_rows = list(
        csv.DictReader(Path(result["view_bundle_files"]["modeling_report_summary_csv"]).open(encoding="utf-8"))
    )
    assert len(summary_rows) == 1
    assert summary_rows[0]["gui_post_open_single_window_policy_ok"] == "False"
    assert "multiple_matstudio_processes_detected" in json.loads(
        summary_rows[0]["gui_post_open_single_window_violation_reasons"]
    )
    assert "matstudio_process_spawned_during_same_window_open" in json.loads(
        summary_rows[0]["gui_post_open_single_window_violation_reasons"]
    )
    assert summary_rows[0]["gui_post_open_window_management_process_count"] == "2"
    assert summary_rows[0]["gui_post_open_window_management_recommended_tool"] == "material_studio_gui_status"


def test_gui_current_revision_prefers_existing_nested_diagnostic_artifacts(tmp_path: Path) -> None:
    stale_audit_path = tmp_path / "stale" / "view_audit.json"
    stale_manifest_path = tmp_path / "stale" / "manifest.json"
    view_audit_path = tmp_path / "view_audit.json"
    report_json_path = tmp_path / "report.json"
    view_bundle_manifest_path = tmp_path / "view_bundle_manifest.json"
    for path in (view_audit_path, report_json_path, view_bundle_manifest_path):
        path.write_text("{}", encoding="utf-8")

    report = {
        "project_id": "artifact_binding_proj",
        "revision": 3,
        "view_audit_report_path": str(stale_audit_path),
        "diagnostics": {
            "view_audit_report_path": str(view_audit_path),
            "report_json_path": str(report_json_path),
            "view_bundle_manifest_path": str(stale_manifest_path),
        },
        "artifacts": {"view_bundle_manifest_path": str(view_bundle_manifest_path)},
        "structure": {"path": str(tmp_path / "structure.cif"), "exists": True},
        "gui": {
            "hot_loaded": True,
            "loaded_current_revision": True,
            "visual_validation": "passed",
        },
    }

    current = server._gui_current_revision_status_from_report(report)

    assert current["view_audit_report_path"] == str(view_audit_path)
    assert current["view_audit_report_exists"] is True
    assert current["view_audit_report_path_source"] == "diagnostics"
    assert current["report_json_path"] == str(report_json_path)
    assert current["report_json_exists"] is True
    assert current["report_json_path_source"] == "diagnostics"
    assert current["view_bundle_manifest_path"] == str(view_bundle_manifest_path)
    assert current["view_bundle_manifest_exists"] is True
    assert current["view_bundle_manifest_path_source"] == "artifacts"

    summary = server._gui_current_revision_live_summary(current)
    assert summary["gui_current_revision_view_audit_report_exists"] is True
    assert summary["gui_current_revision_view_audit_report_path_source"] == "diagnostics"
    assert summary["gui_current_revision_report_json_exists"] is True
    assert summary["gui_current_revision_view_bundle_manifest_exists"] is True

    receipt = server._change_receipt_gui_current_revision(current)
    assert receipt["view_audit_report_path"] == str(view_audit_path)
    assert receipt["view_audit_report_path_source"] == "diagnostics"
    assert receipt["report_json_path"] == str(report_json_path)
    assert receipt["report_json_path_source"] == "diagnostics"
    assert receipt["view_bundle_manifest_path"] == str(view_bundle_manifest_path)
    assert receipt["view_bundle_manifest_path_source"] == "artifacts"


