def test_live_gui_acceptance_separates_visual_review_from_window_binding() -> None:
    report = {
        "execution_mode": "execute",
        "execution_mode_source": "explicit_live_intent",
        "user_request": "Build a semiconductor MOS stack and hot-load it in Materials Studio.",
        "gui": {
            "hot_loaded": True,
            "loaded_current_revision": True,
            "window_identity_verification": "verified",
            "visual_validation": "warning",
            "snapshot_path": "C:\\ms\\warning.bmp",
            "snapshot_viewport_likely_visible_model": False,
            "snapshot_viewport_capture_limitation_possible": True,
            "single_window_policy_ok": True,
            "single_window_violation_reasons": [],
        },
        "live_hotload_preflight": {
            "current_revision_loaded": True,
            "single_window_policy_ok": True,
            "single_window_violation_reasons": [],
        },
    }

    acceptance = server._live_gui_acceptance_summary(report)

    assert acceptance["available"] is True
    assert acceptance["ok"] is False
    assert acceptance["status"] == "visual_review_required"
    assert acceptance["window_binding_ok"] is True
    assert acceptance["visual_review_required"] is True
    assert acceptance["capture_limitation_possible"] is True
    assert acceptance["can_continue_same_window_modeling"] is True
    assert acceptance["can_trust_live_gui_current_revision"] is False
    assert acceptance["binding_failure_count"] == 0
    assert acceptance["binding_failures"] == []
    assert acceptance["visual_failure_count"] == 3
    assert {failure["type"] for failure in acceptance["visual_failures"]} == {
        "gui_visual_validation_not_passed",
        "snapshot_viewport_model_not_visible",
        "snapshot_viewport_capture_limitation_possible",
    }
    assert acceptance["next_action"] == "recapture_or_review_gui_snapshot_for_current_revision"

    report["live_gui_acceptance"] = acceptance
    live_summary = server._live_summary_from_report(report)
