def test_live_session_preflight_warns_when_latest_project_gui_window_is_stale(monkeypatch, tmp_path: Path) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))
    monkeypatch.setattr(server, "runner", FakeRunner())

    created = server.material_studio_live_modeling_request("Build silicon crystal.", working_dir=str(tmp_path))
    assert created["ok"] is True
    planned_structure = Path(created["planned_outputs"]["structure"])
    planned_structure.parent.mkdir(parents=True, exist_ok=True)
    planned_structure.write_text("data_current\n", encoding="utf-8")
    old_structure = tmp_path / "old_revision.cif"
    old_structure.write_text("data_old\n", encoding="utf-8")
    controller = MaterialsStudioGuiController(tmp_path, backend=backend)
    wrapper = controller._create_project_wrapper(
        old_structure.resolve(),
        project_id=created["project_id"],
        revision=created["revision"] + 1,
    )
    backend.window = WindowInfo(
        handle=404,
        title=f"{wrapper['project_name']} - Materials Studio",
        pid=2222,
        rect=(0, 0, 1024, 768),
    )

    result = server.material_studio_live_session_preflight(working_dir=str(tmp_path))

    assert result["ok"] is True
    assert result["state"] == "ready_for_live_edit_gui_review"
    assert result["recommended_tool"] == "material_studio_gui_open_structure"
    assert result["recommended_action"] == "reload_latest_project_structure_in_gui_and_snapshot"
    latest_gui = result["latest_project_gui"]
    assert latest_gui["available"] is True
    assert latest_gui["evaluation_active"] is True
    assert latest_gui["loaded_current_revision"] is False
    assert latest_gui["matching_window_count"] == 0
    assert latest_gui["selected_window_matches_current"] is False
    assert latest_gui["foreground_window_matches_current"] is False
    assert "selected_window_revision_does_not_match_current_revision" in latest_gui["selected_window_stale_reasons"]
    assert "latest_project_not_loaded_in_gui" in result["review_reasons"]
    assert "latest_project_selected_window_stale" in result["review_reasons"]
    assert "latest_project_foreground_window_stale" in result["review_reasons"]
    assert result["readiness"]["latest_project_gui_loaded"] is False
    assert result["next_action_plan"]["action_id"] == "reload_latest_project_structure_in_gui"
    assert result["next_action_plan"]["recommended_tool"] == "material_studio_gui_open_structure"
    assert result["next_action_plan"]["needs_user_confirmation"] is True
    assert result["next_action_plan"]["safe_to_call_without_confirmation"] is False
    assert result["next_action_plan"]["payload_hint"] == {
        "structure_path": str(planned_structure),
        "project_id": created["project_id"],
        "revision": created["revision"],
        "take_snapshot": True,
        "export_view_audit": True,
        "reuse_existing_window_only": True,
        "working_dir": str(tmp_path.resolve()),
    }
    assert result["visible_followup_contract"]["visible_followup_ready"] is False
    assert result["visible_followup_contract"]["visible_followup_status"] == "needs_current_revision_reload"
    assert result["visible_followup_contract"]["visible_followup_blocking_reasons"] == [
        "current_revision_not_loaded_in_gui"
    ]
    assert result["visible_followup_contract"]["visible_followup_recommended_tool"] == "material_studio_gui_open_structure"
    assert result["visible_followup_contract"]["visible_followup_payload_hint"] == result["next_action_plan"]["payload_hint"]
    assert result["visible_followup_ready"] is False
    assert result["visible_followup_status"] == "needs_current_revision_reload"
    assert result["mcp_visible_followup_status"] == "needs_current_revision_reload"
    assert result["mcp_visible_followup_payload_hint"] == result["next_action_plan"]["payload_hint"]

    stale_status = server.material_studio_live_project_status(
        created["project_id"],
        include_gui_status=True,
        working_dir=str(tmp_path),
    )
    assert stale_status["ok"] is True
    assert stale_status["gui_current_revision"]["status"] == "not_hot_loaded"
    assert stale_status["gui_current_revision"]["loaded_current_revision"] is False
    assert stale_status["gui_current_revision"]["needs_reload"] is True
    assert stale_status["gui_current_revision"]["recommended_tool"] == "material_studio_gui_open_structure"
    assert stale_status["gui_current_revision"]["payload_hint"] == {
        "structure_path": str(planned_structure),
        "project_id": created["project_id"],
        "revision": created["revision"],
        "take_snapshot": True,
        "export_view_audit": True,
        "reuse_existing_window_only": True,
        "working_dir": str(tmp_path.resolve()),
    }
    assert "selected_window_revision_does_not_match_current_revision" in stale_status["gui_current_revision"]["stale_reasons"]
    assert stale_status["live_summary"]["gui_current_revision_status"] == "not_hot_loaded"
    assert stale_status["live_summary"]["gui_current_revision_needs_reload"] is True
    stale_client = stale_status["mcp_client_readiness"]
    assert stale_client["visible_followup_ready"] is False
    assert stale_client["visible_followup_status"] == "needs_current_revision_reload"
    assert stale_client["visible_followup_blocking_reasons"] == ["current_revision_not_loaded_in_gui"]
    assert stale_client["visible_followup_recommended_tool"] == "material_studio_gui_open_structure"
    assert stale_client["visible_followup_recommended_action"] == "reload_current_revision_in_gui_and_snapshot"
    assert stale_client["visible_followup_payload_hint"] == stale_status["gui_current_revision"]["payload_hint"]
    assert stale_status["live_gui_window_binding"]["ready_for_next_live_edit"] is False
    assert stale_status["live_gui_window_binding"]["visible_followup_status"] == "needs_current_revision_reload"
    assert (
        stale_status["live_gui_window_binding"]["visible_followup_payload_hint"]
        == stale_status["gui_current_revision"]["payload_hint"]
    )
    stale_receipt_gui = stale_status["modeling_report"]["change_receipt"]["gui_current_revision"]
    assert stale_receipt_gui["status"] == "not_hot_loaded"
    assert stale_receipt_gui["loaded_current_revision"] is False
    assert stale_receipt_gui["needs_reload"] is True
    assert stale_receipt_gui["recommended_tool"] == "material_studio_gui_open_structure"
    assert stale_receipt_gui["payload_hint"] == stale_status["gui_current_revision"]["payload_hint"]

    reopened = server.material_studio_gui_open_structure(
        **result["next_action_plan"]["payload_hint"]
    )

    assert reopened["ok"] is True
    assert reopened["structured_sync"]["persisted"] is True
    assert reopened["structured_sync"]["project_id"] == created["project_id"]
    assert reopened["structured_sync"]["revision"] == created["revision"]
    assert Path(reopened["report_json_path"]).exists()
    assert Path(reopened["view_audit_report_path"]).exists()
    assert Path(reopened["view_bundle_manifest_path"]).exists()
    assert reopened["modeling_report"]["gui"]["hot_loaded"] is True
    assert reopened["modeling_report"]["gui"]["opened_structure_path"] == str(planned_structure)
    report_payload = json.loads(Path(reopened["report_json_path"]).read_text(encoding="utf-8"))
    assert report_payload["gui_open"]["structure_path"] == str(planned_structure)
    assert report_payload["gui_artifacts"][0]["type"] == "gui_open"

    status = server.material_studio_live_project_status(
        created["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
    )
    assert status["ok"] is True
    assert status["modeling_report"]["gui"]["hot_loaded"] is True
    assert status["modeling_report"]["gui"]["opened_structure_path"] == str(planned_structure)
    assert status["structure_path"] == str(planned_structure)
    assert status["structure_exists"] is True
    assert status["gui_open_method"] == reopened["gui_open"]["open_result"]["method"]
    assert status["gui_open_path"] == reopened["gui_open"]["open_result"]["path"]
    assert status["gui_opened_structure_path"] == str(planned_structure)
    assert status["gui_project_wrapper_path"] == reopened["gui_open"]["project_wrapper"]["project_path"]
    assert status["gui_project_wrapper_document_path"] == reopened["gui_open"]["project_wrapper"]["document_path"]
    assert status["current_model_structure_path"] == str(planned_structure)
    assert status["mcp_current_model_structure_path"] == str(planned_structure)
    assert status["gui_current_revision"]["status"] == "current_and_visually_verified"
    assert status["gui_current_revision"]["loaded_current_revision"] is True
    assert status["gui_current_revision"]["needs_reload"] is False
    assert status["gui_current_revision"]["needs_snapshot"] is False
    assert status["live_summary"]["gui_current_revision_status"] == "current_and_visually_verified"
    assert status["live_summary"]["gui_current_revision_loaded"] is True
    assert status["live_summary"]["gui_current_revision_needs_reload"] is False
    status_receipt_gui = status["modeling_report"]["change_receipt"]["gui_current_revision"]
    assert status_receipt_gui["status"] == "current_and_visually_verified"
    assert status_receipt_gui["loaded_current_revision"] is True
    assert status_receipt_gui["needs_reload"] is False
    assert status_receipt_gui["needs_snapshot"] is False
    assert status["outputs"]["report_json_exists"] is True


def test_live_project_status_marks_persisted_hotload_stale_when_gui_window_missing(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    assert result["ok"] is True
    assert result["modeling_report"]["gui_current_revision"]["status"] == "current_and_visually_verified"

    backend.window = None
    status = server.material_studio_live_project_status(
        result["project_id"],
        include_gui_status=True,
        working_dir=str(tmp_path),
    )

    assert status["ok"] is True
    assert status["modeling_report"]["gui"]["window_found"] is False
    assert status["gui_current_revision"]["status"] == "stale_or_not_current"
    assert status["gui_current_revision"]["loaded_current_revision"] is False
    assert status["gui_current_revision"]["needs_reload"] is True
    assert status["gui_current_revision"]["recommended_tool"] == "material_studio_gui_open_structure"
    assert "gui_window_not_found" in status["gui_current_revision"]["stale_reasons"]
    assert status["gui_current_revision"]["payload_hint"] == {
        "structure_path": result["planned_outputs"]["structure"],
        "project_id": result["project_id"],
        "revision": result["revision"],
        "take_snapshot": True,
        "export_view_audit": True,
        "reuse_existing_window_only": True,
        "working_dir": str(tmp_path.resolve()),
    }
    assert status["live_summary"]["gui_current_revision_status"] == "stale_or_not_current"
    assert status["live_summary"]["gui_current_revision_needs_reload"] is True
    receipt_gui = status["modeling_report"]["change_receipt"]["gui_current_revision"]
    assert receipt_gui["status"] == "stale_or_not_current"
    assert "gui_window_not_found" in receipt_gui["stale_reasons"]
    assert receipt_gui["payload_hint"] == status["gui_current_revision"]["payload_hint"]


