def test_gui_open_structure_does_not_sync_omitted_project_id_when_structure_mismatches_latest(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))
    monkeypatch.setattr(server, "runner", FakeRunner())

    created = server.material_studio_live_modeling_request("Build silicon crystal.", working_dir=str(tmp_path))
    assert created["ok"] is True
    other_structure = tmp_path / "other.cif"
    other_structure.write_text("data_other\n", encoding="utf-8")

    opened = server.material_studio_gui_open_structure(
        str(other_structure),
        take_snapshot=False,
        working_dir=str(tmp_path),
    )

    assert opened["ok"] is True
    assert opened["structured_sync_context"]["available"] is False
    assert opened["structured_sync_context"]["reason"] == "latest_current_planned_structure_mismatch"
    assert opened["structured_sync_context"]["latest_project_id"] == created["project_id"]
    assert "structured_sync" not in opened
    assert "report_json_path" not in opened
    assert opened["project_id"] is None
    assert opened["revision"] is None


