def test_live_status_and_preflight_recover_invalid_current_pointer_read_only(
    tmp_path: Path,
) -> None:
    spec = load_benzene("live_status_recovered_current")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    assert created["ok"] is True
    current_path = Path(created["state"]["current_path"])
    invalid_pointer = b'{"project_id":"live_status_recovered_current","spec":'
    current_path.write_bytes(invalid_pointer)

    status = server.material_studio_live_project_status(
        include_gui_status=False,
        working_dir=str(tmp_path),
        response_mode="compact",
    )

    assert status["ok"] is True
    assert status["project_id"] == "live_status_recovered_current"
    assert status["revision"] == 0
    resolution = status["project_resolution"]
    assert resolution["source"] == "latest_current"
    assert resolution["current_pointer_status"] == "recovered_invalid_current_pointer"
    assert resolution["current_pointer_valid"] is False
    assert resolution["current_pointer_recovery_used"] is True
    assert resolution["current_read_source"] == "latest_valid_revision"
    assert resolution["current_pointer"]["recovery_is_read_only"] is True
    assert resolution["current_pointer"]["repair_required"] is True
    assert current_path.read_bytes() == invalid_pointer

    full_status = server.material_studio_live_project_status(
        project_id=created["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
    )
    assert full_status["ok"] is True
    assert full_status["project_resolution"]["source"] == "explicit"
    assert full_status["current"]["status"] == "recovered_invalid_current_pointer"
    assert full_status["current"]["recovery_used"] is True
    assert full_status["current"]["recovery_is_read_only"] is True
    assert full_status["current"]["repair_required"] is True
    assert full_status["current"]["safe_to_continue_read_only"] is True
    assert full_status["current"]["next_successful_revision_write_repairs_pointer"] is True
    assert full_status["current"]["resolved_revision_path"].endswith(
        "r000_model_spec.json"
    )
    assert full_status["current"]["read_error"]
    assert current_path.read_bytes() == invalid_pointer

    preflight = server.material_studio_live_session_preflight(
        working_dir=str(tmp_path),
        include_latest_project=True,
        include_gui_status=False,
    )
    assert preflight["ok"] is True
    assert preflight["readiness"]["latest_project_available"] is True
    latest = preflight["latest_project"]
    assert latest["project_id"] == created["project_id"]
    assert latest["current_pointer_status"] == "recovered_invalid_current_pointer"
    assert latest["current_pointer_recovery_used"] is True
    assert latest["current_pointer"]["recovery_is_read_only"] is True
    assert current_path.read_bytes() == invalid_pointer
    history = server.material_studio_project_history(working_dir=str(tmp_path))
    assert history["ok"] is True
    assert len(history["history"]) == 1
    assert history["project_resolution"]["current_pointer_recovery_used"] is True


def test_live_modeling_request_inspects_current_model_status(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build silicon crystal.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert created["ok"] is True
    assert created["execution_mode"] == "preview"

    inspected = server.material_studio_live_modeling_request(
        "Is the current model normal?",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert inspected["ok"] is True
    assert inspected["workflow"] == "inspect_current"
    assert inspected["diagnostic_export_requested"] is True
    assert inspected["normality_check_requested"] is True
    assert Path(inspected["view_bundle_manifest_path"]).exists()
    assert inspected["view_bundle_row_counts"]["view_projections"] == 48
    assert inspected["view_bundle_row_counts"]["view_quality"] == 6
    assert Path(inspected["view_bundle_files"]["view_quality_csv"]).exists()
    assert inspected["project_id"] == created["project_id"]
    assert inspected["revision"] == created["revision"]
    assert inspected["nl_plan"]["kind"] == "inspect_current"
    assert inspected["nl_plan"]["template_id"] == "inspect_current_revision"
    assert inspected["modeling_health"]["verdict"] in {"ready_for_review", "ready_with_warnings"}
    assert inspected["modeling_report"]["workflow"] == "inspect_current"
    assert inspected["modeling_report"]["diagnostic_export_requested"] is True
    assert inspected["modeling_report"]["normality_check_requested"] is True
    assert inspected["modeling_report"]["change_receipt"]["diagnostic_export_requested"] is True
    assert inspected["modeling_report"]["change_receipt"]["normality_check_requested"] is True
    assert inspected["live_summary"]["diagnostic_export_requested"] is True
    assert inspected["live_summary"]["view_bundle_manifest_path"] == inspected["view_bundle_manifest_path"]
    assert inspected["live_summary"]["view_quality_csv"] == inspected["view_bundle_files"]["view_quality_csv"]
    assert inspected["modeling_report"]["normality"] in {"preview_ready", "review_warnings"}
    assert inspected["computed_audit_summary"]["view_count"] == 6
    status = server.material_studio_live_project_status(created["project_id"], include_gui_status=False, working_dir=str(tmp_path))
    assert status["ok"] is True
    assert status["workflow"] == "inspect_current"
    assert status["project_resolution"]["source"] == "explicit"
    assert status["live_summary"]["project_resolution"]["source"] == "explicit"
    assert status["normality_check_requested"] is True
    assert status["live_summary"]["normality_check_requested"] is True
    assert status["view_bundle_row_counts"]["view_quality"] == 6
    assert Path(status["view_bundle_files"]["view_quality_csv"]).exists()
    history = server.material_studio_project_history(created["project_id"], working_dir=str(tmp_path))
    assert [item["revision"] for item in history["history"]] == [created["revision"]]

    compact_status = server.material_studio_live_project_status(
        created["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    assert compact_status["ok"] is True
    assert compact_status["workflow"] == "inspect_current"
    assert compact_status["visual_normality_summary"]["recommended_view_name"] in {
        "front",
        "top",
        "isometric",
        "crystal_plane_100",
        "crystal_plane_110",
        "crystal_plane_111",
    }
    assert compact_status["visual_clean_view_available"] is True
    assert compact_status["visual_clean_view_count"] >= 1


