    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build an AlGaN/GaN HEMT heterostructure.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert created["ok"] is True
    assert created["workflow"] == "create"
    assert created["execution_mode"] == "preview"
    assert created["revision"] == 0

    inspected = server.material_studio_live_modeling_request(
        (
            "\u7ed9\u5f53\u524d\u6a21\u578b\u505a\u5efa\u6a21\u8d28\u91cf\u4f53\u68c0\uff0c"
            "\u5bfc\u51fa2DEG\u8bca\u65ad\u548c\u5404\u79cd\u89c6\u89d2\u53c2\u6570"
        ),
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert inspected["ok"] is True
    assert inspected["workflow"] == "inspect_current"
    assert inspected["project_id"] == created["project_id"]
    assert inspected["revision"] == created["revision"]
    assert inspected["diagnostic_export_requested"] is True
    assert inspected["normality_check_requested"] is True
    assert inspected["nl_plan"]["kind"] == "inspect_current"
    assert inspected["nl_plan"]["template_id"] == "export_current_diagnostics"
    user_focuses = [
        "iii_nitride_hemt_2deg",
        "semiconductor_structure_health",
        "view_quality",
    ]
    auto_focuses = [
        "electronic_structure_preflight",
        "quantum_well_heterostructure",
        "band_alignment",
        "epitaxial_strain_preflight",
        "alloy_composition_preflight",
    ]
    expected_focuses = user_focuses + auto_focuses
    assert inspected["requested_diagnostic_focuses"] == expected_focuses
    assert inspected["modeling_report"]["auto_completed_diagnostic_focuses"] == auto_focuses
    assert inspected["diagnostic_focus_plan"]["user_requested_focuses"] == user_focuses
    assert inspected["diagnostic_focus_plan"]["auto_completed_focuses"] == auto_focuses
    assert inspected["requested_diagnostic_focus_ok"] is True
    assert inspected["modeling_report"]["requested_diagnostic_focus_status"]["ok"] is True
    focus_names = [focus["focus"] for focus in inspected["modeling_report"]["requested_diagnostic_focus_status"]["focuses"]]
    assert focus_names == expected_focuses
    focus_sources = {
        focus["focus"]: focus
        for focus in inspected["modeling_report"]["requested_diagnostic_focus_status"]["focuses"]
    }
    assert [focus_sources[focus]["source"] for focus in user_focuses] == ["user_request"] * 3
    assert [focus_sources[focus]["source"] for focus in auto_focuses] == ["auto_completed"] * 5
    hemt_focus = inspected["modeling_report"]["requested_diagnostic_focus_status"]["focuses"][0]
    assert "semiconductor_polarization_2deg_csv" in hemt_focus["existing_csv_keys"]
    assert "semiconductor_review.polarization_2deg" in hemt_focus["available_summary_keys"]
    health_focus = inspected["modeling_report"]["requested_diagnostic_focus_status"]["focuses"][1]
    assert "semiconductor_composition_csv" in health_focus["existing_csv_keys"]
    assert "inspection.semiconductor_health.local_environment_summary" in health_focus["available_summary_keys"]
    assert inspected["view_bundle_row_counts"]["semiconductor_polarization_2deg"] == 1
    assert inspected["view_bundle_row_counts"]["semiconductor_composition"] == 3
    assert inspected["view_bundle_row_counts"]["view_quality"] == 7
    assert inspected["view_bundle_row_counts"]["requested_diagnostic_focus_status"] == 8
    assert Path(inspected["view_bundle_files"]["semiconductor_polarization_2deg_csv"]).exists()
    assert Path(inspected["view_bundle_files"]["semiconductor_composition_csv"]).exists()
    assert Path(inspected["view_bundle_files"]["view_quality_csv"]).exists()
    assert Path(inspected["view_bundle_files"]["requested_diagnostic_focus_status_json"]).exists()
    assert inspected["live_summary"]["requested_diagnostic_focuses"] == expected_focuses
    assert inspected["live_summary"]["auto_completed_diagnostic_focuses"] == auto_focuses
    assert inspected["live_summary"]["requested_diagnostic_focus_ok"] is True
    assert inspected["live_summary"]["normality_check_requested"] is True
    assert inspected["live_summary"]["semiconductor_polarization_2deg_quality"] == "complete"

    status = server.material_studio_live_project_status(created["project_id"], include_gui_status=False, working_dir=str(tmp_path))
    assert status["ok"] is True
    assert status["workflow"] == "inspect_current"
    assert status["normality_check_requested"] is True
    assert status["requested_diagnostic_focuses"] == expected_focuses
    assert status["modeling_report"]["auto_completed_diagnostic_focuses"] == auto_focuses
    history = server.material_studio_project_history(created["project_id"], working_dir=str(tmp_path))
    assert [item["revision"] for item in history["history"]] == [created["revision"]]


