def test_gui_visual_validation_warns_when_model_viewport_looks_blank() -> None:
    analysis = {
        "readable": True,
        "likely_nonblank": True,
        "viewport_likely_visible_model": False,
        "viewport_foreground_ratio": 0.0,
        "viewport_background_ratio": 1.0,
        "viewport_capture_limitation_possible": True,
        "viewport_capture_diagnostic": "uniform_dark_viewport_surface",
        "warnings": [],
    }

    assert server._gui_visual_validation(analysis, True, None) == "warning"
    health = build_modeling_health(
        {
            "validation": {"valid": True},
            "result": {"success": True},
            "gui_open": {
                "window": {"title": "Materials Studio"},
                "snapshot": {"analysis": analysis},
            },
        },
        execution_mode="execute",
    )
    assert health["checks"]["snapshot_viewport_likely_visible_model"] is False
    assert health["checks"]["snapshot_viewport_foreground_ratio"] == 0.0
    assert health["checks"]["snapshot_viewport_capture_limitation_possible"] is True
    assert health["checks"]["snapshot_viewport_capture_diagnostic"] == "uniform_dark_viewport_surface"
    assert "GUI snapshot viewport does not show a visible model." in health["warnings"]
    assert "GUI snapshot may be limited by GDI/OpenGL viewport capture." in health["warnings"]

    readiness = server._live_readiness_summary(
        {
            "ok": True,
            "health_ok": True,
            "script_valid": True,
            "execution_mode": "execute",
            "normality": "review_warnings",
            "structure": {"exists": True},
            "gui": {
                "hot_loaded": True,
                "visual_validation": "warning",
                "snapshot_viewport_likely_visible_model": False,
                "snapshot_viewport_capture_limitation_possible": True,
            },
        }
    )
    assert "gui_visual_validation_warning" in readiness["review_reasons"]
    assert "gui:viewport_model_not_visible" in readiness["visual_review_reasons"]
    assert "gui:viewport_capture_limitation_possible" in readiness["visual_review_reasons"]


def test_modeling_health_downgrades_snapshot_capture_warnings_after_external_visual_confirmation(
    tmp_path: Path,
) -> None:
    structure = tmp_path / "structure_r000.cif"
    structure.write_text("data_confirmed\n", encoding="utf-8")
    analysis = {
        "readable": True,
        "likely_nonblank": True,
        "viewport_likely_visible_model": False,
        "viewport_capture_limitation_possible": True,
        "warnings": [
            "Central model viewport appears blank or not fit-to-view; the model may not be visually visible.",
            "Central model viewport is a uniform dark surface; in Materials Studio 20.x this can also indicate GDI/BitBlt did not capture the OpenGL 3D viewport.",
        ],
    }

    health = build_modeling_health(
        {
            "ok": True,
            "validation": {"valid": True},
            "planned_outputs": {"structure": str(structure)},
            "result": {"success": True},
            "gui_open": {
                "window": {"title": "Materials Studio"},
                "project_id": "visual_confirmed",
                "revision": 0,
                "structure_path": str(structure),
                "snapshot": {"analysis": analysis},
            },
            "gui_artifacts": [
                {
                    "type": "visual_confirmation",
                    "project_id": "visual_confirmed",
                    "revision": 0,
                    "source": "computer_use",
                    "model_visible": True,
                }
            ],
        },
        execution_mode="execute",
    )

    assert health["checks"]["snapshot_viewport_likely_visible_model"] is False
    assert health["checks"]["snapshot_viewport_capture_limitation_possible"] is True
    assert health["checks"]["external_visual_confirmation_ok"] is True
    assert "GUI snapshot viewport does not show a visible model." in health["warnings"]
    assert "GUI snapshot may be limited by GDI/OpenGL viewport capture." in health["warnings"]
    assert health["verdict"] == "passed"
    assert health["checks"]["verdict_warning_count"] == 0
    assert health["verdict_warnings"] == []


