def test_gui_apply_current_revision_execute_opens_output(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    def fake_execute_structured_script(*, store, spec, script, timeout_seconds):
        output = store.project_dir(spec.project_id) / "outputs" / f"r{spec.revision:03d}" / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text("fake xsd", encoding="utf-8")
        return {"result": {"success": True, "created_files": [str(output)]}, "result_metadata_path": str(output.parent / "result_metadata.json")}

    monkeypatch.setattr(server, "_execute_structured_script", fake_execute_structured_script)

    spec = load_benzene("gui_execute_proj")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    assert created["ok"] is True

    executed = server.material_studio_gui_apply_current_revision(
        "gui_execute_proj",
        execution_mode="execute",
        working_dir=str(tmp_path),
    )

    assert executed["ok"] is True
    assert executed["result"]["success"] is True
    execution_transaction = executed["execution_transaction"]
    assert execution_transaction["scope"] == "project_revision"
    assert execution_transaction["domain"] == "revision_execution"
    assert execution_transaction["project_id"] == "gui_execute_proj"
    assert execution_transaction["revision"] == 0
    assert execution_transaction["current_revision_at_start"] == 0
    assert execution_transaction["current_revision_after_execution"] == 0
    assert execution_transaction["current_revision_still_current"] is True
    assert execution_transaction["execution_started"] is True
    assert execution_transaction["execution_completed"] is True
    assert execution_transaction["path"].endswith("revision_execution.lock")
    assert {
        "revision_execution",
        "immutable_revision_binding",
        "current_revision_revalidation",
        "materials_script_execution",
        "result_metadata_publish",
    } <= set(execution_transaction["coverage"])
    assert executed["result"]["execution_transaction"] == execution_transaction
    execution_attempt = executed["execution_attempt"]
    assert execution_attempt["sequence"] == 1
    assert execution_attempt["backend"] == "materials_script"
    assert execution_attempt["status"] == "completed"
    assert execution_attempt["result_success"] is True
    assert execution_attempt["current_revision_still_current"] is True
    assert Path(executed["execution_attempt_state_path"]).exists()
    assert Path(executed["execution_attempt_events_path"]).exists()
    persisted_result = json.loads(
        Path(executed["result_metadata_path"]).read_text(encoding="utf-8")
    )
    assert persisted_result["execution_transaction"] == execution_transaction
    assert persisted_result["execution_attempt"] == execution_attempt
    status = server.material_studio_live_project_status(
        project_id=executed["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
    )
    assert status["execution_runtime"]["status"] == "completed"
    assert status["execution_runtime"]["active"] is False
    assert status["execution_runtime"]["latest_attempt"] == execution_attempt
    assert status["execution_runtime"]["journal"]["event_count"] == 2
    compact_status = server.material_studio_live_project_status(
        project_id=executed["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
        response_mode="compact",
    )
    assert compact_status["execution_attempt"]["attempt_id"] == execution_attempt[
        "attempt_id"
    ]
    assert compact_status["execution_attempt"]["sequence"] == 1
    assert compact_status["execution_attempt"]["status"] == "completed"
    assert compact_status["execution_attempt"]["spec_sha256"] == execution_attempt[
        "spec_sha256"
    ]
    assert compact_status["execution_runtime"]["status"] == "completed"
    assert compact_status["execution_runtime"]["latest_attempt"]["attempt_id"] == (
        execution_attempt["attempt_id"]
    )
    assert compact_status["execution_continuation"]["automatic_retry_allowed"] is False
    assert executed["modeling_health"]["verdict"] == "passed"
    assert executed["modeling_health"]["checks"]["gui_loaded_current_revision"] is True
    assert executed["modeling_health"]["checks"]["gui_stale_reasons"] == []
    assert executed["modeling_health"]["checks"]["gui_open_identity_verification"] == "matched_open_artifact"
    assert executed["modeling_health"]["checks"]["gui_window_identity_verification"] == "unverified"
    assert "gui_open" in executed
    high_level_transaction = executed["gui_action_transaction"]
    assert high_level_transaction["path"] == executed["report_write_transaction"]["path"]
    assert high_level_transaction["nested_call_count"] == 0
    assert {
        "high_level_hotload",
        "workflow:gui_apply_current_revision",
        "target_window_revalidation",
        "gui_open_structure",
        "gui_snapshot",
        "report_read_modify_write",
    } <= set(high_level_transaction["coverage"])
    assert executed["modeling_report"]["normality"] == "review_warnings"
    normality_gate = executed["modeling_report"]["normality_gate"]
    assert normality_gate["status"] == "review_required"
    assert normality_gate["can_claim_model_normal"] is False
    assert normality_gate["can_claim_live_gui_normal"] is False
    assert "gui:window_identity_unverified" in normality_gate["must_not_claim_normal_reasons"]
    assert executed["normality_gate"] == normality_gate
    assert executed["live_summary"]["normality_gate_status"] == "review_required"
    assert executed["live_summary"]["can_claim_live_gui_normal"] is False
