def test_gui_apply_current_revision_execute_refuses_multiple_windows_before_running(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = MultiWindowFakeGuiBackend()
    backend.windows = [
        backend.window,
        WindowInfo(handle=404, title="Extra - Materials Studio", pid=2222, rect=(20, 20, 1024, 768)),
    ]
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )
    calls: list[str] = []

    def fake_execute_structured_script(*, store, spec, script, timeout_seconds):
        calls.append(spec.project_id)
        output = store.project_dir(spec.project_id) / "outputs" / f"r{spec.revision:03d}" / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text("fake xsd", encoding="utf-8")
        return {"result": {"success": True, "created_files": [str(output)]}}

    monkeypatch.setattr(server, "_execute_structured_script", fake_execute_structured_script)

    spec = load_benzene("gui_execute_blocked_multiwindow_proj")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    assert created["ok"] is True

    executed = server.material_studio_gui_apply_current_revision(
        "gui_execute_blocked_multiwindow_proj",
        execution_mode="execute",
        working_dir=str(tmp_path),
    )

    assert executed["ok"] is False
    assert calls == []
    assert backend.opened == []
    assert "result" not in executed
    assert "gui_open" not in executed
    assert executed["single_window_hotload_block"]["reason"] == "single_window_policy_violation"
    assert executed["single_window_hotload_block"]["single_window_violation_reasons"] == [
        "multiple_matstudio_windows_detected"
    ]
    readiness = executed["modeling_report"]["live_readiness"]
    assert readiness["state"] == "blocked"
    assert "gui_single_window_policy_violation" in readiness["blocking_reasons"]


