def test_live_update_recovers_invalid_latest_pointer_with_gap_safe_revision(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )
    spec = load_benzene("live_patch_pointer_recovery")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    project_dir = Path(created["state"]["project_dir"])
    current_path = Path(created["state"]["current_path"])
    orphan = project_dir / "revisions" / "r001_model_spec.json"
    orphan_bytes = b'{"orphan":'
    orphan.write_bytes(orphan_bytes)
    current_path.write_bytes(b'{"broken":')

    updated = server.material_studio_live_update_with_patch(
        patch={"operations": [{"type": "delete_atom", "atom_id": "H1"}]},
        user_text="Delete H1 and prepare preview.",
        open_in_gui=False,
        take_snapshot=False,
        export_view_audit=False,
        working_dir=str(tmp_path),
        response_mode="compact",
    )

    assert updated["ok"] is True
    assert updated["project_id"] == created["project_id"]
    assert updated["project_resolution"]["source"] == "latest_current"
    assert updated["project_resolution"]["current_pointer_recovery_used"] is True
    assert updated["base_revision"] == 0
    assert updated["new_revision"] == 2
    assert updated["revision_delta"]["new_revision"] == 2
    assert "r002" in updated["planned_outputs"]["structure"]
    assert updated["current_pointer_repaired"] is True
    assert updated["current_pointer_after_write"]["status"] == "valid"
    assert updated["current_pointer_after_write"]["revision"] == 2
    assert orphan.read_bytes() == orphan_bytes
    assert json.loads(current_path.read_text(encoding="utf-8"))["revision"] == 2
    history = server.material_studio_project_history(
        created["project_id"],
        working_dir=str(tmp_path),
    )
    assert [event["revision"] for event in history["history"]] == [0, 2]


def test_live_update_with_patch_preview_writes_view_audit(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    spec = load_benzene("live_preview_proj")
