def test_live_update_with_patch_stale_base_returns_recovery_contract(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    spec = load_benzene("live_patch_stale_base_proj")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    assert created["ok"] is True

    first = server.material_studio_live_update_with_patch(
        project_id="live_patch_stale_base_proj",
        base_revision=0,
        patch={"operations": [{"type": "set_atom_position", "atom_id": "H1", "xyz_angstrom": [2.6, 0, 0]}]},
        working_dir=str(tmp_path),
    )
    assert first["ok"] is True
    assert first["revision"] == 1

    stale = server.material_studio_live_update_with_patch(
        project_id="live_patch_stale_base_proj",
        base_revision=0,
        patch={"operations": [{"type": "set_atom_position", "atom_id": "H2", "xyz_angstrom": [-2.6, 0, 0]}]},
        user_text="move H2 after refreshing the current live model",
        working_dir=str(tmp_path),
    )

    assert stale["ok"] is False
    assert stale["workflow"] == "live_patch"
    assert stale["project_id"] == "live_patch_stale_base_proj"
    assert stale["revision"] == 1
    assert "base_revision" in stale["error"]
    contract = stale["live_modeling_contract"]
    assert contract["status"] == "patch_apply_failed"
    assert contract["workflow_stages"]["failed_required_stages"] == ["model_spec"]
    assert contract["next_action"]["recommended_tool"] == "material_studio_live_update_with_patch"
    assert contract["next_action"]["recommended_action"] == "refresh_current_revision_and_retry_patch"
    assert contract["next_action"]["payload_hint"]["project_id"] == "live_patch_stale_base_proj"
    assert contract["next_action"]["payload_hint"]["base_revision"] == 1
    assert contract["current_model_context"]["available"] is True
    assert contract["current_model_context"]["base_revision_for_next_patch"] == 1
    assert contract["current_model_context"]["model_type"] == "molecule"
    assert contract["followup_edit_capabilities"]["available"] is True
    assert contract["followup_edit_capabilities"]["base_revision"] == 1
    assert contract["followup_edit_capabilities"]["recommended_tool"] == "material_studio_live_update_with_patch"
    assert contract["followup_edit_capabilities"]["patch_payload_hint"]["tool"] == "material_studio_live_update_with_patch"


def test_modeling_report_marks_revision_delta_audit_mismatch(tmp_path: Path) -> None:
    response = {
        "ok": True,
        "project_id": "delta_mismatch_proj",
        "revision": 1,
        "execution_mode": "preview",
        "modeling_health": {"ok": True, "verdict": "ready_for_review", "errors": [], "warnings": []},
        "revision_delta": {
            "available": True,
            "project_id": "delta_mismatch_proj",
            "base_revision": 0,
            "new_revision": 1,
            "atom_count_after": 2,
            "element_counts_after": {"C": 1, "N": 1},
            "molecule": {
                "added_atoms": [{"atom_id": "N1", "element": "N", "xyz_angstrom": [1.0, 0.0, 0.0]}],
                "deleted_atoms": [],
                "substituted_atoms": [],
                "moved_atoms": [],
                "bond_count_after": 0,
                "added_bonds": [],
                "deleted_bonds": [],
                "changed_bond_types": [],
            },
        },
        "view_audit": {
            "model_type": "molecule",
            "model": {"atom_count": 1, "bond_count": 0, "elements": {"C": 1}},
            "atoms": [{"id": "C1", "element": "C", "xyz_angstrom": [0.0, 0.0, 0.0]}],
            "health": {"ok": True, "bond_lengths_angstrom": []},
            "views": [],
        },
    }

    report = server._build_modeling_report(response)

    assert report["change_validation"]["available"] is True
    assert report["change_validation"]["ok"] is False
    checks = {item["name"]: item for item in report["change_validation"]["checks"]}
    assert checks["atom_count_after_matches_audit"]["passed"] is False
    assert checks["element_counts_after_match_audit"]["passed"] is False
    assert checks["added_atoms_present"]["passed"] is False
    assert checks["added_atoms_present"]["mismatches"] == [{"atom_id": "N1", "reason": "missing"}]
    assert report["change_verification"]["available"] is True
    assert report["change_verification"]["ok"] is False
    assert report["change_verification"]["status"] == "failed"
    assert "added_atoms_present" in report["change_verification"]["change_validation_failed_checks"]
    assert report["change_receipt"]["change_verification"] == report["change_verification"]
    assert report["change_receipt"]["change_verification_ok"] is False
    assert report["change_receipt"]["health_check"]["change_verification_ok"] is False
    assert "change_validation_failed" in report["live_readiness"]["blocking_reasons"]
    assert "change_verification_failed" in report["live_readiness"]["blocking_reasons"]
    assert report["live_readiness"]["change_verification_ok"] is False
    assert report["live_readiness"]["change_verification_status"] == "failed"
    assert "change_verification_failed" in report["normality_gate"]["must_not_claim_normal_reasons"]
    assert report["normality_gate"]["change_verification_ok"] is False
    assert report["normality_gate"]["change_verification_status"] == "failed"
    assert report["normality_explanation"]["evidence"]["change_verification_ok"] is False
    assert report["normality_explanation"]["evidence"]["change_verification_status"] == "failed"
    assert report["live_summary"]["change_verification_status"] == "failed"
    assert report["normality"] == "review_warnings"


def test_modeling_report_blocks_when_acceptance_warning_limit_fails() -> None:
    response = {
        "ok": True,
        "project_id": "acceptance_warning_proj",
        "revision": 0,
        "execution_mode": "preview",
        "acceptance": {"max_warnings": 0, "require_convergence": False, "notes": ["strict"]},
        "modeling_health": {
            "ok": True,
            "verdict": "ready_with_warnings",
            "errors": [],
            "warnings": ["Bond length review required."],
            "checks": {"verdict_warning_count": 1},
        },
    }

    report = server._build_modeling_report(response)

    acceptance_review = report["acceptance_review"]
    assert acceptance_review["available"] is True
    assert acceptance_review["ok"] is False
    assert acceptance_review["warning_count"] == 1
    assert acceptance_review["raw_warning_count"] == 1
    assert acceptance_review["failed_checks"] == ["warning_count_within_acceptance"]
    assert report["normality"] == "review_warnings"
    readiness = report["live_readiness"]
    assert readiness["state"] == "preview_ready_with_review"
    assert readiness["ready_for_hotload"] is True
    assert readiness["ready_for_calculation"] is False
    assert readiness["acceptance_ok"] is False
    assert "acceptance_criteria_failed" not in readiness["blocking_reasons"]
    assert "acceptance_criteria_failed" in readiness["review_reasons"]
    assert "acceptance_criteria_failed" in readiness["calculation_blocking_reasons"]


def test_modeling_report_blocks_when_acceptance_requires_convergence() -> None:
    response = {
        "ok": True,
        "project_id": "acceptance_convergence_proj",
        "revision": 0,
        "execution_mode": "execute",
        "acceptance": {"max_warnings": 1, "require_convergence": True, "notes": []},
        "modeling_health": {
            "ok": True,
            "verdict": "completed",
            "errors": [],
            "warnings": [],
            "checks": {"verdict_warning_count": 0},
        },
        "result": {"parsed_json": {"converged": "not_converged"}},
        "planned_outputs": {"structure": "missing.xsd"},
    }

    report = server._build_modeling_report(response)

    acceptance_review = report["acceptance_review"]
    assert acceptance_review["available"] is True
    assert acceptance_review["ok"] is False
    assert acceptance_review["convergence"]["converged"] is False
    assert acceptance_review["failed_checks"] == ["convergence_required"]
    assert report["normality"] == "review_warnings"
    readiness = report["live_readiness"]
    assert readiness["state"] == "blocked"
    assert readiness["acceptance_ok"] is False
    assert "acceptance_criteria_failed" not in readiness["blocking_reasons"]
    assert "acceptance_criteria_failed" in readiness["review_reasons"]
    assert "acceptance_criteria_failed" in readiness["calculation_blocking_reasons"]
    assert "executed_structure_missing" in readiness["blocking_reasons"]


def test_modeling_report_marks_critical_view_review_problem() -> None:
    response = {
        "ok": True,
        "project_id": "bad_view_proj",
        "revision": 0,
        "execution_mode": "preview",
        "modeling_health": {"ok": True, "verdict": "ready_for_review", "errors": [], "warnings": []},
        "view_audit": {
            "model_type": "molecule",
            "model": {"atom_count": 2, "bond_count": 0, "elements": {"H": 2}},
            "atoms": [
                {"id": "H1", "element": "H", "xyz_angstrom": [0.0, 0.0, 0.0]},
                {"id": "H2", "element": "H", "xyz_angstrom": [0.8, 0.0, 0.0]},
            ],
            "health": {"ok": True, "bond_lengths_angstrom": []},
            "views": [
                {"name": "front", "supported": False, "warning": "Unknown view name."},
                {
                    "name": "top",
                    "supported": True,
                    "atom_projection_count": 1,
                    "atom_projections_truncated": False,
                    "projection_span_angstrom": {"x": 0.0, "y": 0.0, "depth": 0.0},
                    "projection_bbox_angstrom": {"x": [0.0, 0.0], "y": [0.0, 0.0], "depth": [0.0, 0.0]},
                    "overlap_candidates": [],
                    "framing": {"orthographic_width_angstrom": 1.0, "orthographic_height_angstrom": 1.0},
                    "health": {"ok": False, "warnings": ["Projected structure is nearly degenerate in this view."]},
                },
            ],
        },
    }

    report = server._build_modeling_report(response)

    view_review = report["view_review"]
    assert view_review["available"] is True
    assert view_review["ok"] is False
    assert view_review["status"] == "failed"
    assert {"unsupported_views", "projection_atom_count_mismatch"} <= set(view_review["critical_flags"])
    assert "degenerate_projection_views" in view_review["risk_flags"]
    readiness = report["live_readiness"]
    assert readiness["state"] == "blocked"
    assert readiness["ready_for_hotload"] is False
    assert readiness["recommended_tool"] == "material_studio_live_project_status"
    assert "view:unsupported_views" in readiness["blocking_reasons"]
    assert "view:projection_atom_count_mismatch" in readiness["blocking_reasons"]
    assert report["normality"] == "review_warnings"


def test_live_update_with_patch_execute_opens_gui(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    def fake_execute_structured_script(*, store, spec, script, timeout_seconds):
        output = store.project_dir(spec.project_id) / "outputs" / f"r{spec.revision:03d}" / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text("fake live xsd", encoding="utf-8")
        return {"result": {"success": True, "created_files": [str(output)]}, "result_metadata_path": str(output.parent / "result_metadata.json")}

    monkeypatch.setattr(server, "_execute_structured_script", fake_execute_structured_script)

    spec = load_benzene("live_execute_proj")
    created = server.material_studio_model_create_from_spec(spec, working_dir=str(tmp_path))
    assert created["ok"] is True

    patch = {"operations": [{"type": "set_atom_position", "atom_id": "H1", "xyz_angstrom": [2.6, 0, 0]}]}
    updated = server.material_studio_live_update_with_patch(
        "live_execute_proj",
        0,
        patch,
        execution_mode="execute",
        working_dir=str(tmp_path),
    )

    assert updated["ok"] is True
    assert updated["result"]["success"] is True
    assert updated["modeling_health"]["verdict"] == "passed"
    assert updated["new_revision"] == 1
    assert updated["revision"] == 1
    assert "gui_open" in updated
    high_level_transaction = updated["gui_action_transaction"]
    assert high_level_transaction["path"] == updated["report_write_transaction"]["path"]
    assert high_level_transaction["nested_call_count"] == 0
    assert {
        "high_level_hotload",
        "workflow:live_patch",
        "target_window_revalidation",
        "gui_open_structure",
        "gui_snapshot",
        "report_read_modify_write",
    } <= set(high_level_transaction["coverage"])
    assert backend.opened
    assert backend.opened[0].name == "live_execute_proj_r001.xsd"


