def test_live_modeling_request_exports_comprehensive_parameters_for_4h_sic_mos(tmp_path: Path) -> None:
    result = server.material_studio_live_modeling_request(
        "\u6784\u5efa4H-SiC MOS\u7535\u5bb9\u5e76\u5bfc\u51fa\u5404\u79cd\u89c6\u89d2\u6a21\u578b\u53c2\u6570"
        "\u68c0\u67e5\u5efa\u6a21\u662f\u5426\u6b63\u5e38",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["template_id"] == "aluminum_silicon_dioxide_silicon_carbide_4h_mos_capacitor"
    user_focuses = [
        "comprehensive_model_parameters",
        "semiconductor_structure_health",
        "view_quality",
    ]
    auto_focuses = [
        "electronic_structure_preflight",
        "mos_gate_stack",
        "epitaxial_strain_preflight",
    ]
    expected_focuses = user_focuses + auto_focuses
    assert result["requested_diagnostic_focuses"] == expected_focuses
    assert result["modeling_report"]["auto_completed_diagnostic_focuses"] == auto_focuses
    assert result["diagnostic_focus_plan"]["user_requested_focuses"] == user_focuses
    assert result["diagnostic_focus_plan"]["auto_completed_focuses"] == auto_focuses
    assert result["requested_diagnostic_focus_ok"] is True
    assert result["requested_diagnostic_focus_status"]["missing_csv_keys"] == []
    assert result["requested_diagnostic_focus_status"]["missing_summary_keys"] == []
    comprehensive = result["modeling_report"]["requested_diagnostic_focus_status"]["focuses"][0]
    assert comprehensive["focus"] == "comprehensive_model_parameters"
    assert "semiconductor_band_path_csv" in comprehensive["existing_csv_keys"]
    focus_by_id = {
        focus["focus"]: focus
        for focus in result["modeling_report"]["requested_diagnostic_focus_status"]["focuses"]
    }
    electronic_focus = focus_by_id["electronic_structure_preflight"]
    assert "inspection.semiconductor_health.band_path_summary" in electronic_focus["available_summary_keys"]
    band_path = result["modeling_report"]["inspection"]["semiconductor_health"]["band_path_summary"]
    assert band_path["available"] is False
    assert band_path["requires_materials_studio_review"] is True
    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    assert semiconductor["surface_model_summary"] is None
    assert semiconductor["surface_termination_summary"] is None
    assert semiconductor["surface_polarity_summary"] is None
    assert result["modeling_report"]["inspection"]["slab_vacuum"] is None
    risk_flags = set(result["modeling_report"]["semiconductor_review"]["risk_flags"])
    assert "surface_model_not_ready" not in risk_flags
    assert "slab_not_centered" not in risk_flags
    assert "slab_vacuum_review" not in risk_flags
    calculation_readiness = result["modeling_report"]["semiconductor_calculation_readiness"]
    assert calculation_readiness["surface_model_blocked"] is False
    assert calculation_readiness.get("primary_blocking_reason") != "semiconductor:surface_model_not_ready"
    assert not result["modeling_report"]["diagnostics"].get("semiconductor_surface_model_csv")
    assert not result["view_bundle_files"].get("semiconductor_surface_model_csv")
    assert Path(result["view_bundle_files"]["semiconductor_band_path_csv"]).exists()
    assert Path(result["view_bundle_files"]["modeling_report_summary_csv"]).exists()
    assert "mos_gate_stack" in result["recommended_diagnostic_focuses"]
    assert "mos_gate_stack" not in result["unrequested_recommended_diagnostic_focuses"]


