def test_live_modeling_request_infers_al_si_schottky_contact_template(tmp_path: Path) -> None:
    result = server.material_studio_live_modeling_request(
        "Build an Al/Si Schottky contact.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["template_id"] == "aluminum_silicon_100_schottky_contact"
    assert result["view_audit"]["model"]["name"] == "aluminum_silicon_100_schottky_contact"
    assert result["view_audit"]["model"]["atom_count"] == 16
    assert result["view_audit"]["model"]["elements"] == {"Al": 8, "Si": 8}

    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    assert semiconductor["interface_quality_summary"]["quality"] == "complete"
    assert semiconductor["interface_quality_summary"]["material_sequence"] == ["Si", "Al"]
    assert semiconductor["quantum_well_summary"] is None
    assert semiconductor["surface_termination_summary"] is None
    contact = semiconductor["metal_semiconductor_contact_summary"]
    assert contact["quality"] == "complete"
    assert contact["contact_type"] == "schottky"
