def test_live_modeling_request_applies_inline_silicon_schottky_contact_modifiers(tmp_path: Path) -> None:
    au_contact = server.material_studio_live_modeling_request(
        "Build an Au/Si Schottky contact and export contact diagnostics.",
        working_dir=str(tmp_path / "au_contact"),
    )

    assert au_contact["ok"] is True
    assert au_contact["workflow"] == "create"
    assert au_contact["execution_mode"] == "preview"
    assert au_contact["diagnostic_export_requested"] is True
    assert au_contact["nl_plan"]["template_id"] == "aluminum_silicon_100_schottky_contact"
    assert au_contact["view_audit"]["model"]["elements"] == {"Au": 8, "Si": 8}
    au_metadata = au_contact["view_audit"]["metadata"]
    assert au_metadata["interface"] == "Au/Si"
    assert au_metadata["metal_contact_material"] == "Au"
    assert au_metadata["metal_work_function_ev"] == 5.1
    assert au_metadata["last_contact_metal_replacement"]["replaced_atom_count"] == 8
    assert any(
        item.startswith("substitute_atom AlContact1->Au")
        for item in au_metadata["nl_composite_operations"]
    )
    au_summary = au_contact["modeling_report"]["inspection"]["semiconductor_health"]["metal_semiconductor_contact_summary"]
    assert au_summary["metal_material"] == "Au"
    assert au_summary["material_sequence"] == ["Si", "Au"]
    assert au_summary["sequence_matches_expected"] is True
    assert au_summary["contact_geometry_status"] == "matched"
    assert au_summary["barrier_preflight"]["ideal_n_type_barrier_ev"] == 1.05
    assert au_contact["live_summary"]["semiconductor_contact_sequence"] == ["Si", "Au"]
    assert au_contact["live_summary"]["semiconductor_contact_ideal_n_type_barrier_ev"] == 1.05

    pt_gap = server.material_studio_live_modeling_request(
        "Build a Pt/Si Schottky contact with interface gap 3.0 angstrom and export contact diagnostics.",
        working_dir=str(tmp_path / "pt_contact"),
    )

    assert pt_gap["ok"] is True
    assert pt_gap["workflow"] == "create"
    assert pt_gap["execution_mode"] == "preview"
    assert pt_gap["nl_plan"]["template_id"] == "aluminum_silicon_100_schottky_contact"
    assert pt_gap["view_audit"]["model"]["elements"] == {"Pt": 8, "Si": 8}
    pt_metadata = pt_gap["view_audit"]["metadata"]
    assert pt_metadata["interface"] == "Pt/Si"
    assert pt_metadata["metal_contact_material"] == "Pt"
    assert pt_metadata["metal_work_function_ev"] == 5.65
    assert pt_metadata["interface_gap_angstrom"] == 3.0
    assert pt_metadata["last_contact_gap_adjustment"]["moved_atom_count"] == 8
    assert "set_metadata interface_gap_angstrom,last_contact_gap_adjustment,last_contact_parameter_update" in pt_metadata[
        "nl_composite_operations"
    ]
    pt_summary = pt_gap["modeling_report"]["inspection"]["semiconductor_health"]["metal_semiconductor_contact_summary"]
    assert pt_summary["metal_material"] == "Pt"
    assert pt_summary["material_sequence"] == ["Si", "Pt"]
    assert abs(pt_summary["actual_contact_gap_angstrom"] - 3.0) < 1e-4
    assert abs(pt_summary["contact_gap_delta_angstrom"]) < 1e-4
    assert pt_summary["contact_geometry_status"] == "matched"
    assert pt_summary["barrier_preflight"]["ideal_n_type_barrier_ev"] == 1.6
    assert abs(pt_gap["live_summary"]["semiconductor_contact_actual_gap_angstrom"] - 3.0) < 1e-4
    assert pt_gap["live_summary"]["semiconductor_contact_geometry_status"] == "matched"


