    assert gap_shift["workflow"] == "patch"
    assert gap_shift["execution_mode"] == "preview"
    assert gap_shift["nl_plan"]["template_id"] == "metal_semiconductor_contact_gap"
    assert gap_shift["new_revision"] == 4
    assert gap_shift["view_audit"]["metadata"]["interface_gap_angstrom"] == 3.2
    assert gap_shift["view_audit"]["metadata"]["last_contact_gap_adjustment"]["moved_atom_count"] == 8
    moved_atom = next(atom for atom in gap_shift["view_audit"]["atoms"] if atom["id"] == "AlContact1")
    assert moved_atom["fractional"] == [0.0, 0.0, 0.464286]
    gap_contact = gap_shift["modeling_report"]["inspection"]["semiconductor_health"]["metal_semiconductor_contact_summary"]
    assert gap_contact["declared_contact_gap_angstrom"] == 3.2
    assert abs(gap_contact["actual_contact_gap_angstrom"] - 3.2) < 1e-4
    assert abs(gap_contact["contact_gap_delta_angstrom"]) < 1e-4
    assert gap_contact["contact_geometry_status"] == "matched"
    assert "metal_semiconductor_contact_gap_mismatch" not in gap_shift["modeling_report"]["semiconductor_review"]["risk_flags"]
    assert gap_contact["metal_material"] == "Au"
    assert gap_contact["barrier_preflight"]["ideal_n_type_barrier_ev"] == 1.1
    assert gap_shift["live_summary"]["semiconductor_contact_sequence"] == ["Si", "Au"]

    thickness_shift = server.material_studio_live_modeling_request(
        "Set metal contact thickness to 2.8 angstrom and export contact diagnostics.",
        project_id=created["project_id"],
        working_dir=str(tmp_path),
    )

    assert thickness_shift["ok"] is True
    assert thickness_shift["workflow"] == "patch"
    assert thickness_shift["execution_mode"] == "preview"
    assert thickness_shift["nl_plan"]["template_id"] == "metal_semiconductor_contact_thickness"
    assert thickness_shift["new_revision"] == 5
    assert thickness_shift["view_audit"]["metadata"]["metal_contact_thickness_angstrom"] == 2.8
    assert thickness_shift["view_audit"]["metadata"]["last_contact_thickness_adjustment"]["moved_atom_count"] == 8
    bottom_atom = next(atom for atom in thickness_shift["view_audit"]["atoms"] if atom["id"] == "AlContact1")
    top_atom = next(atom for atom in thickness_shift["view_audit"]["atoms"] if atom["id"] == "AlContact5")
    assert bottom_atom["fractional"] == [0.0, 0.0, 0.464286]
    assert top_atom["fractional"] == [0.0, 0.5, 0.564286]
    thick_contact = thickness_shift["modeling_report"]["inspection"]["semiconductor_health"]["metal_semiconductor_contact_summary"]
    assert thick_contact["declared_contact_gap_angstrom"] == 3.2
    assert abs(thick_contact["actual_contact_gap_angstrom"] - 3.2) < 1e-4
    assert thick_contact["declared_metal_thickness_angstrom"] == 2.8
    assert abs(thick_contact["actual_metal_thickness_angstrom"] - 2.8) < 1e-4
    assert abs(thick_contact["metal_thickness_delta_angstrom"]) < 1e-4
    assert thick_contact["contact_geometry_status"] == "matched"
    assert "metal_semiconductor_contact_thickness_mismatch" not in thickness_shift["modeling_report"]["semiconductor_review"]["risk_flags"]
    assert thick_contact["metal_material"] == "Au"
    assert thickness_shift["live_summary"]["semiconductor_contact_sequence"] == ["Si", "Au"]
