    assert "inspection.semiconductor_health.surface_model_summary" in surface_focus["available_summary_keys"]
    assert "inspection.semiconductor_health.surface_polarity_summary" in surface_focus["available_summary_keys"]
    assert "inspection.semiconductor_health.layer_profile_summary" in surface_focus["available_summary_keys"]
    assert "inspection.slab_vacuum" in surface_focus["available_summary_keys"]
