    assert "semiconductor_surface_termination_csv" in surface_focus["existing_csv_keys"]
    assert "semiconductor_surface_polarity_csv" in surface_focus["existing_csv_keys"]
    assert "semiconductor_layer_profile_csv" in surface_focus["existing_csv_keys"]
