    assert Path(surface_focus["artifacts"]["semiconductor_surface_termination_csv"]).exists()
    assert Path(surface_focus["artifacts"]["semiconductor_surface_polarity_csv"]).exists()
    assert Path(surface_focus["artifacts"]["semiconductor_layer_profile_csv"]).exists()
