    assert semiconductor["surface_termination_summary"]["termination"] == "unpassivated"
    assert semiconductor["surface_termination_summary"]["surface_preparation_status"] == "dangling_bonds"
    assert semiconductor["surface_polarity_summary"]["surface_axis"] == "c"
    assert semiconductor["surface_polarity_summary"]["surface_polarity_status"] == "symmetric_nonpolar"
