    assert inspection["slab_vacuum"]["slab_vacuum_status"] == "off_center"
    assert result["live_summary"]["semiconductor_slab_vacuum_status"] == "off_center"
    assert result["live_summary"]["semiconductor_surface_preparation_status"] == "dangling_bonds"
    assert result["live_summary"]["semiconductor_surface_polarity_status"] == "symmetric_nonpolar"
