    assert calculation_readiness["safe_to_call_without_confirmation"] is True
    assert calculation_readiness["payload_hint"]["project_id"] == result["project_id"]
    assert calculation_readiness["payload_hint"]["execution_mode"] == "preview"
    assert calculation_readiness["payload_hint"]["open_in_gui"] is False
    assert "fully hydrogen passivate both surfaces" in calculation_readiness["payload_hint"]["user_request"]
    assert calculation_readiness["action_context"]["surface_model_status"] == "blocked"
    assert result["next_action_plan"]["action_id"] == "fix_semiconductor_surface_model"
    assert result["next_action_plan"]["recommended_tool"] == "material_studio_live_modeling_request"
    assert result["next_action_plan"]["payload_hint"] == calculation_readiness["payload_hint"]
    assert result["live_action_summary"]["phase"] == "fix_semiconductor_surface_model"
    assert result["live_summary"]["semiconductor_calculation_readiness_status"] == "blocked"
    assert result["live_summary"]["semiconductor_calculation_readiness_ready"] is False
    assert result["live_summary"]["semiconductor_calculation_readiness_action_id"] == "fix_semiconductor_surface_model"
    assert (
        result["live_summary"]["semiconductor_calculation_readiness_recommended_tool"]
        == "material_studio_live_modeling_request"
    )
    assert result["semiconductor_calculation_readiness"] == calculation_readiness
    assert result["semiconductor_calculation_readiness_status"] == "blocked"
    assert result["semiconductor_calculation_readiness_ready"] is False
    assert result["semiconductor_calculation_readiness_action_id"] == "fix_semiconductor_surface_model"
    assert result["semiconductor_calculation_readiness_recommended_tool"] == "material_studio_live_modeling_request"
    assert result["semiconductor_calculation_readiness_needs_user_confirmation"] is False
    assert result["semiconductor_calculation_readiness_safe_to_call_without_confirmation"] is True
    assert result["semiconductor_calculation_readiness_primary_blocking_reason"] == (
        "semiconductor:surface_model_not_ready"
    )
    assert result["semiconductor_calculation_readiness_payload_hint"] == calculation_readiness["payload_hint"]
    assert (
        result["live_summary"]["semiconductor_slab_vacuum_next_action"]
        == "center_slab_or_review_asymmetric_vacuum_before_claiming_normality"
    )
    assert result["live_summary"]["requested_diagnostic_focus_ok"] is True
    assert result["view_bundle_row_counts"]["requested_diagnostic_focus_status"] == 2
    summary_rows = list(csv.DictReader(Path(result["view_bundle_files"]["modeling_report_summary_csv"]).open(encoding="utf-8")))
