def test_live_modeling_request_infers_tmd_monolayer_template(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build MoS2 monolayer semiconductor for 2D modeling.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["kind"] == "spec"
    assert result["nl_plan"]["template_id"] == "molybdenum_disulfide_2d_mos2_monolayer"
    assert result["view_audit"]["model"]["name"] == "molybdenum_disulfide_2d_mos2_monolayer"
    assert result["view_audit"]["model"]["elements"] == {"Mo": 4, "S": 8}
    current = server.material_studio_model_get_current(result["project_id"], working_dir=str(tmp_path))
    assert current["spec"]["metadata"]["domain"] == "semiconductor"
    assert current["spec"]["metadata"]["structure_family"] == "2d tmd monolayer"
    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    assert semiconductor["ok"] is True
    assert semiconductor["rule"] == "tmd_layered_trigonal_prismatic"
    assert semiconductor["expected_coordination"] is None
    assert semiconductor["expected_coordination_by_element"] == {"Mo": 6, "S": 3}
    assert semiconductor["neighbor_pair_counts"] == {"Mo-S": 24}
    assert semiconductor["unexpected_neighbor_pair_count"] == 0
    assert semiconductor["sublattice_balance_summary"]["balance_kind"] == "tmd_metal_chalcogen_ratio"
    assert semiconductor["sublattice_balance_summary"]["balanced"] is True
    assert result["modeling_health"]["checks"]["semiconductor_tmd_metal_count"] == 4
    assert result["modeling_health"]["checks"]["semiconductor_tmd_chalcogen_count"] == 8
    review = result["modeling_report"]["semiconductor_review"]
    assert review["available"] is True
    assert review["ok"] is True
    assert review["structure_family"] == "2d tmd monolayer"
    assert review["expected_coordination_by_element"] == {"Mo": 6, "S": 3}
    assert review["reduced_formula"] == "MoS2"
    assert review["kpoints"]["band_path"]["bravais_lattice"] == "hexagonal"
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_local_environment_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_sublattice_balance_csv"]).exists()


def test_live_modeling_request_infers_common_2d_tmd_monolayer_templates(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    cases = [
        (
            "Build WS2 monolayer semiconductor for 2D modeling.",
            "tungsten_disulfide_2d_ws2_monolayer",
            {"W": 4, "S": 8},
            {"W": 6, "S": 3},
            {"W-S": 24},
            "WS2",
        ),
        (
            "Build MoSe2 monolayer semiconductor for 2D modeling.",
            "molybdenum_diselenide_2d_mose2_monolayer",
            {"Mo": 4, "Se": 8},
            {"Mo": 6, "Se": 3},
            {"Mo-Se": 24},
            "MoSe2",
        ),
        (
            "构建 WSe2 单层并准备预览",
            "tungsten_diselenide_2d_wse2_monolayer",
            {"W": 4, "Se": 8},
            {"W": 6, "Se": 3},
            {"W-Se": 24},
            "WSe2",
        ),
    ]
    for index, (request, template_id, elements, expected_coordination, neighbor_pairs, formula) in enumerate(cases, start=1):
        result = server.material_studio_live_modeling_request(
            request,
            working_dir=str(tmp_path / f"tmd_{index}"),
        )

        assert result["ok"] is True, {"request": request, "template_id": template_id, "error": result.get("error")}
        assert result["execution_mode"] == "preview"
        assert len(result["project_id"]) <= 40
        assert result["nl_plan"]["template_id"] == template_id
        assert result["view_audit"]["model"]["elements"] == elements
        semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
        assert semiconductor["ok"] is True
        assert semiconductor["rule"] == "tmd_layered_trigonal_prismatic"
        assert semiconductor["expected_coordination_by_element"] == expected_coordination
        assert semiconductor["neighbor_pair_counts"] == neighbor_pairs
        assert semiconductor["coordination_outlier_count"] == 0
        assert result["modeling_report"]["semiconductor_review"]["reduced_formula"] == formula
        assert Path(result["modeling_report"]["diagnostics"]["semiconductor_local_environment_csv"]).exists()


def test_live_modeling_request_patches_tmd_dopant_and_vacancy(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build MoS2 monolayer semiconductor.",
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True

    doped = server.material_studio_live_modeling_request(
        "Dope with Cl.",
        working_dir=str(tmp_path),
    )

    assert doped["ok"] is True
    assert doped["workflow"] == "patch"
    assert doped["nl_plan"]["template_id"] == "crystal_auto_dopant"
    assert doped["project_resolution"]["project_id"] == created["project_id"]
    semiconductor = doped["modeling_report"]["inspection"]["semiconductor_health"]
    dopant_site = semiconductor["dopant_site_summary"]
    assert semiconductor["rule"] == "doped_tmd_layered_trigonal_prismatic"
    assert semiconductor["expected_coordination_by_element"] == {"Cl": 3, "Mo": 6, "S": 3}
    assert semiconductor["unexpected_neighbor_pair_count"] == 0
    assert dopant_site["carrier_type_hint"] == "donor_like_n_type"
    assert dopant_site["latest"]["site_family"] == "tmd_chalcogen"
    assert dopant_site["latest"]["site_element"] == "S"
    assert dopant_site["latest"]["dopant_element"] == "Cl"
    assert dopant_site["latest"]["role_hint"] == "donor_like_n_type_on_tmd_chalcogen_site"
    assert doped["modeling_health"]["checks"]["semiconductor_dopant_site_carrier_type_hint"] == "donor_like_n_type"
    assert Path(doped["modeling_report"]["diagnostics"]["semiconductor_dopant_sites_csv"]).exists()

    vacancy = server.material_studio_live_modeling_request(
        "Create S vacancy.",
        working_dir=str(tmp_path),
    )

    assert vacancy["ok"] is True
    assert vacancy["workflow"] == "patch"
    assert vacancy["nl_plan"]["template_id"] == "crystal_auto_vacancy"
    defect = vacancy["modeling_report"]["inspection"]["semiconductor_health"]["defect_summary"]
    assert defect["vacancy_count"] == 1
    assert defect["defects"][0]["site_element"] == "S"
    assert defect["defects"][0]["expected_neighbor_count"] == 3
    assert vacancy["modeling_health"]["checks"]["semiconductor_defect_count"] == 1
    assert Path(vacancy["modeling_report"]["diagnostics"]["semiconductor_defects_csv"]).exists()


