    assert result["modeling_health"]["checks"]["semiconductor_superlattice_layers_per_period"] == 8.0
    assert result["modeling_health"]["checks"]["semiconductor_quantum_well_period_count"] == 3
    assert result["modeling_health"]["checks"]["semiconductor_quantum_well_segment_count"] == 6
    assert result["modeling_health"]["checks"]["semiconductor_quantum_well_mean_well_thickness_angstrom"] == 5.654286
    assert result["modeling_health"]["checks"]["semiconductor_quantum_well_mean_barrier_thickness_angstrom"] == 5.660113
    assert result["modeling_health"]["checks"]["semiconductor_interface_quality"] == "complete"
    assert result["modeling_health"]["checks"]["semiconductor_interface_period_sequence_complete"] is True
    assert result["modeling_health"]["checks"]["semiconductor_interface_transition_sequence_complete"] is True
    assert result["modeling_health"]["checks"]["semiconductor_formula"] == "Al12Ga12As24"
    assert result["modeling_health"]["checks"]["semiconductor_reduced_formula"] == "AlGaAs2"
    assert Path(result["modeling_report"]["diagnostics"]["modeling_health_summary_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_composition_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_layer_profile_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_interface_quality_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_quantum_well_csv"]).exists()
    health_summary_csv = Path(result["modeling_report"]["diagnostics"]["modeling_health_summary_csv"]).read_text(encoding="utf-8")
    assert "semiconductor_interface_quality" in health_summary_csv
    assert "ready_with_warnings" in health_summary_csv
    assert "Al12Ga12As24" in health_summary_csv


