def test_live_modeling_request_hotloads_chinese_ingaas_inp_quantum_well_with_in_fraction(
    monkeypatch, tmp_path: Path
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "\u6784\u5efaInGaAs/InP\u91cf\u5b50\u9631\uff0cIn\u542b\u91cf53%\uff0c"
        "\u70ed\u52a0\u8f7d\u5e76\u5bfc\u51fa\u89c6\u89d2\u53c2\u6570\u68c0\u67e5\u662f\u5426\u6b63\u5e38\u3002",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "execute"
    assert result["execution_mode_source"] == "explicit_live_intent"
    assert result["diagnostic_export_requested"] is True
    assert result["normality_check_requested"] is True
    user_focuses = ["quantum_well_heterostructure", "view_quality"]
    auto_focuses = [
        "semiconductor_structure_health",
        "electronic_structure_preflight",
        "band_alignment",
        "epitaxial_strain_preflight",
        "alloy_composition_preflight",
    ]
    assert result["requested_diagnostic_focuses"] == user_focuses + auto_focuses
    assert result["modeling_report"]["auto_completed_diagnostic_focuses"] == auto_focuses
    assert result["diagnostic_focus_plan"]["user_requested_focuses"] == user_focuses
    assert result["diagnostic_focus_plan"]["auto_completed_focuses"] == auto_focuses
    assert result["nl_plan"]["template_id"] == "indium_gallium_arsenide_indium_phosphide_001_heterostructure"
    assert result["view_audit"]["model"]["elements"] == {"As": 24, "Ga": 11, "In": 37, "P": 24}
    assert result["result"]["execution_backend"] == "crystal_cif_materialize"
    assert result["gui_open"]["structure_path"].endswith(".cif")
    assert backend.opened and backend.opened[-1].suffix == ".cif"

    metadata = result["view_audit"]["metadata"]
    assert metadata["materials"] == ["In0.53Ga0.47As", "InP"]
    assert metadata["interface"] == "In0.53Ga0.47As/InP"
    assert metadata["formula_alloy_request"] == {
        "formula": "In0.53Ga0.47As",
        "host_element": "Ga",
        "alloy_element": "In",
        "requested_fraction": 0.53,
        "source": "natural_language_iii_v_heterostructure_formula_alloy",
    }
    alloy = metadata["last_applied_alloy"]
    assert alloy["candidate_site_count"] == 24
    assert alloy["substituted_site_count"] == 13
    assert alloy["actual_fraction"] == 0.541667
    assert not any("Barrier" in atom_id for atom_id in alloy["selected_atom_ids"])
    assert not any("InBarrier" in diff for diff in metadata["nl_composite_operations"])

    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    quantum_well = semiconductor["quantum_well_summary"]
    assert quantum_well["well_material"] == "In0.53Ga0.47As"
    assert quantum_well["barrier_materials"] == ["InP"]
    assert quantum_well["well_cation_fractions_by_material"] == {
        "In0.53Ga0.47As": {"Ga": 0.458333, "In": 0.541667}
    }
    assert quantum_well["barrier_cation_fractions_by_material"] == {"InP": {"In": 1.0}}
    assert result["modeling_health"]["checks"]["semiconductor_quantum_well_barrier_materials"] == ["InP"]
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_quantum_well_csv"]).exists()
    assert result["modeling_report"]["normality"] in {"hot_loaded_and_passed", "review_warnings"}


