def test_live_modeling_request_builds_composite_semiconductor_supercell_dopant(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal as a 2x1x1 supercell and dope Si1_000 with P, then hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "execute"
    assert result["nl_plan"]["kind"] == "spec"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["view_audit"]["model"]["atom_count"] == 16
    assert result["view_audit"]["model"]["elements"] == {"P": 1, "Si": 15}
    assert result["view_audit"]["model"]["lattice"]["a"] == 10.862
    assert result["view_audit"]["metadata"]["nl_composite_operations"] == [
        "make_supercell 2x1x1",
        "substitute_atom Si1_000->P",
        "set_metadata last_semiconductor_dopant_site,semiconductor_dopant_sites",
    ]
    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    assert semiconductor["expected_coordination"] == 4
    assert semiconductor["rule"] == "doped_group_iv_tetrahedral"
    assert semiconductor["dopant_summary"]["host_elements"] == ["Si"]
    assert semiconductor["dopant_summary"]["dopant_elements"] == ["P"]
    assert semiconductor["dopant_summary"]["dopants"][0]["role_hint"] == "donor_like_n_type_for_group_iv_host"
    assert semiconductor["dopant_summary"]["dopants"][0]["coordination_stats"]["min"] == 4.0
    concentration = semiconductor["dopant_concentration_summary"]
    assert concentration["total_dopant_density_cm3"] > 3.0e21
    assert concentration["concentration_warning_level"] == "very_high"
    assert concentration["degenerate_doping_review_required"] is True
    assert concentration["dopants"][0]["carrier_type_hint"] == "donor_like_n_type"
    charge_balance = semiconductor["charge_balance_summary"]
    assert charge_balance["total_valence_electron_count"] == 65
    assert charge_balance["electron_count_parity"] == "odd"
    assert charge_balance["odd_electron_warning"] is True
    assert charge_balance["spin_charge_review_required"] is True
    assert charge_balance["spin_polarization_review_required"] is True
    assert charge_balance["recommended_spin_treatment"] == "review_spin_polarized_calculation_or_explicit_charge_state"
    assert charge_balance["next_action"] == "review_spin_polarization_or_charge_state_before_castep_execution"
    assert charge_balance["carrier_type_hint"] == "donor_like_n_type"
    assert result["modeling_health"]["checks"]["semiconductor_total_valence_electron_count"] == 65
    assert result["modeling_health"]["checks"]["semiconductor_electron_count_parity"] == "odd"
    assert result["modeling_health"]["checks"]["semiconductor_spin_charge_review_required"] is True
    assert result["modeling_health"]["checks"]["semiconductor_recommended_spin_treatment"] == (
        "review_spin_polarized_calculation_or_explicit_charge_state"
    )
    assert result["modeling_health"]["checks"]["semiconductor_charge_balance_next_action"] == (
        "review_spin_polarization_or_charge_state_before_castep_execution"
    )
    assert result["modeling_health"]["checks"]["semiconductor_carrier_type_hint"] == "donor_like_n_type"
    assert result["modeling_health"]["checks"]["semiconductor_finite_size_warning"] is True
    assert result["modeling_health"]["checks"]["semiconductor_finite_size_max_isolated_fraction"] == 0.0625
    assert result["modeling_health"]["checks"]["semiconductor_finite_size_max_isolated_kind"] == "dopant"
    assert result["modeling_health"]["checks"]["semiconductor_total_dopant_density_cm3"] > 3.0e21
    assert result["modeling_health"]["checks"]["semiconductor_dopant_concentration_warning_level"] == "very_high"
    assert result["modeling_health"]["checks"]["semiconductor_degenerate_doping_review_required"] is True
    assert any("nominal valence-electron count is odd" in item for item in result["modeling_health"]["warnings"])
    assert any("finite-size/dilution" in item for item in result["modeling_health"]["warnings"])
    assert any("dopant concentration" in item for item in result["modeling_health"]["warnings"])
    assert result["modeling_report"]["normality"] == "review_warnings"
    receipt = result["modeling_report"]["change_receipt"]
    assert receipt["available"] is True
    assert receipt["workflow"] == "create"
    assert receipt["user_request"].startswith("Build silicon crystal")
    assert receipt["nl_template_id"] == "silicon_diamond"
    assert receipt["revision"] == 0
    assert receipt["execution_mode"] == "execute"
    assert receipt["formula"] == "PSi15"
    assert receipt["dopants"]["dopant_elements"] == ["P"]
    assert receipt["semiconductor"]["formula"] == "PSi15"
    assert receipt["semiconductor"]["dopants"]["dopant_elements"] == ["P"]
    assert receipt["semiconductor"]["calculation"]["module"] == "CASTEP"
    assert receipt["semiconductor"]["kpoints"]["status"] == "ok"
    assert {"dopant_model", "finite_size_or_dilution_warning", "odd_valence_electron_count"} <= set(
        receipt["semiconductor"]["risk_flags"]
    )
    assert receipt["gui_loaded_current_revision"] is True
    assert receipt["gui_visual_validation"] == "snapshot_missing"
    assert receipt["ready_for_next_edit"] is True
    assert receipt["ready_for_calculation"] is False
    assert "semiconductor:odd_valence_electron_count" in receipt["calculation_blocking_reasons"]
    assert "semiconductor:finite_size_or_dilution_warning" in receipt["calculation_blocking_reasons"]
    assert receipt["delta"]["available"] is False
    review = result["modeling_report"]["semiconductor_review"]
    assert review["dopants"]["dopant_elements"] == ["P"]
    assert review["dopants"]["role_hints"] == ["donor_like_n_type_for_group_iv_host"]
    assert review["dopants"]["total_dopant_density_cm3"] > 3.0e21
    assert review["dopants"]["concentration_warning_level"] == "very_high"
    assert review["dopants"]["degenerate_doping_review_required"] is True
    assert review["charge_balance"]["carrier_type_hint"] == "donor_like_n_type"
    assert review["charge_balance"]["spin_charge_review_required"] is True
    assert review["charge_balance"]["recommended_spin_treatment"] == (
        "review_spin_polarized_calculation_or_explicit_charge_state"
    )
    assert {"dopant_model", "finite_size_or_dilution_warning", "odd_valence_electron_count"} <= set(review["risk_flags"])
    assert review["next_action"] == "review_semiconductor_risk_flags_before_calculation_or_claiming_normality"
    calculation_readiness = result["modeling_report"]["semiconductor_calculation_readiness"]
    assert calculation_readiness["action_id"] == "review_semiconductor_spin_charge_state"
    assert calculation_readiness["recommended_tool"] == "material_studio_live_modeling_request"
    assert calculation_readiness["recommended_action"] == "review_spin_polarization_or_charge_state_before_castep_execution"
    assert calculation_readiness["payload_hint"]["execution_mode"] == "preview"
    assert calculation_readiness["payload_hint"]["remediation_intent"] == "spin_charge_state_preflight"
    assert calculation_readiness["payload_hint"]["remediation_operations"] == [
        "review_charge_balance",
        "review_spin_polarization_or_charge_state",
    ]
    assert calculation_readiness["payload_hint"]["required_diagnostic_focuses"] == [
        "electronic_structure_preflight",
        "spin_charge_preflight",
    ]
    assert calculation_readiness["action_context"]["total_valence_electron_count"] == 65
    assert calculation_readiness["action_context"]["recommended_spin_treatment"] == (
        "review_spin_polarized_calculation_or_explicit_charge_state"
    )
    readiness = result["modeling_report"]["live_readiness"]
    assert readiness["ready_for_next_edit"] is True
    assert readiness["ready_for_calculation"] is False
    assert "semiconductor:odd_valence_electron_count" in readiness["review_reasons"]
    assert "semiconductor:finite_size_or_dilution_warning" in readiness["review_reasons"]
    assert "semiconductor:odd_valence_electron_count" in readiness["calculation_blocking_reasons"]
    assert "semiconductor:finite_size_or_dilution_warning" in readiness["calculation_blocking_reasons"]
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_dopants_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_dopant_concentration_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_charge_balance_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_finite_size_csv"]).exists()
    assert result["modeling_report"]["gui"]["hot_loaded"] is True
    assert result["result"]["execution_backend"] == "crystal_cif_materialize"
    assert Path(result["planned_outputs"]["structure"]).exists()
    current = server.material_studio_model_get_current(result["project_id"], working_dir=str(tmp_path))
    assert current["revision"] == 0
    assert current["spec"]["metadata"]["nl_composite_operations"] == [
        "make_supercell 2x1x1",
        "substitute_atom Si1_000->P",
        "set_metadata last_semiconductor_dopant_site,semiconductor_dopant_sites",
    ]


def test_live_update_add_vacuum_receipt_marks_cartesian_positions_preserved(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build silicon crystal for semiconductor modeling.",
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True

    updated = server.material_studio_live_update_with_patch(
        created["project_id"],
        0,
        {"operations": [{"type": "add_vacuum", "axis": "z", "thickness_angstrom": 10.0}]},
        user_text="add 10 angstrom vacuum along z",
        working_dir=str(tmp_path),
    )

    assert updated["ok"] is True
    crystal_delta = updated["revision_delta"]["crystal"]
    assert crystal_delta["lattice_delta"] == {"c": 10.0}
    assert crystal_delta["fractional_coordinate_update_count"] == 6
    assert crystal_delta["cartesian_moved_atom_count"] == 0
    assert crystal_delta["cartesian_preserved_atom_count"] == 6
    assert crystal_delta["max_cartesian_displacement_angstrom"] == 0.0
    assert crystal_delta["fractional_rescale_preserved_cartesian"] is True

    receipt_delta = updated["modeling_report"]["change_receipt"]["delta"]["crystal"]
    assert receipt_delta["lattice_delta"] == {"c": 10.0}
    assert receipt_delta["cartesian_moved_atom_count"] == 0
    assert receipt_delta["cartesian_preserved_atom_count"] == 6
    assert receipt_delta["fractional_rescale_preserved_cartesian"] is True
    assert updated["modeling_report"]["change_validation"]["ok"] is True


