    assert server._requested_views_from_text(
        "\u5bfc\u51fa\u8868\u9762\u6cd5\u5411\u548c\u4e24\u4e2a\u9762\u5185\u89c6\u56fe\u53c2\u6570"
    ) == surface_views
    assert server._requested_views_from_text(
        "Export interface-normal and two interface in-plane views."
    ) == interface_views
    assert server._requested_views_from_text(
        "\u5bfc\u51fa\u754c\u9762\u6cd5\u5411\u548c\u4e24\u4e2a\u9762\u5185\u89c6\u56fe\u53c2\u6570"
    ) == interface_views
