def test_live_modeling_request_exports_comprehensive_model_parameter_focus(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend),
    )

    result = server.material_studio_live_modeling_request(
        "\u6784\u5efa\u7845\u6676\u4f53\u5e76\u5bfc\u51fa\u5b8c\u6574\u6a21\u578b\u53c2\u6570\uff0c"
        "\u68c0\u67e5\u5efa\u6a21\u662f\u5426\u6b63\u5e38\u3002",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    user_focuses = [
        "comprehensive_model_parameters",
        "semiconductor_structure_health",
        "view_quality",
    ]
    auto_focuses = ["electronic_structure_preflight"]
    assert result["requested_diagnostic_focuses"] == user_focuses + auto_focuses
    assert result["modeling_report"]["auto_completed_diagnostic_focuses"] == auto_focuses
    assert result["diagnostic_focus_plan"]["user_requested_focuses"] == user_focuses
    assert result["diagnostic_focus_plan"]["auto_completed_focuses"] == auto_focuses
    assert result["requested_diagnostic_focus_ok"] is True
    focus_status = result["requested_diagnostic_focus_status"]
    assert focus_status["focus_count"] == 4
    assert focus_status["auto_completed_focuses"] == auto_focuses
    assert focus_status["missing_csv_keys"] == []
    assert focus_status["missing_summary_keys"] == []
    comprehensive_focus = focus_status["focuses"][0]
    assert comprehensive_focus["focus"] == "comprehensive_model_parameters"
    assert "modeling_report_summary_csv" in comprehensive_focus["existing_csv_keys"]
    assert "semiconductor_calculation_readiness" in comprehensive_focus["available_summary_keys"]
    assert "semiconductor_normality_diagnosis" in comprehensive_focus["available_summary_keys"]
    assert "semiconductor_normality_diagnosis_json" in comprehensive_focus["existing_csv_keys"]
    assert "semiconductor_normality_diagnosis_csv" in comprehensive_focus["existing_csv_keys"]
    assert result["view_bundle_row_counts"]["requested_diagnostic_focus_status"] == 4
    view_parameters = result["view_parameter_summary"]
    assert view_parameters == result["modeling_report"]["view_parameter_summary"]
    assert result["view_parameter_status"] == view_parameters["status"]
    assert result["view_parameter_view_count"] == view_parameters["view_count"]
    assert result["view_parameter_recommended_view_name"] == view_parameters["recommended_view"]["name"]
    assert view_parameters["view_count"] == result["view_count"]
    assert view_parameters["view_names"] == result["view_names"]
    assert view_parameters["row_counts"]["view_summary"] == result["view_bundle_row_counts"]["view_summary"]
    assert view_parameters["row_counts"]["view_projections"] == result["view_bundle_row_counts"]["view_projections"]
    assert view_parameters["exported_row_counts"]["view_summary"] == result["view_bundle_row_counts"]["view_summary"]
    assert view_parameters["exported_row_counts"]["view_projections"] == result["view_bundle_row_counts"]["view_projections"]
    assert view_parameters["exported_row_counts_match_summary"] is True
    assert view_parameters["export_status"] == "current"
    assert view_parameters["export_needs_refresh"] is False
    assert result["view_parameter_export_status"] == "current"
    assert result["view_parameter_export_needs_refresh"] is False
    assert view_parameters["files"]["view_summary_csv"] == result["view_bundle_files"]["view_summary_csv"]
    assert view_parameters["files"]["view_projections_csv"] == result["view_bundle_files"]["view_projections_csv"]
    assert len(view_parameters["views"]) == view_parameters["view_count"]
    first_view = view_parameters["views"][0]
    assert {
        "name",
        "camera_direction",
        "camera_up",
        "camera_position",
        "camera_distance_angstrom",
        "projection_span_angstrom",
        "atom_projection_count",
        "overlap_candidate_count",
        "warning_count",
        "clean_for_visual_review",
    }.issubset(first_view)
    assert Path(result["report_json_path"]).exists()
    assert Path(result["view_bundle_files"]["requested_diagnostic_focus_status_json"]).exists()


def test_view_parameter_summary_recommends_export_refresh_when_counts_are_stale() -> None:
    report = {
        "project_id": "stale_views",
        "revision": 2,
        "execution_mode": "execute",
        "normality": "hot_loaded_and_passed",
        "health_ok": True,
        "live_readiness": {
            "state": "ready",
            "ready_for_next_edit": True,
            "recommended_tool": "material_studio_live_modeling_request",
            "recommended_action": "continue_next_model_edit",
        },
        "view_review": {
            "available": True,
            "ok": True,
            "status": "passed",
            "view_count": 2,
            "view_names": ["front", "top"],
            "supported_view_count": 2,
            "supported_view_names": ["front", "top"],
            "clean_view_count": 2,
            "clean_views": ["front", "top"],
            "views": [
                {
                    "name": "front",
                    "supported": True,
                    "atom_projection_count": 4,
                    "projection_count_matches_model": True,
                    "overlap_candidate_count": 0,
                    "warning_count": 0,
                    "camera_direction": [0.0, 0.0, 1.0],
                    "camera_up": [0.0, 1.0, 0.0],
                    "camera_position": [0.0, 0.0, 10.0],
                    "camera_distance_angstrom": 10.0,
                    "projection_span_angstrom": {"x": 2.0, "y": 2.0, "depth": 1.0},
                },
                {
                    "name": "top",
                    "supported": True,
                    "atom_projection_count": 4,
                    "projection_count_matches_model": True,
                    "overlap_candidate_count": 0,
                    "warning_count": 0,
                    "camera_direction": [0.0, 1.0, 0.0],
                    "camera_up": [0.0, 0.0, 1.0],
                    "camera_position": [0.0, 10.0, 0.0],
                    "camera_distance_angstrom": 10.0,
                    "projection_span_angstrom": {"x": 2.0, "y": 2.0, "depth": 1.0},
                },
            ],
            "recommended_view_name": "front",
            "recommended_view_reason": "test",
            "recommended_view_camera_direction": [0.0, 0.0, 1.0],
            "recommended_view_camera_up": [0.0, 1.0, 0.0],
            "next_action": "view_parameters_ready_for_visual_review",
        },
        "diagnostics": {
            "view_bundle_row_counts": {
                "view_summary": 1,
                "view_projections": 4,
                "view_overlaps": 0,
                "view_quality": 1,
            }
        },
        "structure": {"path": "C:/tmp/stale_views/structure.cif", "exists": True},
        "gui": {
            "hot_loaded": True,
            "loaded_current_revision": True,
            "visual_validation": "passed",
        },
    }

    summary = server._view_parameter_summary(report)
    report["view_parameter_summary"] = summary

    assert summary["row_counts"] == {
        "view_summary": 2,
        "view_projections": 8,
        "view_overlaps": 0,
        "view_quality": 2,
    }
    assert summary["exported_row_counts"]["view_summary"] == 1
    assert summary["exported_row_counts_match_summary"] is False
    assert summary["export_status"] == "stale_or_partial"
    assert summary["export_needs_refresh"] is True
    assert summary["export_recommended_tool"] == "material_studio_model_export_view_bundle"
    assert summary["export_recommended_action"] == "regenerate_view_bundle_for_current_view_parameter_summary"
    assert summary["export_payload_hint"] == {
        "project_id": "stale_views",
        "views": ["front", "top"],
        "include_gui_snapshot": False,
    }
    acceptance = server._diagnostic_acceptance_summary(report)
    assert acceptance["status"] == "diagnostics_stale_or_partial"
    assert acceptance["ok"] is False
    assert acceptance["can_check_model_normality"] is False
    assert acceptance["basic_view_tables_ok"] is True
    assert acceptance["view_parameter_export_status"] == "stale_or_partial"
    assert acceptance["view_parameter_export_current"] is False
    assert acceptance["view_parameter_export_needs_refresh"] is True
    assert acceptance["view_parameter_export_recommended_tool"] == "material_studio_model_export_view_bundle"
    assert acceptance["view_parameter_export_payload_hint"]["project_id"] == "stale_views"
    assert acceptance["failures"] == [
        {
            "type": "view_parameter_export_not_current",
            "status": "stale_or_partial",
            "expected_row_counts": summary["row_counts"],
            "exported_row_counts": summary["exported_row_counts"],
        }
    ]

    next_action = server._modeling_report_next_action_plan(report)
    assert next_action["action_id"] == "refresh_view_parameter_export"
    assert next_action["recommended_tool"] == "material_studio_model_export_view_bundle"
    assert next_action["recommended_action"] == "regenerate_view_bundle_for_current_view_parameter_summary"
    assert next_action["needs_user_confirmation"] is False
    assert next_action["safe_to_call_without_confirmation"] is True
    assert next_action["payload_hint"] == {
        "project_id": "stale_views",
        "views": ["front", "top"],
        "include_gui_snapshot": False,
        "revision": 2,
    }

    gate = server._normality_gate(report)
    assert gate["can_claim_model_normal"] is True
    assert gate["can_claim_live_gui_normal"] is True
    assert "view_parameter_export_not_current" not in gate["all_must_not_claim_reasons"]


def test_live_summary_next_action_contract_prefers_plan_and_preserves_legacy_fallback() -> None:
    next_action_plan = {
        "action_id": "apply_recommended_semiconductor_kpoint_grid",
        "recommended_tool": "material_studio_live_update_with_patch",
        "recommended_action": "apply_recommended_explicit_kpoint_grid_then_reaudit",
        "needs_user_confirmation": True,
        "safe_to_call_without_confirmation": False,
        "payload_hint": {"project_id": "action_contract", "base_revision": 4},
        "ready": {"hotload": False, "next_edit": True, "calculation": False},
    }
    live = server._live_summary_from_report(
        {
            "project_id": "action_contract",
            "revision": 4,
            "next_action": "Inspect the GUI snapshot, then continue modeling.",
            "next_action_plan": next_action_plan,
        }
    )

    assert live["next_action_id"] == next_action_plan["action_id"]
    assert live["next_action_tool"] == next_action_plan["recommended_tool"]
    assert live["next_action"] == next_action_plan["recommended_action"]
    assert live["next_action_payload_hint"] == next_action_plan["payload_hint"]
    assert live["next_action_needs_user_confirmation"] is True
    assert live["next_action_safe_to_call_without_confirmation"] is False
    assert live["next_action_source"] == "next_action_plan"
    resolution = live["next_action_resolution"]
    assert resolution["status"] == "next_action_plan_override_applied"
    assert resolution["contract_consistent"] is True
    assert resolution["legacy_action_overridden"] is True
    assert resolution["confirmation_gate_consistent"] is True
    assert resolution["superseded_action"] == (
        "Inspect the GUI snapshot, then continue modeling."
    )

    legacy = server._live_summary_from_report(
        {
            "project_id": "legacy_action_contract",
            "revision": 1,
            "next_action": "legacy_review_action",
        }
    )
    assert legacy["next_action"] == "legacy_review_action"
    assert legacy["next_action_source"] == "legacy_report_action"
    assert legacy["next_action_resolution"]["status"] == (
        "legacy_report_action_fallback"
    )
    assert legacy["next_action_resolution"]["contract_consistent"] is False


def test_semiconductor_recommended_focuses_mark_ready_when_already_exported(
    monkeypatch, tmp_path: Path
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and export view quality diagnostics.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["requested_diagnostic_focuses"] == ["view_quality"]
    assert set(result["unrequested_recommended_diagnostic_focuses"]) == {
        "semiconductor_structure_health",
        "electronic_structure_preflight",
    }
    assert result["view_bundle_row_counts"]["view_quality"] == 6
    assert result["view_bundle_row_counts"]["semiconductor_composition"] == 1
    assert result["view_bundle_row_counts"]["semiconductor_calculation_preflight"] == 1
    assert Path(result["view_bundle_files"]["semiconductor_composition_csv"]).exists()
    assert Path(result["view_bundle_files"]["semiconductor_calculation_readiness_csv"]).exists()

    plan = result["diagnostic_focus_plan"]
    assert plan["status"] == "recommended_focuses_ready"
    assert plan["ok"] is True
    assert plan["export_needed"] is False
    assert plan["recommended_focuses_ready"] is True
    assert plan["recommended_focus_missing_csv_keys"] == []
    assert plan["recommended_focus_missing_summary_keys"] == []
    assert plan["recommended_action"] == "review_recommended_diagnostic_focus_status"
    assert result["live_summary"]["diagnostic_focus_plan_status"] == "recommended_focuses_ready"
    assert result["live_summary"]["diagnostic_focus_plan_ok"] is True
    assert result["live_summary"]["diagnostic_focus_plan_export_needed"] is False
    assert result["live_summary"]["diagnostic_focus_plan_recommended_focuses_ready"] is True
    assert result["live_summary"]["mcp_diagnostic_focus_plan_export_needed"] is False
    assert result["live_summary"]["mcp_diagnostic_focus_plan_recommended_focuses_ready"] is True
    assert result["mcp_diagnostic_focus_plan_export_needed"] is False
    assert result["mcp_diagnostic_focus_plan_recommended_focuses_ready"] is True
    assert result["modeling_report"]["change_receipt"]["diagnostic_focus_plan"]["export_needed"] is False


def test_live_modeling_request_opens_gui_when_user_says_open_in_materials_studio(
    monkeypatch, tmp_path: Path
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and open it in Materials Studio.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "execute"
    assert result["execution_mode_source"] == "explicit_live_intent"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["result"]["execution_backend"] == "crystal_cif_materialize"
    assert result["gui_open"]["open_result"]["method"] == "fake"
