def test_live_modeling_request_handles_chinese_realtime_gui_diagnostics_and_normality(
    monkeypatch, tmp_path: Path
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "构建硅晶体并实时热加载到当前界面，导出视角参数并检查模型是否正常。",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "execute"
    assert result["execution_mode_source"] == "explicit_live_intent"
    assert result["diagnostic_export_requested"] is True
    assert result["normality_check_requested"] is True
    assert result["nl_plan"]["kind"] == "spec"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["result"]["execution_backend"] == "crystal_cif_materialize"
    assert result["gui_open"]["structure_path"].endswith(".cif")
    assert result["modeling_report"]["gui"]["hot_loaded"] is True
    assert result["modeling_report"]["diagnostic_export_requested"] is True
    assert result["modeling_report"]["normality_check_requested"] is True
    assert result["requested_diagnostic_focuses"] == [
        "semiconductor_structure_health",
        "view_quality",
        "electronic_structure_preflight",
    ]
    assert result["modeling_report"]["auto_completed_diagnostic_focuses"] == [
        "electronic_structure_preflight",
    ]
    assert result["modeling_report"]["change_receipt"]["auto_completed_diagnostic_focuses"] == [
        "electronic_structure_preflight",
    ]
    assert result["live_summary"]["auto_completed_diagnostic_focuses"] == [
        "electronic_structure_preflight",
    ]
    assert result["live_summary"]["mcp_auto_completed_diagnostic_focuses"] == [
        "electronic_structure_preflight",
    ]
    focus_status = result["requested_diagnostic_focus_status"]
    assert focus_status["auto_completed_focuses"] == ["electronic_structure_preflight"]
    assert focus_status["auto_completed_focus_count"] == 1
    focus_sources = {item["focus"]: item for item in focus_status["focuses"]}
    assert focus_sources["semiconductor_structure_health"]["source"] == "user_request"
    assert focus_sources["semiconductor_structure_health"]["auto_completed"] is False
    assert focus_sources["view_quality"]["source"] == "user_request"
    assert focus_sources["electronic_structure_preflight"]["source"] == "auto_completed"
    assert focus_sources["electronic_structure_preflight"]["auto_completed"] is True
    diagnostic_focus_plan = result["diagnostic_focus_plan"]
    assert diagnostic_focus_plan["user_requested_focuses"] == [
        "semiconductor_structure_health",
        "view_quality",
    ]
    assert diagnostic_focus_plan["auto_completed_focuses"] == [
        "electronic_structure_preflight",
    ]
    assert diagnostic_focus_plan["auto_completed_focus_count"] == 1
    assert diagnostic_focus_plan["payload_hint"]["auto_completed_focuses"] == [
        "electronic_structure_preflight",
    ]
    assert result["unrequested_recommended_diagnostic_focuses"] == []
    assert result["modeling_report"]["gui_current_revision"]["status"] == "current_but_snapshot_missing"
    assert result["modeling_report"]["gui_current_revision"]["loaded_current_revision"] is True
    assert result["modeling_report"]["gui_current_revision"]["needs_snapshot"] is True
    receipt_gui = result["modeling_report"]["change_receipt"]["gui_current_revision"]
    assert receipt_gui["status"] == "current_but_snapshot_missing"
    assert receipt_gui["loaded_current_revision"] is True
    assert receipt_gui["needs_snapshot"] is True
    assert receipt_gui["recommended_tool"] == "material_studio_gui_snapshot"
    assert result["live_summary"]["diagnostic_export_requested"] is True
    assert result["live_summary"]["normality_check_requested"] is True
    assert result["live_summary"]["gui_loaded_current_revision"] is True
