    assert backend.opened and backend.opened[-1].suffix == ".cif"

    snapshot = server.material_studio_gui_snapshot(
        project_id=result["project_id"],
        revision=result["revision"],
        label="current_revision",
        working_dir=str(tmp_path),
    )

