    assert snapshot["structured_sync"]["persisted"] is True
    assert snapshot["modeling_report"]["gui"]["hot_loaded"] is True
    assert snapshot["modeling_report"]["gui"]["snapshot_source"] == "gui_snapshot"
    assert snapshot["modeling_report"]["gui"]["visual_validation"] == "passed"
    assert snapshot["modeling_report"]["gui_current_revision"]["status"] == "current_and_visually_verified"
    assert snapshot["modeling_report"]["gui_current_revision"]["needs_snapshot"] is False
    assert snapshot["live_summary"]["gui_current_revision_status"] == "current_and_visually_verified"

    status = server.material_studio_live_project_status(
        result["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
    )
    assert status["ok"] is True
    assert status["gui_current_revision"]["status"] == "current_and_visually_verified"
    assert status["gui_current_revision"]["needs_snapshot"] is False
    assert status["modeling_report"]["gui"]["snapshot_source"] == "gui_snapshot"


