def test_requested_views_from_common_chinese_model_parameter_phrases() -> None:
    all_views = ["front", "back", "right", "left", "top", "bottom", "isometric"]
    for phrase in (
        "\u5bfc\u51fa\u5404\u4e2a\u89c6\u89d2\u6a21\u578b\u53c2\u6570",
        "\u5bfc\u51fa\u4e0d\u540c\u89c6\u89d2\u6a21\u578b\u53c2\u6570",
        "\u5bfc\u51fa\u591a\u89d2\u5ea6\u6a21\u578b\u53c2\u6570",
        "\u5bfc\u51fa\u5168\u89d2\u5ea6\u6a21\u578b\u53c2\u6570",
        "\u5bfc\u51fa\u5168\u89c6\u89d2\u6a21\u578b\u53c2\u6570",
    ):
        assert server._requested_views_from_text(phrase) == all_views

    for phrase in (
        "\u5bfc\u51fa\u4e09\u89c6\u56fe\u6a21\u578b\u53c2\u6570",
        "\u5bfc\u51fa\u4e09\u9762\u89c6\u56fe\u53c2\u6570",
        "\u5bfc\u51fa\u6b63\u4fa7\u4fef\u89c6\u56fe\u53c2\u6570",
    ):
        assert server._requested_views_from_text(phrase) == ["front", "right", "top"]


