def test_semiconductor_diagnostic_gate_treats_focus_status_json_as_optional_when_focus_ready(
    tmp_path: Path,
) -> None:
    artifact_keys = [
        "view_summary_csv",
        "view_projections_csv",
        "view_quality_csv",
        "semiconductor_normality_diagnosis_json",
        "semiconductor_normality_diagnosis_csv",
        "diagnostic_export_manifest_json",
    ]
    diagnostics = {
        "view_bundle_row_counts": {
            "view_summary": 7,
            "view_projections": 56,
            "view_quality": 7,
            "semiconductor_composition": 2,
            "semiconductor_calculation_preflight": 1,
            "semiconductor_calculation_readiness": 1,
            "semiconductor_normality_diagnosis": 1,
        },
        "view_bundle_manifest_path": str(tmp_path / "manifest.json"),
    }
    Path(diagnostics["view_bundle_manifest_path"]).write_text("{}", encoding="utf-8")
    for key in artifact_keys:
        path = tmp_path / f"{key}.csv"
        path.write_text("ok\n", encoding="utf-8")
        diagnostics[key] = str(path)
    _write_current_diagnostic_contract_artifacts(tmp_path, diagnostics)

    report = {
        "project_id": "gaas_focus_status_optional",
        "revision": 0,
        "normality": "hot_loaded_and_passed",
        "semiconductor_review": {"available": True},
        "diagnostics": diagnostics,
        "diagnostic_export_manifest": {
            "ok": True,
            "status": "exported",
            "total_exported_file_count": len(artifact_keys),
        },
        "requested_diagnostic_focuses": [
            "semiconductor_structure_health",
            "electronic_structure_preflight",
            "view_quality",
        ],
        "requested_diagnostic_focus_status": {
            "available": True,
            "ok": True,
            "focus_count": 3,
            "missing_csv_keys": [],
            "missing_summary_keys": [],
        },
        "diagnostic_focus_plan": {
            "recommended_focuses": [
                "semiconductor_structure_health",
                "electronic_structure_preflight",
                "view_quality",
            ],
            "requested_focuses": [
                "semiconductor_structure_health",
                "electronic_structure_preflight",
                "view_quality",
            ],
        },
        "semiconductor_normality_diagnosis": {"available": True, "status": "ready"},
        "normality_gate": {"status": "model_claimable", "can_claim_model_normal": True},
    }

    gate = server._semiconductor_diagnostic_gate(report)
    report["semiconductor_diagnostic_gate"] = gate
    acceptance = server._diagnostic_acceptance_summary(report)

    assert gate["ok"] is True
    assert gate["status"] == "ready"
    assert gate["blocking_reasons"] == []
    assert gate["missing_artifacts"] == []
    assert "requested_diagnostic_focus_status_json" in gate["optional_artifacts"]
    assert gate["missing_optional_artifacts"] == ["requested_diagnostic_focus_status_json"]
    assert gate["payload_hint"]["missing_artifacts"] == []
    assert gate["payload_hint"]["missing_optional_artifacts"] == [
        "requested_diagnostic_focus_status_json"
    ]
    assert acceptance["ok"] is True
    assert acceptance["status"] == "diagnostics_ready"
    assert acceptance["can_check_model_normality"] is True


def test_semiconductor_diagnostic_gate_reports_missing_artifacts() -> None:
    gate = server._semiconductor_diagnostic_gate(
        {
            "project_id": "si_missing_diag",
            "revision": 0,
            "semiconductor_review": {"available": True},
            "diagnostics": {"view_bundle_row_counts": {"view_summary": 1}},
            "diagnostic_export_manifest": {"ok": False, "status": "missing"},
            "requested_diagnostic_focus_status": {
                "ok": False,
                "missing_csv_keys": ["semiconductor_composition_csv"],
                "missing_summary_keys": ["semiconductor_review.composition"],
            },
            "diagnostic_focus_plan": {
                "recommended_focuses": ["semiconductor_structure_health"],
            },
            "semiconductor_normality_diagnosis": {"available": True},
        }
    )

    assert gate["available"] is True
    assert gate["ok"] is False
    assert gate["status"] == "requested_focus_incomplete"
    assert "diagnostic_manifest_missing" in gate["blocking_reasons"]
    assert "requested_diagnostic_focus_incomplete" in gate["blocking_reasons"]
    assert "view_projections" in gate["missing_row_counts"]
    assert "semiconductor_composition" in gate["missing_row_counts"]
    assert "view_summary_csv" in gate["missing_artifacts"]
    assert gate["recommended_tool"] == "material_studio_model_export_view_bundle"
    assert gate["payload_hint"]["project_id"] == "si_missing_diag"
    assert gate["payload_hint"]["missing_row_counts"] == gate["missing_row_counts"]


