def test_gui_snapshot_without_project_id_uses_latest_project_context_for_paths(
    monkeypatch, tmp_path: Path
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert result["ok"] is True
    assert result["modeling_report"]["gui_current_revision"]["status"] == "current_but_snapshot_missing"

    snapshot = server.material_studio_gui_snapshot(
        label="latest_current",
        working_dir=str(tmp_path),
    )

    assert snapshot["ok"] is True
    assert snapshot["structured_sync_context"]["available"] is True
    assert snapshot["structured_sync_context"]["reason"] == "latest_current_project"
    assert snapshot["project_resolution"]["source"] == "latest_current"
    assert snapshot["structured_sync"]["persisted"] is True
    assert snapshot["structured_sync"]["project_id"] == result["project_id"]
    assert snapshot["structured_sync"]["revision"] == result["revision"]
    assert snapshot["gui_action_transaction"]["path"] == snapshot["report_write_transaction"]["path"]
    assert snapshot["gui_action_transaction"]["nested_call_count"] == 1
    assert "gui_snapshot" in snapshot["gui_action_transaction"]["coverage"]

    screenshot_path = Path(snapshot["screenshot_path"])
    assert screenshot_path.exists()
    assert screenshot_path.parent == tmp_path / "screenshots" / result["project_id"] / f"r{result['revision']:03d}"
    assert "latest_current" in screenshot_path.name

    log_path = tmp_path / result["project_id"] / "gui_actions.jsonl"
    assert log_path.exists()
    log_text = log_path.read_text(encoding="utf-8")
    assert '"action": "snapshot"' in log_text
    assert f'"project_id": "{result["project_id"]}"' in log_text
    assert f'"revision": {result["revision"]}' in log_text

    assert snapshot["modeling_report"]["gui"]["snapshot_path"] == snapshot["screenshot_path"]
    assert snapshot["modeling_report"]["gui"]["snapshot_source"] == "gui_snapshot"
    assert snapshot["modeling_report"]["gui_current_revision"]["status"] == "current_and_visually_verified"
    assert snapshot["live_summary"]["gui_current_revision_status"] == "current_and_visually_verified"


def test_gui_snapshot_supersedes_prior_gui_open_snapshot_in_reports(
    monkeypatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

