def test_live_modeling_request_create_hotloads_and_marks_requested_diagnostic_export(
    monkeypatch, tmp_path: Path
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build GaAs zinc blende crystal, hot-load it in Materials Studio, export view parameters, and check whether the model is normal.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "execute"
    assert result["execution_mode_source"] == "explicit_live_intent"
    assert result["diagnostic_export_requested"] is True
    assert result["normality_check_requested"] is True
    assert result["nl_plan"]["kind"] == "spec"
    assert result["nl_plan"]["template_id"] == "gallium_arsenide_zincblende"
    assert result["result"]["execution_backend"] == "crystal_cif_materialize"
    assert result["gui_open"]["structure_path"].endswith(".cif")
    high_level_transaction = result["gui_action_transaction"]
    assert high_level_transaction["path"] == result["report_write_transaction"]["path"]
    assert high_level_transaction["nested_call_count"] == 0
    assert {
        "high_level_hotload",
        "workflow:create",
        "target_window_revalidation",
        "gui_open_structure",
        "report_read_modify_write",
    } <= set(high_level_transaction["coverage"])
    assert result["modeling_report"]["diagnostic_export_requested"] is True
    assert result["modeling_report"]["normality_check_requested"] is True
    assert result["modeling_report"]["gui"]["hot_loaded"] is True
    expected_followup_payload = {
        "project_id": result["project_id"],
        "working_dir": str(tmp_path.resolve()),
    }
    expected_snapshot_payload = {
        "project_id": result["project_id"],
        "revision": result["revision"],
        "working_dir": str(tmp_path.resolve()),
    }
    live_summary = result["live_summary"]
    assert live_summary == result["modeling_report"]["live_summary"]
    assert live_summary["project_id"] == result["project_id"]
    assert live_summary["revision"] == result["revision"]
    assert live_summary["workflow"] == "create"
    assert live_summary["execution_mode"] == "execute"
    assert live_summary["execution_mode_source"] == "explicit_live_intent"
    assert live_summary["normality"] == result["modeling_report"]["normality"]
    assert live_summary["health_verdict"] == result["modeling_report"]["health_verdict"]
    normality_explanation = result["modeling_report"]["normality_explanation"]
    assert normality_explanation["status"] == result["modeling_report"]["normality"]
    assert normality_explanation["summary"] == "ready_for_model_edits_but_not_for_calculation"
    assert normality_explanation["primary_reason"] == "acceptance_criteria_failed"
    assert normality_explanation["trust_level"] == "review"
    assert normality_explanation["ready_for_next_edit"] is True
    assert normality_explanation["ready_for_calculation"] is False
    assert normality_explanation["next_action_tool"] == "material_studio_live_modeling_request"
    assert normality_explanation["evidence"]["hot_loaded"] is True
    assert normality_explanation["evidence"]["view_projection_row_count"] == 48
    assert live_summary["normality_explanation"] == normality_explanation
    assert live_summary["normality_summary"] == "ready_for_model_edits_but_not_for_calculation"
    assert live_summary["normality_primary_reason"] == "acceptance_criteria_failed"
    assert live_summary["normality_next_action"] == "review_flags_then_continue_next_model_edit"
    live_action = result["modeling_report"]["live_action_summary"]
    assert result["live_action_summary"] == live_action
    assert live_action["phase"] == "continue_modeling"
    assert live_action["action_id"] == "continue_live_modeling"
    assert live_action["recommended_tool"] == "material_studio_live_modeling_request"
