def test_live_modeling_request_shows_current_revision_and_exports_diagnostics(
    monkeypatch, tmp_path: Path
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build silicon crystal.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert created["ok"] is True
    assert created["execution_mode"] == "preview"

    shown = server.material_studio_live_modeling_request(
        "Show the current model in Materials Studio and export current view parameters.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert shown["ok"] is True
    assert shown["workflow"] == "show_current"
    assert shown["project_id"] == created["project_id"]
    assert shown["revision"] == created["revision"]
    assert shown["execution_mode"] == "execute"
    assert shown["execution_mode_source"] == "explicit_live_intent"
    assert shown["diagnostic_export_requested"] is True
    assert shown["nl_plan"]["kind"] == "show_current"
    assert shown["nl_plan"]["template_id"] == "show_current_revision_with_diagnostics"
    assert shown["result"]["execution_backend"] == "crystal_cif_materialize"
    assert shown["gui_open"]["structure_path"].endswith(".cif")
    assert shown["modeling_report"]["gui"]["hot_loaded"] is True
    assert shown["modeling_report"]["diagnostic_export_requested"] is True
    assert Path(shown["view_bundle_manifest_path"]).exists()
    assert Path(shown["view_bundle_files"]["view_projections_csv"]).exists()
    assert shown["view_bundle_row_counts"]["view_projections"] == 56
    assert backend.opened and backend.opened[-1].suffix == ".cif"

    shown_chinese = server.material_studio_live_modeling_request(
        "把当前模型推到 Materials Studio，并导出当前视图参数。",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert shown_chinese["ok"] is True
    assert shown_chinese["workflow"] == "show_current"
    assert shown_chinese["diagnostic_export_requested"] is True
    assert shown_chinese["nl_plan"]["kind"] == "show_current"
    assert shown_chinese["nl_plan"]["template_id"] == "show_current_revision_with_diagnostics"
    assert shown_chinese["view_bundle_row_counts"]["view_projections"] == 56

    current = server.material_studio_model_get_current(created["project_id"], working_dir=str(tmp_path))
    assert current["revision"] == created["revision"]
    history = server.material_studio_project_history(created["project_id"], working_dir=str(tmp_path))
    assert [item["revision"] for item in history["history"]] == [created["revision"]]


def test_live_modeling_request_auto_selects_semiconductor_dopant_site(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal as a 2x1x1 supercell and dope with P.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["view_audit"]["model"]["elements"] == {"P": 1, "Si": 15}
    assert result["view_audit"]["metadata"]["nl_composite_operations"] == [
        "make_supercell 2x1x1",
        "substitute_atom Si1_000->P",
        "set_metadata last_semiconductor_dopant_site,nl_auto_selected_sites,semiconductor_dopant_sites",
    ]
    auto_site = result["view_audit"]["metadata"]["nl_auto_selected_sites"][0]
    assert auto_site["operation"] == "dopant"
    assert auto_site["atom_id"] == "Si1_000"
    assert auto_site["site_element"] == "Si"
    assert auto_site["new_element"] == "P"
    assert auto_site["auto_selected_site"] is True
    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    assert semiconductor["dopant_summary"]["total_dopant_count"] == 1
    assert result["modeling_health"]["checks"]["semiconductor_total_dopant_fraction"] == 0.0625
    assert result["modeling_health"]["checks"]["semiconductor_dopant_site_count"] == 1


