def test_live_modeling_request_builds_semiconductor_dopant_fraction(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal as a 2x1x1 supercell, dope 25% P, and export dopant concentration diagnostics.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "preview"
    assert result["diagnostic_export_requested"] is True
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["requested_diagnostic_focuses"] == [
        "dopant_site_preflight",
        "dopant_fraction_preflight",
        "view_quality",
    ]
    assert result["requested_diagnostic_focus_ok"] is True
    assert result["view_audit"]["model"]["atom_count"] == 16
    assert result["view_audit"]["model"]["elements"] == {"P": 4, "Si": 12}
    dopant_record = result["view_audit"]["metadata"]["last_applied_dopant_fraction"]
    assert dopant_record["host_element"] == "Si"
    assert dopant_record["dopant_element"] == "P"
    assert dopant_record["requested_fraction"] == 0.25
    assert dopant_record["actual_fraction"] == 0.25
    assert dopant_record["selected_atom_ids"] == ["Si1_000", "Si1_100", "Si2_000", "Si2_100"]
    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    dopant_summary = semiconductor["dopant_summary"]
    assert dopant_summary["total_dopant_count"] == 4
    assert dopant_summary["total_dopant_fraction"] == 0.25
    dopant_fraction = semiconductor["dopant_fraction_summary"]
    assert dopant_fraction["entry_count"] == 1
    assert dopant_fraction["latest"]["substituted_site_count"] == 4
    assert dopant_fraction["latest"]["rounding_warning"] is False
    assert result["modeling_health"]["checks"]["semiconductor_dopant_fraction_count"] == 1
    assert result["modeling_health"]["checks"]["semiconductor_dopant_fraction_rounding_warning"] is False
    focus_status = result["modeling_report"]["requested_diagnostic_focus_status"]
    dopant_focus = next(item for item in focus_status["focuses"] if item["focus"] == "dopant_fraction_preflight")
    assert focus_status["ok"] is True
    assert dopant_focus["focus"] == "dopant_fraction_preflight"
    assert "inspection.semiconductor_health.dopant_fraction_summary" in dopant_focus["available_summary_keys"]
    assert "inspection.semiconductor_health.dopant_concentration_summary" in dopant_focus["available_summary_keys"]
    assert "semiconductor_dopant_concentration_csv" in dopant_focus["existing_csv_keys"]
    assert "semiconductor_dopant_fraction_csv" in dopant_focus["existing_csv_keys"]
    assert Path(dopant_focus["artifacts"]["semiconductor_dopant_concentration_csv"]).exists()
    assert Path(dopant_focus["artifacts"]["semiconductor_dopant_fraction_csv"]).exists()
    assert result["live_summary"]["requested_diagnostic_focuses"] == [
        "dopant_site_preflight",
        "dopant_fraction_preflight",
        "view_quality",
    ]
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_dopant_fraction_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_dopant_concentration_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_dopants_csv"]).exists()
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_dopant_sites_csv"]).exists()


