def test_infer_modeling_plan_matches_chinese_formula_semiconductor_alloys() -> None:
    cases = [
        (
            "构建Al0.3Ga0.7As合金并准备预览",
            {"formula": "Al0.3Ga0.7As", "host_element": "Ga", "alloy_element": "Al", "requested_fraction": 0.3},
        ),
        (
            "构建铝镓砷合金x=0.3并准备预览",
            {"formula": "Al0.3Ga0.7As", "host_element": "Ga", "alloy_element": "Al", "requested_fraction": 0.3},
        ),
        (
            "构建铝镓砷固溶体铝含量0.25并准备预览",
            {"formula": "Al0.25Ga0.75As", "host_element": "Ga", "alloy_element": "Al", "requested_fraction": 0.25},
        ),
        (
            "构建In0.2Ga0.8As合金并准备预览",
            {"formula": "In0.2Ga0.8As", "host_element": "Ga", "alloy_element": "In", "requested_fraction": 0.2},
        ),
        (
            "构建铟镓砷合金x=0.2并准备预览",
            {"formula": "In0.2Ga0.8As", "host_element": "Ga", "alloy_element": "In", "requested_fraction": 0.2},
        ),
        (
            "构建Al0.25Ga0.75N合金并准备预览",
            {"formula": "Al0.25Ga0.75N", "host_element": "Ga", "alloy_element": "Al", "requested_fraction": 0.25},
        ),
        (
            "构建铝镓氮合金x=0.25并准备预览",
            {"formula": "Al0.25Ga0.75N", "host_element": "Ga", "alloy_element": "Al", "requested_fraction": 0.25},
        ),
        (
            "构建In0.25Ga0.75N合金并准备预览",
            {"formula": "In0.25Ga0.75N", "host_element": "Ga", "alloy_element": "In", "requested_fraction": 0.25},
        ),
        (
            "构建铟镓氮合金x=0.25并准备预览",
            {"formula": "In0.25Ga0.75N", "host_element": "Ga", "alloy_element": "In", "requested_fraction": 0.25},
        ),
        (
            "构建Cd0.5Zn0.5Te合金并准备预览",
            {"formula": "Cd0.5Zn0.5Te", "host_element": "Cd", "alloy_element": "Zn", "requested_fraction": 0.5},
        ),
        (
            "构建镉锌碲合金x=0.5并准备预览",
            {"formula": "Cd0.5Zn0.5Te", "host_element": "Cd", "alloy_element": "Zn", "requested_fraction": 0.5},
        ),
        (
            "构建硅锗合金x=0.25并准备预览",
            {"formula": "Si0.75Ge0.25", "host_element": "Si", "alloy_element": "Ge", "requested_fraction": 0.25},
        ),
    ]

    for request, expected in cases:
        plan = infer_modeling_plan(request)
        assert plan.kind == "spec"
        assert plan.template_id == "crystal_formula_alloy"
        assert isinstance(plan.payload, dict)
        assert plan.payload["metadata"]["formula_alloy_request"] == {
            **expected,
            "source": "natural_language_formula_alloy",
        }


