def test_live_modeling_request_applies_dopant_after_formula_alloy(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build SiGe alloy x=0.25 as a 2x1x1 supercell with B dopant.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "preview"
    assert result["nl_plan"]["template_id"] == "crystal_formula_alloy"
    assert result["view_audit"]["model"]["elements"] == {"B": 1, "Ge": 4, "Si": 11}
    assert result["view_audit"]["metadata"]["nl_composite_operations"] == [
        "make_supercell 2x1x1",
        "substitute_atom Si1_000->Ge",
        "substitute_atom Si1_100->Ge",
        "substitute_atom Si2_000->Ge",
        "substitute_atom Si2_100->Ge",
        "set_metadata applied_alloy,last_applied_alloy",
        "substitute_atom Si3_000->B",
        "set_metadata last_semiconductor_dopant_site,nl_auto_selected_sites,semiconductor_dopant_sites",
    ]
    alloy = result["view_audit"]["metadata"]["last_applied_alloy"]
    dopant = result["view_audit"]["metadata"]["last_semiconductor_dopant_site"]
    assert alloy["selected_atom_ids"] == ["Si1_000", "Si1_100", "Si2_000", "Si2_100"]
    assert dopant["site_id"] == "Si3_000"
    assert dopant["site_element"] == "Si"
    assert dopant["dopant_element"] == "B"
    assert dopant["site_id"] not in alloy["selected_atom_ids"]
    semiconductor = result["modeling_report"]["inspection"]["semiconductor_health"]
    assert semiconductor["alloy_summary"]["latest"]["actual_fraction"] == 0.25
    assert semiconductor["dopant_site_summary"]["latest"]["role_hint"] == "acceptor_like_p_type_on_group_iv_site"
    assert result["modeling_health"]["checks"]["semiconductor_alloy_rounding_warning"] is False
    assert result["modeling_health"]["checks"]["semiconductor_dopant_site_carrier_type_hint"] == "acceptor_like_p_type"
    assert result["modeling_health"]["errors"] == []
    assert backend.opened == []


