def test_live_modeling_request_applies_semiconductor_strain(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build silicon crystal and apply 2% tensile strain in-plane.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["nl_plan"]["template_id"] == "silicon_diamond"
    assert result["view_audit"]["model"]["lattice"]["a"] == 5.53962
    assert result["view_audit"]["model"]["lattice"]["b"] == 5.53962
    assert result["view_audit"]["model"]["lattice"]["c"] == 5.431
    assert result["view_audit"]["metadata"]["nl_composite_operations"] == [
        "set_lattice",
        "set_metadata applied_strain,in_plane_lattice_angstrom,last_applied_strain",
    ]
    strain = result["modeling_report"]["inspection"]["semiconductor_health"]["strain_summary"]
    assert strain["entry_count"] == 1
    assert strain["latest"]["axes"] == ["a", "b"]
    assert strain["latest"]["percent"] == 2.0
    assert strain["latest"]["mode"] == "biaxial_tensile"
    assert strain["max_abs_strain_percent"] == 2.0
    assert strain["strain_warning"] is False
    assert result["modeling_health"]["checks"]["semiconductor_applied_strain_count"] == 1
    assert result["modeling_health"]["checks"]["semiconductor_applied_strain_max_abs_percent"] == 2.0
    assert Path(result["modeling_report"]["diagnostics"]["semiconductor_strain_csv"]).exists()


def test_live_modeling_request_marks_large_semiconductor_strain_warning(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request("Build silicon crystal.", working_dir=str(tmp_path))
    assert created["ok"] is True

    result = server.material_studio_live_modeling_request(
        "Apply 6% compressive strain along c.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "patch"
    assert result["nl_plan"]["template_id"] == "crystal_strain"
    assert result["view_audit"]["model"]["lattice"]["c"] == 5.10514
    strain = result["modeling_report"]["inspection"]["semiconductor_health"]["strain_summary"]
    assert strain["latest"]["axes"] == ["c"]
