    assert calculation["task_intent"] == "band_structure"
    assert calculation["cutoff_status"] == "ok"
    assert calculation["kpoint_mode"] == "separation"
    assert calculation["requires_prior_relaxed_structure"] is True
    assert semiconductor["band_path_summary"]["task_relevant"] is True
    assert semiconductor["band_path_summary"]["bravais_lattice"] == "hexagonal"
    live_summary = result["live_summary"]
    assert live_summary["semiconductor_calculation_status"] == calculation["status"]
    assert live_summary["semiconductor_calculation_task"] == "BandStructure"
    assert live_summary["semiconductor_calculation_task_intent"] == "band_structure"
    assert live_summary["semiconductor_calculation_cutoff_status"] == "ok"
    assert live_summary["semiconductor_calculation_kpoint_mode"] == "separation"
    assert live_summary["semiconductor_calculation_kpoint_separation"] == 0.03
