    assert live_summary["semiconductor_estimated_kpoints_from_separation"] == semiconductor["reciprocal_lattice_summary"]["estimated_kpoints_from_separation"]
    assert live_summary["semiconductor_band_path_requires_materials_studio_review"] is True
    assert live_summary["semiconductor_calculation_requires_prior_relaxed_structure"] is True
