    created = server.material_studio_live_modeling_request(
        "构建 Si(100) 表面 slab",
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True

    added = server.material_studio_live_modeling_request(
        "在分数坐标 0.5 0.5 0.24 添加 Htop1 H",
        working_dir=str(tmp_path),
    )
    assert added["ok"] is True
    assert added["workflow"] == "patch"
    assert added["nl_plan"]["template_id"] == "crystal_add_atom_fractional"
    assert added["view_audit"]["model"]["elements"] == {"H": 1, "Si": 8}
    added_atom = next(atom for atom in added["view_audit"]["atoms"] if atom["id"] == "Htop1")
    assert added_atom["fractional"] == [0.5, 0.5, 0.24]

    moved = server.material_studio_live_modeling_request(
        "将 Htop1 移动到分数坐标 0.5 0.5 0.28 并热加载到 Materials Studio",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
