    assert moved["execution_mode"] == "execute"
    assert moved["execution_mode_source"] == "explicit_live_intent"
    assert moved["nl_plan"]["template_id"] == "crystal_set_atom_fractional"
    assert moved["result"]["execution_backend"] == "crystal_cif_materialize"
    moved_atom = next(atom for atom in moved["view_audit"]["atoms"] if atom["id"] == "Htop1")
    assert moved_atom["fractional"] == [0.5, 0.5, 0.28]
    assert moved["modeling_report"]["gui"]["hot_loaded"] is True
    assert backend.opened
    assert backend.opened[-1].suffix == ".cif"


