def test_live_modeling_request_infers_semiconductor_slab_templates(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    cases = [
        ("Build Si(100) surface slab for semiconductor modeling.", "silicon_100_slab", {"Si": 8}, "(100)"),
        ("Build GaAs(001) surface slab.", "gallium_arsenide_001_slab", {"As": 4, "Ga": 4}, "(001)"),
        ("Build GaN(0001) surface slab.", "gallium_nitride_0001_slab", {"Ga": 2, "N": 2}, "(0001)"),
        ("Build AlN(0001) surface slab.", "aluminum_nitride_0001_slab", {"Al": 2, "N": 2}, "(0001)"),
        ("Build InN(0001) surface slab.", "indium_nitride_0001_slab", {"In": 2, "N": 2}, "(0001)"),
        ("Build ZnO(0001) surface slab.", "zinc_oxide_0001_slab", {"O": 8, "Zn": 8}, "(0001)"),
        ("构建氧化锌(0001)表面并准备预览", "zinc_oxide_0001_slab", {"O": 8, "Zn": 8}, "(0001)"),
    ]
    for request, template_id, elements, orientation in cases:
        result = server.material_studio_live_modeling_request(request, working_dir=str(tmp_path))

        assert result["ok"] is True
        assert result["workflow"] == "create"
        assert result["execution_mode"] == "preview"
        assert result["nl_plan"]["template_id"] == template_id
        assert result["view_audit"]["model"]["name"] == template_id
        assert result["view_audit"]["model"]["elements"] == elements
        assert result["view_audit"]["model"]["lattice"]["c"] == 25.0
        assert result["view_audit"]["metadata"]["surface_orientation"] == orientation
        current = server.material_studio_model_get_current(result["project_id"], working_dir=str(tmp_path))
        assert current["spec"]["metadata"]["domain"] == "semiconductor"
        assert current["spec"]["metadata"]["surface_orientation"] == orientation
        assert current["spec"]["metadata"]["termination"] == "unpassivated"
        assert result["modeling_report"]["inspection"]["surface"]["surface_orientation"] == orientation
        assert result["modeling_report"]["inspection"]["surface"]["vacuum_angstrom"] > 19.0
        assert result["modeling_report"]["inspection"]["slab_vacuum"]["vacuum_ok"] is True
        assert result["modeling_health"]["verdict"] == "ready_with_warnings"
        assert result["modeling_report"]["normality"] == "review_warnings"
        assert result["modeling_health"]["checks"]["semiconductor_surface_dangling_bond_estimate"] > 0
        assert any("dangling bonds" in warning for warning in result["modeling_health"]["warnings"])
        assert result["modeling_report"]["inspection"]["crystal_nearest_neighbor_stats_angstrom"]["min"] > 1.0
        assert result["view_bundle_row_counts"]["crystal_coordination"] == result["view_audit"]["model"]["atom_count"]
        assert result["modeling_report"]["inspection"]["view_count"] == 6
        assert Path(result["view_audit_report_path"]).exists()


