def test_live_modeling_request_handles_chinese_vacuum_layer_variants(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    cases = [
        "添加 10 埃真空层",
        "沿 z 方向增加 10 埃 真空层",
    ]
    for index, request in enumerate(cases):
        work = tmp_path / f"vacuum_{index}"
        created = server.material_studio_live_modeling_request(
            "构建硅(100)表面并准备预览",
            working_dir=str(work),
        )
        assert created["ok"] is True
        assert created["nl_plan"]["template_id"] == "silicon_100_slab"

        result = server.material_studio_live_modeling_request(
            request,
            working_dir=str(work),
        )

        assert result["ok"] is True
        assert result["workflow"] == "patch"
        assert result["nl_plan"]["template_id"] == "crystal_vacuum"
        assert "add_vacuum z 10.0" in result["diff"]
        assert result["revision_delta"]["crystal"]["lattice_delta"] == {"c": 10.0}
        assert result["modeling_report"]["inspection"]["slab_vacuum"]["surface_axis"] == "c"
        assert result["modeling_report"]["inspection"]["slab_vacuum"]["declared_vacuum_angstrom"] > 10.0
        assert result["modeling_report"]["inspection"]["slab_vacuum"]["vacuum_ok"] is True


def test_live_modeling_request_infers_semiconductor_crystal_patches(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build silicon crystal for semiconductor modeling.",
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True

    supercell = server.material_studio_live_modeling_request(
        "Make 2x2x1 supercell.",
        working_dir=str(tmp_path),
    )
    assert supercell["ok"] is True
    assert supercell["workflow"] == "patch"
    assert supercell["nl_plan"]["template_id"] == "crystal_supercell"
    assert supercell["project_resolution"]["source"] == "latest_current"
    assert supercell["view_audit"]["model"]["atom_count"] == 32
    assert abs(supercell["view_audit"]["model"]["lattice"]["a"] - 10.862) < 1e-6
    assert abs(supercell["view_audit"]["model"]["lattice"]["b"] - 10.862) < 1e-6

    vacancy = server.material_studio_live_modeling_request(
        "Create vacancy at Si1_000.",
        working_dir=str(tmp_path),
    )
    assert vacancy["ok"] is True
    assert vacancy["nl_plan"]["template_id"] == "crystal_vacancy"
    assert vacancy["new_revision"] == 2
    assert vacancy["revision"] == 2
    assert vacancy["view_audit"]["model"]["atom_count"] == 31
    defect_summary = vacancy["modeling_report"]["inspection"]["semiconductor_health"]["defect_summary"]
    defect = defect_summary["defects"][0]
    assert defect_summary["vacancy_count"] == 1
    assert defect_summary["total_lattice_site_count_estimate"] == 32
    assert defect_summary["total_vacancy_fraction"] == 0.03125
    assert defect["site_id"] == "Si1_000"
    assert defect["site_element"] == "Si"
    assert defect["nearest_neighbor_count"] == 4
    assert defect["undercoordinated_neighbor_count"] == 4
    assert defect["missing_neighbor_bond_estimate"] == 4
    assert vacancy["modeling_health"]["verdict"] == "ready_with_warnings"
    assert vacancy["modeling_health"]["checks"]["semiconductor_vacancy_count"] == 1
    assert vacancy["modeling_health"]["checks"]["semiconductor_defect_missing_neighbor_bond_estimate"] == 4
    assert any("vacancy/defect" in warning for warning in vacancy["modeling_health"]["warnings"])
    assert Path(vacancy["modeling_report"]["diagnostics"]["semiconductor_defects_csv"]).exists()

    doped = server.material_studio_live_modeling_request(
        "Dope Si2_000 with P.",
        working_dir=str(tmp_path),
    )
    assert doped["ok"] is True
    assert doped["nl_plan"]["template_id"] == "crystal_dopant"
    assert doped["new_revision"] == 3
    assert doped["view_audit"]["model"]["elements"] == {"P": 1, "Si": 30}
    doped_receipt = doped["modeling_report"]["change_receipt"]
    assert doped_receipt["workflow"] == "patch"
    assert doped_receipt["user_request"] == "Dope Si2_000 with P."
    assert doped_receipt["base_revision"] == 2
    assert doped_receipt["revision"] == 3
    assert doped_receipt["nl_template_id"] == "crystal_dopant"
    assert doped_receipt["delta"]["element_count_delta"] == {"P": 1, "Si": -1}
    assert doped_receipt["formula"] == "PSi30"
    assert doped_receipt["semiconductor"]["formula"] == "PSi30"
    assert doped_receipt["semiconductor"]["dopants"]["dopant_elements"] == ["P"]
    assert "finite_size_or_dilution_warning" in doped_receipt["semiconductor"]["risk_flags"]
    assert "semiconductor:finite_size_or_dilution_warning" in doped_receipt["calculation_blocking_reasons"]
    assert doped_receipt["ready_for_next_edit"] is True

    vacuum = server.material_studio_live_modeling_request(
        "Add 10 angstrom vacuum along z.",
        working_dir=str(tmp_path),
    )
    assert vacuum["ok"] is True
    assert vacuum["nl_plan"]["template_id"] == "crystal_vacuum"
    assert vacuum["new_revision"] == 4
    assert abs(vacuum["view_audit"]["model"]["lattice"]["c"] - 15.431) < 1e-6
    assert vacuum["modeling_report"]["inspection"]["view_count"] == 6
    assert vacuum["modeling_report"]["inspection"]["slab_vacuum"]["surface_axis"] == "c"
    assert vacuum["modeling_report"]["inspection"]["slab_vacuum"]["declared_vacuum_angstrom"] == 10.0
    assert vacuum["modeling_report"]["inspection"]["slab_vacuum"]["vacuum_ok"] is True
    assert vacuum["modeling_report"]["semiconductor_review"]["lattice"]["is_slab"] is True


