def test_live_modeling_request_hotloads_iii_v_superlattice(monkeypatch, tmp_path: Path) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    result = server.material_studio_live_modeling_request(
        "Build a GaAs/AlAs superlattice and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is True
    assert result["workflow"] == "create"
    assert result["execution_mode"] == "execute"
    assert result["nl_plan"]["template_id"] == "gallium_arsenide_aluminum_arsenide_001_heterostructure"
    assert result["view_audit"]["model"]["elements"] == {"Al": 4, "As": 8, "Ga": 4}
    assert result["view_audit"]["metadata"]["interface"] == "GaAs/AlAs"
    assert result["modeling_report"]["inspection"]["crystal_coordination_stats"]["min"] == 4.0
    heterostructure = result["modeling_report"]["inspection"]["semiconductor_health"]["heterostructure_summary"]
    assert heterostructure["interface"] == "GaAs/AlAs"
    assert heterostructure["substrate"] == "GaAs"
    assert heterostructure["max_abs_in_plane_strain_percent"] < 0.08
    sublattice = result["modeling_report"]["inspection"]["semiconductor_health"]["sublattice_balance_summary"]
    assert sublattice["balance_kind"] == "iii_v_cation_anion_count"
    assert sublattice["balanced"] is True
    assert sublattice["balance_delta_count"] == 0
    assert result["modeling_health"]["checks"]["semiconductor_sublattice_balanced"] is True
    assert result["modeling_health"]["checks"]["semiconductor_iii_v_cation_count"] == 8
    assert result["modeling_health"]["checks"]["semiconductor_iii_v_anion_count"] == 8
    assert result["modeling_health"]["checks"]["semiconductor_lattice_volume_angstrom3"] == 362.10506
    assert result["modeling_health"]["checks"]["semiconductor_volume_per_non_passivant_atom_angstrom3"] == 22.631566
    assert result["modeling_health"]["checks"]["semiconductor_neighbor_pair_count"] == 32
    assert result["modeling_health"]["checks"]["semiconductor_neighbor_pair_type_count"] == 2
    assert result["modeling_health"]["checks"]["semiconductor_neighbor_distance_min_angstrom"] == 2.449078
    assert result["modeling_health"]["checks"]["semiconductor_local_environment_coordination_outlier_count"] == 0
    assert result["modeling_health"]["checks"]["semiconductor_tetrahedral_angle_deviation_max_deg"] == 0.037173
    assert result["modeling_health"]["checks"]["semiconductor_total_valence_electron_count"] == 64
    assert result["modeling_health"]["checks"]["semiconductor_electron_count_parity"] == "even"
    assert result["modeling_health"]["checks"]["semiconductor_carrier_type_hint"] == "neutral_or_intrinsic"
    assert result["modeling_health"]["checks"]["semiconductor_calculation_module"] == "CASTEP"
    assert result["modeling_health"]["checks"]["semiconductor_calculation_cutoff_energy_ev"] == 520
    assert result["modeling_health"]["checks"]["semiconductor_calculation_kpoint_mode"] == "separation"
    assert result["modeling_health"]["checks"]["semiconductor_calculation_ready_for_energy_preflight"] is True
    assert result["modeling_health"]["checks"]["semiconductor_reciprocal_status"] == "ok"
    assert result["modeling_health"]["checks"]["semiconductor_reciprocal_estimated_kpoints"] == [28, 28, 14]
    assert result["modeling_health"]["checks"]["semiconductor_interface_transition_count"] == 1
    assert result["modeling_health"]["checks"]["semiconductor_interface_abrupt"] is True
    layer_profile = result["modeling_report"]["inspection"]["semiconductor_health"]["layer_profile_summary"]
