def test_concurrent_structured_patches_return_one_revision_conflict(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    spec = load_benzene("concurrent_mcp_patch")
    created = server.material_studio_model_create_from_spec(
        spec,
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True
    original_save_revision = store_module.ProjectStore.save_revision
    save_barrier = threading.Barrier(2)

    def synchronized_save_revision(self, *args, **kwargs):
        save_barrier.wait(timeout=10.0)
        return original_save_revision(self, *args, **kwargs)

    monkeypatch.setattr(
        store_module.ProjectStore,
        "save_revision",
        synchronized_save_revision,
    )

    def remove(atom_id: str) -> dict:
        return server.material_studio_model_modify_with_patch(
            project_id=created["project_id"],
            base_revision=0,
            patch={"operations": [{"type": "delete_atom", "atom_id": atom_id}]},
            working_dir=str(tmp_path),
        )

    with ThreadPoolExecutor(max_workers=2) as executor:
        results = list(executor.map(remove, ("H1", "H2")))

    committed = [result for result in results if result.get("ok") is True]
    conflicts = [
        result
        for result in results
        if result.get("status") == "project_revision_conflict"
    ]
    assert len(committed) == 1
    assert len(conflicts) == 1
    assert committed[0]["revision"] == 1
    assert committed[0]["state_write_transaction"]["domain"] == "project_state"
    assert conflicts[0]["expected_revision"] == 0
    assert conflicts[0]["current_revision"] == 1
    assert conflicts[0]["state_write_deferred"] is True
    assert conflicts[0]["state_retry_tool"] == "material_studio_live_project_status"
    store = store_module.ProjectStore(tmp_path)
    assert store.load_current(created["project_id"]).revision == 1
    assert [
        event["revision"] for event in store.list_history(created["project_id"])
    ] == [0, 1]
    assert not (
        store.project_dir(created["project_id"])
        / "revisions"
        / "r002_model_spec.json"
    ).exists()


def test_structured_patch_state_lock_timeout_returns_retry_contract(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    spec = load_benzene("mcp_state_lock_timeout")
    created = server.material_studio_model_create_from_spec(
        spec,
        working_dir=str(tmp_path),
    )
    store = store_module.ProjectStore(tmp_path)
    project_dir = store.project_dir(created["project_id"])
    current_path = project_dir / "current.json"
    history_path = project_dir / "history.jsonl"
    committed_current = current_path.read_bytes()
    committed_history = history_path.read_bytes()
    monkeypatch.setattr(
        store_module,
        "PROJECT_STATE_LOCK_TIMEOUT_SECONDS",
        0.05,
    )
    monkeypatch.setattr(
        store_module,
        "PROJECT_STATE_LOCK_POLL_SECONDS",
        0.005,
    )
    lock_path = project_dir / "project_state.lock"

    with store_module._project_state_advisory_write_lock(
        lock_path,
        project_id=created["project_id"],
        workspace_root=tmp_path,
        timeout_seconds=1.0,
        poll_seconds=0.01,
    ):
        blocked = server.material_studio_model_modify_with_patch(
            project_id=created["project_id"],
            base_revision=0,
            patch={"operations": [{"type": "delete_atom", "atom_id": "H1"}]},
            working_dir=str(tmp_path),
        )

    assert blocked["ok"] is False
    assert blocked["status"] == "project_state_busy"
    assert blocked["state_write_deferred"] is True
    assert blocked["project_state_transaction_error"] == blocked["error"]
    assert blocked["state_retry_payload"] == {
        "project_id": created["project_id"],
        "include_gui_status": False,
    }
    assert current_path.read_bytes() == committed_current
    assert history_path.read_bytes() == committed_history
    assert not (project_dir / "revisions" / "r001_model_spec.json").exists()


def test_structured_patch_rejects_orphan_revision_allocation_drift(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    spec = load_benzene("mcp_orphan_allocation")
    created = server.material_studio_model_create_from_spec(
        spec,
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True
    store = store_module.ProjectStore(tmp_path)
    project_dir = store.project_dir(created["project_id"])
    current_path = project_dir / "current.json"
    history_path = project_dir / "history.jsonl"
    current_before = current_path.read_bytes()
    history_before = history_path.read_bytes()
    original_save_revision = store_module.ProjectStore.save_revision

    def inject_orphan_before_commit(self, project_id, *args, **kwargs):
        orphan_path = (
            self.project_dir(project_id)
            / "revisions"
            / "r001_model_spec.json"
        )
        orphan_path.write_bytes(b'{"incomplete":')
        return original_save_revision(self, project_id, *args, **kwargs)

    monkeypatch.setattr(
        store_module.ProjectStore,
        "save_revision",
        inject_orphan_before_commit,
    )
    rejected = server.material_studio_model_modify_with_patch(
        project_id=created["project_id"],
        base_revision=0,
        patch={"operations": [{"type": "delete_atom", "atom_id": "H1"}]},
        working_dir=str(tmp_path),
    )

    assert rejected["ok"] is False
    assert rejected["status"] == "project_revision_allocation_conflict"
    assert rejected["expected_new_revision"] == 1
    assert rejected["allocated_revision"] == 2
    assert rejected["current_revision"] == 0
    assert rejected["state_write_deferred"] is True
    assert rejected["state_retry_tool"] == "material_studio_live_project_status"
    assert rejected["state_retry_payload"] == {
        "project_id": created["project_id"],
        "include_gui_status": True,
    }
    compact = server._compact_live_response(
        rejected,
        server.McpResponseMode.COMPACT,
    )
    assert compact["expected_new_revision"] == 1
    assert compact["allocated_revision"] == 2
    assert compact["current_revision"] == 0
    assert current_path.read_bytes() == current_before
    assert history_path.read_bytes() == history_before
    assert not (project_dir / "revisions" / "r002_model_spec.json").exists()
    assert not (project_dir / "scripts" / "r002_build.pl").exists()


def test_concurrent_same_revision_execution_returns_busy_without_second_runner(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    monkeypatch.setattr(server, "REVISION_EXECUTION_LOCK_TIMEOUT_SECONDS", 0.05)
    monkeypatch.setattr(server, "REVISION_EXECUTION_LOCK_POLL_SECONDS", 0.005)
    execution_started = threading.Event()
    release_execution = threading.Event()
    runner_calls: list[int] = []

    def blocking_execute(*, store, spec, script, timeout_seconds):
        runner_calls.append(spec.revision)
        execution_started.set()
        assert release_execution.wait(timeout=10.0)
        output = (
            store.outputs_dir(spec.project_id, spec.revision)
            / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        )
        output.write_text("serialized execution", encoding="utf-8")
        return {
            "result": {"success": True, "created_files": [str(output)]},
            "result_metadata_path": str(output.parent / "result_metadata.json"),
        }

    monkeypatch.setattr(server, "_execute_structured_script", blocking_execute)
    created = server.material_studio_model_create_from_spec(
        load_benzene("concurrent_revision_execution"),
        working_dir=str(tmp_path),
    )
    with ThreadPoolExecutor(max_workers=1) as executor:
        first_future = executor.submit(
            server.material_studio_gui_apply_current_revision,
            project_id=created["project_id"],
            execution_mode="execute",
            open_in_gui=False,
            take_snapshot=False,
            export_view_audit=False,
            working_dir=str(tmp_path),
        )
        assert execution_started.wait(timeout=10.0)
        blocked = server.material_studio_gui_apply_current_revision(
            project_id=created["project_id"],
            execution_mode="execute",
            open_in_gui=False,
            take_snapshot=False,
            export_view_audit=False,
            working_dir=str(tmp_path),
            response_mode="compact",
        )
        try:
            assert first_future.done() is False
            blocked_status = server.material_studio_live_project_status(
                project_id=created["project_id"],
                include_gui_status=False,
                working_dir=str(tmp_path),
            )
            assert blocked_status["execution_started"] is False
            assert blocked_status["execution_deferred"] is True
            assert (
                blocked_status["execution_transaction_error"]
                == blocked["execution_transaction_error"]
            )
            assert (
                blocked_status["execution_retry_payload"]
                == blocked["execution_retry_payload"]
            )
            assert blocked_status["execution_runtime"]["status"] == "running"
            assert blocked_status["execution_runtime"]["active"] is True
            active_attempt = blocked_status["execution_runtime"]["latest_attempt"]
            assert active_attempt["status"] == "running"
        finally:
            release_execution.set()
        committed = first_future.result(timeout=30.0)

    assert runner_calls == [0]
    assert blocked["ok"] is False
    assert blocked["status"] == "revision_execution_busy"
    assert blocked["execution_started"] is False
    assert blocked["execution_deferred"] is True
    assert blocked["execution_transaction_error"] == blocked["error"]
    assert blocked["execution_retry_tool"] == "material_studio_live_project_status"
    assert blocked["execution_retry_payload"] == {
        "project_id": created["project_id"],
        "include_gui_status": True,
    }
    assert "execution_transaction" not in blocked
    assert committed["ok"] is True
    transaction = committed["execution_transaction"]
    assert transaction["domain"] == "revision_execution"
    assert transaction["current_revision_still_current"] is True
    persisted_result = json.loads(
        Path(committed["result_metadata_path"]).read_text(encoding="utf-8")
    )
    assert persisted_result["execution_transaction"] == transaction
    assert committed["execution_attempt"]["attempt_id"] == active_attempt["attempt_id"]
    completed_status = server.material_studio_live_project_status(
        project_id=created["project_id"],
        include_gui_status=False,
        working_dir=str(tmp_path),
    )
    assert completed_status["execution_runtime"]["status"] == "completed"
    assert completed_status["execution_runtime"]["active"] is False


def test_waiting_execution_revalidates_current_before_runner(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    runner_calls: list[int] = []

    def must_not_execute(*, store, spec, script, timeout_seconds):
        runner_calls.append(spec.revision)
        raise AssertionError("superseded revision reached the runner")

    monkeypatch.setattr(server, "_execute_structured_script", must_not_execute)
    created = server.material_studio_model_create_from_spec(
        load_benzene("execution_current_revalidation"),
        working_dir=str(tmp_path),
    )
    store = store_module.ProjectStore(tmp_path)
    output_dir = store.outputs_dir(created["project_id"], 0)
    lock_path = output_dir / "revision_execution.lock"
    contention_observed = threading.Event()
    original_lock_attempt = gui_module._lock_file_descriptor_nonblocking

    with ThreadPoolExecutor(max_workers=1) as executor:
        with gui_module._workspace_advisory_write_lock(
            lock_path,
            workspace_root=tmp_path,
            timeout_seconds=1.0,
            poll_seconds=0.01,
        ):
            def observed_lock_attempt(file_descriptor: int) -> None:
                try:
                    original_lock_attempt(file_descriptor)
                except OSError:
                    contention_observed.set()
                    raise

            monkeypatch.setattr(
                gui_module,
                "_lock_file_descriptor_nonblocking",
                observed_lock_attempt,
            )
            execution_future = executor.submit(
                server.material_studio_gui_apply_current_revision,
                project_id=created["project_id"],
                execution_mode="execute",
                open_in_gui=False,
                take_snapshot=False,
                export_view_audit=False,
                working_dir=str(tmp_path),
                response_mode="compact",
            )
            assert contention_observed.wait(timeout=10.0)
            superseding_patch = server.material_studio_model_modify_with_patch(
                project_id=created["project_id"],
                base_revision=0,
                patch={
                    "operations": [
                        {"type": "delete_atom", "atom_id": "H1"},
                    ]
                },
                working_dir=str(tmp_path),
            )
            assert superseding_patch["ok"] is True
            assert superseding_patch["revision"] == 1
        blocked = execution_future.result(timeout=30.0)

    assert runner_calls == []
    assert blocked["ok"] is False
    assert blocked["status"] == "current_revision_execution_block"
    assert blocked["execution_started"] is False
    assert blocked["execution_deferred"] is True
    assert blocked["target_revision"] == 0
    assert blocked["current_revision"] == 1
    transaction = blocked["execution_transaction"]
    assert transaction["domain"] == "revision_execution"
    assert transaction["execution_started"] is False
    assert transaction["current_revision_at_start"] == 1
    block = blocked["current_revision_execution_block"]
    assert block["reason"] == "current_revision_advanced_before_execution"
    assert block["target_revision"] == 0
    assert block["current_revision"] == 1
    assert blocked["execution_retry_payload"] == {
        "project_id": created["project_id"],
        "include_gui_status": True,
    }
    assert not (output_dir / "result_metadata.json").exists()
    assert not (output_dir / "execution_attempt_state.json").exists()
    assert not (output_dir / "execution_attempts.jsonl").exists()


