def test_diagnostic_export_lock_timeout_preserves_report_and_skips_snapshot(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    spec = load_benzene("diagnostic_export_timeout")
    created = server.material_studio_model_create_from_spec(
        spec,
        working_dir=str(tmp_path),
    )
    baseline = server.material_studio_model_export_view_bundle(
        project_id=created["project_id"],
        include_gui_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert baseline["ok"] is True
    report_path = Path(baseline["report_json_path"])
    committed_report = report_path.read_bytes()
    capture_count = 0
    original_capture = backend.capture_window

    def counted_capture(window: WindowInfo, output_path: Path) -> Path:
        nonlocal capture_count
        capture_count += 1
        return original_capture(window, output_path)

    monkeypatch.setattr(backend, "capture_window", counted_capture)
    monkeypatch.setattr(server, "GUI_ARTIFACT_REPORT_LOCK_TIMEOUT_SECONDS", 0.05)
    monkeypatch.setattr(server, "GUI_ARTIFACT_REPORT_LOCK_POLL_SECONDS", 0.005)
    lock_path = report_path.parent / "gui_artifact_report.lock"

    with gui_module._workspace_advisory_write_lock(
        lock_path,
        workspace_root=tmp_path,
        timeout_seconds=1.0,
        poll_seconds=0.01,
    ):
        audit = server.material_studio_model_export_view_audit(
            project_id=created["project_id"],
            include_gui_snapshot=True,
            working_dir=str(tmp_path),
        )
        bundle = server.material_studio_model_export_view_bundle(
            project_id=created["project_id"],
            include_gui_snapshot=True,
            working_dir=str(tmp_path),
            response_mode="compact",
        )
        inspection = server.material_studio_live_modeling_request(
            "Is the current model normal?",
            project_id=created["project_id"],
            take_snapshot=False,
            working_dir=str(tmp_path),
        )

    for result, tool_name in (
        (audit, "material_studio_model_export_view_audit"),
        (bundle, "material_studio_model_export_view_bundle"),
    ):
        assert result["ok"] is False
        assert result["status"] == "diagnostic_export_deferred"
        assert result["diagnostic_export_deferred"] is True
        assert result["report_persistence_deferred"] is True
        assert result["diagnostic_export_retry_tool"] == tool_name
        assert result["diagnostic_export_retry_payload"]["project_id"] == created["project_id"]
        assert "GUI artifact report write transaction is busy" in result["error"]
    assert inspection["ok"] is False
    assert inspection["status"] == "diagnostic_export_deferred"
    assert inspection["workflow"] == "inspect_current"
    assert inspection["diagnostic_export_deferred"] is True
    assert inspection["report_persistence_deferred"] is True
    assert (
        inspection["diagnostic_export_retry_tool"]
        == "material_studio_live_modeling_request"
    )
    assert (
        inspection["diagnostic_export_retry_payload"]["project_id"]
        == created["project_id"]
    )
    assert capture_count == 0
    assert report_path.read_bytes() == committed_report


def test_diagnostic_export_rejects_revision_superseded_while_waiting(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    spec = load_benzene("diagnostic_export_superseded")
    created = server.material_studio_model_create_from_spec(
        spec,
        working_dir=str(tmp_path),
    )
    baseline = server.material_studio_model_export_view_bundle(
        project_id=created["project_id"],
        include_gui_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert baseline["ok"] is True
    report_path = Path(baseline["report_json_path"])
    committed_report = report_path.read_bytes()
    lock_path = report_path.parent / "gui_artifact_report.lock"
    contention_observed = threading.Event()
    original_lock_attempt = gui_module._lock_file_descriptor_nonblocking
    capture_count = 0
    original_capture = backend.capture_window

    def observed_lock_attempt(file_descriptor: int) -> None:
        try:
            original_lock_attempt(file_descriptor)
        except OSError:
            contention_observed.set()
            raise

    def counted_capture(window: WindowInfo, output_path: Path) -> Path:
        nonlocal capture_count
        capture_count += 1
        return original_capture(window, output_path)

    monkeypatch.setattr(
        gui_module,
        "_lock_file_descriptor_nonblocking",
        observed_lock_attempt,
    )
    monkeypatch.setattr(backend, "capture_window", counted_capture)

    with ThreadPoolExecutor(max_workers=1) as executor:
        with gui_module._workspace_advisory_write_lock(
            lock_path,
            workspace_root=tmp_path,
            timeout_seconds=1.0,
            poll_seconds=0.01,
        ):
            pending = executor.submit(
                server.material_studio_model_export_view_bundle,
                None,
                created["project_id"],
                None,
                True,
                str(tmp_path),
            )
            assert contention_observed.wait(timeout=10.0)
            patched = server.material_studio_model_modify_with_patch(
                project_id=created["project_id"],
                base_revision=created["revision"],
                patch={"operations": [{"type": "delete_atom", "atom_id": "H1"}]},
                working_dir=str(tmp_path),
            )
            assert patched["ok"] is True
            assert patched["revision"] == 1
        exported = pending.result(timeout=30.0)

    assert exported["ok"] is False
    assert exported["status"] == "diagnostic_export_revision_superseded"
    assert exported["revision"] == 0
    assert exported["current_revision"] == 1
    assert exported["diagnostic_export_current_revision_block"]["blocked"] is True
    assert exported["diagnostic_export_retry_payload"]["project_id"] == created["project_id"]
    assert capture_count == 0
    assert report_path.read_bytes() == committed_report


def test_inspect_current_publishes_all_reports_inside_one_transaction(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = FakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon crystal.",
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    original_persist = server._persist_modeling_report
    persist_calls: list[dict[str, object]] = []

    def tracked_persist(store, model_spec, response):
        active = server._ACTIVE_GUI_ARTIFACT_REPORT_TRANSACTION.get()
        persist_calls.append(
            {
                "revision": model_spec.revision,
                "active": active is not None,
                "transaction_revision": (
                    (active or {}).get("transaction", {}).get("revision")
                    if isinstance(active, dict)
                    else None
                ),
            }
        )
        return original_persist(store, model_spec, response)

    monkeypatch.setattr(server, "_persist_modeling_report", tracked_persist)
    inspected = server.material_studio_live_modeling_request(
        "Is the current model normal?",
        project_id=created["project_id"],
        working_dir=str(tmp_path),
        take_snapshot=False,
    )

    assert inspected["ok"] is True
    assert len(persist_calls) == 2
    assert all(call["active"] is True for call in persist_calls)
    assert all(call["revision"] == created["revision"] for call in persist_calls)
    assert all(
        call["transaction_revision"] == created["revision"]
        for call in persist_calls
    )
    transaction = inspected["report_write_transaction"]
    assert transaction["nested_call_count"] >= 1
    assert {
        "workflow:inspect_current",
        "workflow:model_export_view_bundle",
        "current_revision_revalidation",
        "diagnostic_export",
        "view_audit_bundle_write",
        "report_read_modify_write",
    } <= set(transaction["coverage"])


def test_gui_snapshot_blocks_concurrent_open_before_gui_action(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    project_id = created["project_id"]
    revision = created["revision"]
    structure_path = created["planned_outputs"]["structure"]
    initial_open_count = len(backend.opened)
    capture_started = threading.Event()
    release_capture = threading.Event()
    contention_observed = threading.Event()
    original_capture = backend.capture_window
    original_lock_attempt = gui_module._lock_file_descriptor_nonblocking

    def blocking_capture(window: WindowInfo, output_path: Path) -> Path:
        capture_started.set()
        assert release_capture.wait(timeout=10.0)
        return original_capture(window, output_path)

    def observed_lock_attempt(file_descriptor: int) -> None:
        try:
            original_lock_attempt(file_descriptor)
        except OSError:
            contention_observed.set()
            raise

    monkeypatch.setattr(backend, "capture_window", blocking_capture)
    monkeypatch.setattr(gui_module, "_lock_file_descriptor_nonblocking", observed_lock_attempt)

    with ThreadPoolExecutor(max_workers=2) as executor:
        first = executor.submit(
            server.material_studio_gui_snapshot,
            "action_transaction_snapshot",
            project_id,
            revision,
            str(tmp_path),
        )
        assert capture_started.wait(timeout=10.0)
        second = executor.submit(
            server.material_studio_gui_open_structure,
            structure_path,
            project_id,
            revision,
            False,
            True,
            True,
            None,
            str(tmp_path),
        )
        try:
            assert contention_observed.wait(timeout=10.0)
            assert second.done() is False
            assert len(backend.opened) == initial_open_count
        finally:
            release_capture.set()
        snapshot_result = first.result(timeout=30.0)
        open_result = second.result(timeout=30.0)

    assert snapshot_result["ok"] is True
    assert open_result["ok"] is True
    assert len(backend.opened) == initial_open_count + 1
    snapshot_transaction = snapshot_result["gui_action_transaction"]
    open_transaction = open_result["gui_action_transaction"]
    assert snapshot_transaction["path"] == open_transaction["path"]
    assert snapshot_transaction["nested_call_count"] == 1
    assert open_transaction["nested_call_count"] == 1
    assert open_transaction["waited_seconds"] > 0.0
    assert {
        "target_window_revalidation",
        "gui_snapshot",
        "report_read_modify_write",
    } <= set(snapshot_transaction["coverage"])
    assert {
        "target_window_revalidation",
        "gui_open_structure",
        "report_read_modify_write",
    } <= set(open_transaction["coverage"])
    report = json.loads(Path(created["report_json_path"]).read_text(encoding="utf-8"))
    assert [artifact["type"] for artifact in report["gui_artifacts"]] == ["gui_open"]


def test_visual_confirmation_revalidates_window_after_waiting_for_gui_action_transaction(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    project_id = created["project_id"]
    revision = created["revision"]
    management = created["gui_status"]["window_management"]
    capture_started = threading.Event()
    release_capture = threading.Event()
    contention_observed = threading.Event()
    original_capture = backend.capture_window
    original_lock_attempt = gui_module._lock_file_descriptor_nonblocking

    def blocking_capture(window: WindowInfo, output_path: Path) -> Path:
        capture_started.set()
        assert release_capture.wait(timeout=10.0)
        return original_capture(window, output_path)

    def observed_lock_attempt(file_descriptor: int) -> None:
        try:
            original_lock_attempt(file_descriptor)
        except OSError:
            contention_observed.set()
            raise

    monkeypatch.setattr(backend, "capture_window", blocking_capture)
    monkeypatch.setattr(gui_module, "_lock_file_descriptor_nonblocking", observed_lock_attempt)

    with ThreadPoolExecutor(max_workers=2) as executor:
        first = executor.submit(
            server.material_studio_gui_snapshot,
            "binding_revalidation_snapshot",
            project_id,
            revision,
            str(tmp_path),
        )
        assert capture_started.wait(timeout=10.0)
        second = executor.submit(
            server.material_studio_gui_record_visual_confirmation,
            project_id,
            revision,
            "computer_use",
            True,
            "must be rejected after the target window changes",
            None,
            management["target_window_handle"],
            management["target_window_title"],
            None,
            str(tmp_path),
        )
        try:
            assert contention_observed.wait(timeout=10.0)
            assert second.done() is False
            prior_window = backend.window
            backend.window = WindowInfo(
                handle=prior_window.handle + 100,
                title=prior_window.title,
                pid=prior_window.pid,
                rect=prior_window.rect,
            )
        finally:
            release_capture.set()
        snapshot_result = first.result(timeout=30.0)
        confirmation_result = second.result(timeout=30.0)

    assert snapshot_result["ok"] is True
    assert confirmation_result["ok"] is False
    assert confirmation_result["status"] == "visual_confirmation_rejected"
    assert "observed_window_handle_mismatch" in confirmation_result["visual_confirmation_binding"]["rejection_reasons"]
    assert confirmation_result["gui_action_transaction"]["waited_seconds"] > 0.0
    assert "visual_confirmation_binding" in confirmation_result["gui_action_transaction"]["coverage"]
    report = json.loads(Path(created["report_json_path"]).read_text(encoding="utf-8"))
    assert not any(
        artifact.get("type") == "visual_confirmation"
        and artifact.get("note") == "must be rejected after the target window changes"
        for artifact in report["gui_artifacts"]
    )


@pytest.mark.parametrize(
    ("first_operation", "expected_artifact_types"),
    [
        ("open", ["gui_open", "gui_snapshot"]),
        ("snapshot", ["gui_open"]),
    ],
)
def test_gui_open_and_snapshot_reports_follow_lock_acquisition_order(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
    first_operation: str,
    expected_artifact_types: list[str],
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    project_id = created["project_id"]
    revision = created["revision"]
    gui = MaterialsStudioGuiController(str(tmp_path), backend=backend)
    snapshot = gui.snapshot(
        label=f"{first_operation}_ordering_snapshot",
        project_id=project_id,
        revision=revision,
    )
    gui_open = {**created["gui_open"], "test_sequence": first_operation}

    def persist_open() -> dict:
        return server._persist_gui_open_structure_report(
            project_id=project_id,
            revision=revision,
            gui_open=gui_open,
            gui=gui,
            working_dir=str(tmp_path),
            views=None,
            project_resolution=created.get("project_resolution"),
        )

    def persist_snapshot() -> dict:
        return server._persist_gui_snapshot_report(
            project_id=project_id,
            revision=revision,
            snapshot=snapshot,
            gui=gui,
            working_dir=str(tmp_path),
            views=None,
            project_resolution=created.get("project_resolution"),
        )

    first_update = persist_open if first_operation == "open" else persist_snapshot
    second_update = persist_snapshot if first_operation == "open" else persist_open
    first_result, second_result = _run_concurrent_gui_report_updates(
        monkeypatch,
        first_update,
        second_update,
    )

    assert (
        first_result["report_write_transaction"]["path"]
        == second_result["report_write_transaction"]["path"]
    )
    assert second_result["report_write_transaction"]["waited_seconds"] > 0.0
    report = json.loads(Path(created["report_json_path"]).read_text(encoding="utf-8"))
    assert [artifact["type"] for artifact in report["gui_artifacts"]] == expected_artifact_types
    assert report["gui_artifacts"][0]["result"]["test_sequence"] == first_operation
    snapshot_paths = {
        artifact.get("screenshot_path")
        for artifact in report["gui_artifacts"]
        if artifact.get("type") == "gui_snapshot"
    }
    assert (snapshot["screenshot_path"] in snapshot_paths) is (first_operation == "open")


def test_gui_artifact_report_lock_timeout_preserves_report(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    report_path = Path(created["report_json_path"])
    committed_report = report_path.read_bytes()
    output_dir = report_path.parent
    lock_path = output_dir / "gui_artifact_report.lock"
    management = created["gui_status"]["window_management"]
    initial_open_count = len(backend.opened)
    capture_call_count = 0
    original_capture = backend.capture_window

    def counted_capture(window: WindowInfo, output_path: Path) -> Path:
        nonlocal capture_call_count
        capture_call_count += 1
        return original_capture(window, output_path)

    monkeypatch.setattr(backend, "capture_window", counted_capture)
    monkeypatch.setattr(
        server,
        "GUI_ARTIFACT_REPORT_LOCK_TIMEOUT_SECONDS",
        0.05,
    )
    monkeypatch.setattr(
        server,
        "GUI_ARTIFACT_REPORT_LOCK_POLL_SECONDS",
        0.005,
    )

    with gui_module._workspace_advisory_write_lock(
        lock_path,
        workspace_root=tmp_path,
        timeout_seconds=1.0,
        poll_seconds=0.01,
    ):
        blocked_snapshot = server.material_studio_gui_snapshot(
            label="must_not_capture_while_transaction_is_busy",
            project_id=created["project_id"],
            revision=created["revision"],
            working_dir=str(tmp_path),
        )
        blocked_open = server.material_studio_gui_open_structure(
            created["planned_outputs"]["structure"],
            project_id=created["project_id"],
            revision=created["revision"],
            take_snapshot=False,
            working_dir=str(tmp_path),
        )
        blocked = server.material_studio_gui_record_visual_confirmation(
            project_id=created["project_id"],
            revision=created["revision"],
            source="computer_use",
            note="must not be persisted while the report lock is held",
            expected_window_handle=management["target_window_handle"],
            expected_window_title=management["target_window_title"],
            working_dir=str(tmp_path),
        )

    assert blocked_snapshot["ok"] is False
    assert "GUI artifact report write transaction is busy" in blocked_snapshot["error"]
    assert blocked_open["ok"] is False
    assert "GUI artifact report write transaction is busy" in blocked_open["error"]
    assert blocked["ok"] is False
    assert "GUI artifact report write transaction is busy" in blocked["error"]
    assert capture_call_count == 0
    assert len(backend.opened) == initial_open_count
    assert report_path.read_bytes() == committed_report
    recorded = server.material_studio_gui_record_visual_confirmation(
        project_id=created["project_id"],
        revision=created["revision"],
        source="computer_use",
        note="persisted after report lock release",
        expected_window_handle=management["target_window_handle"],
        expected_window_title=management["target_window_title"],
        working_dir=str(tmp_path),
    )
    assert recorded["ok"] is True


def test_high_level_patch_waits_for_snapshot_transaction_before_hotload(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    patch_execution_ready = threading.Event()
    release_patch_execution = threading.Event()

    def fake_execute_structured_script(*, store, spec, script, timeout_seconds):
        output = (
            store.project_dir(spec.project_id)
            / "outputs"
            / f"r{spec.revision:03d}"
            / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        )
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text(f"fake revision {spec.revision}", encoding="utf-8")
        if spec.revision == 1:
            patch_execution_ready.set()
            assert release_patch_execution.wait(timeout=10.0)
        return {
            "result": {"success": True, "created_files": [str(output)]},
            "result_metadata_path": str(output.parent / "result_metadata.json"),
        }

    monkeypatch.setattr(server, "_execute_structured_script", fake_execute_structured_script)
    created = server.material_studio_model_create_from_spec(
        load_benzene("high_level_patch_transaction_proj"),
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True
    loaded = server.material_studio_gui_apply_current_revision(
        project_id=created["project_id"],
        execution_mode="execute",
        take_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert loaded["ok"] is True
    initial_open_count = len(backend.opened)

    capture_started = threading.Event()
    release_capture = threading.Event()
    contention_observed = threading.Event()
    original_capture = backend.capture_window
    original_lock_attempt = gui_module._lock_file_descriptor_nonblocking

    def blocking_capture(window: WindowInfo, output_path: Path) -> Path:
        capture_started.set()
        assert release_capture.wait(timeout=10.0)
        return original_capture(window, output_path)

    def observed_lock_attempt(file_descriptor: int) -> None:
        try:
            original_lock_attempt(file_descriptor)
        except OSError:
            contention_observed.set()
            raise

    monkeypatch.setattr(backend, "capture_window", blocking_capture)
    monkeypatch.setattr(gui_module, "_lock_file_descriptor_nonblocking", observed_lock_attempt)

    with ThreadPoolExecutor(max_workers=2) as executor:
        patch_future = executor.submit(
            server.material_studio_live_update_with_patch,
            project_id=created["project_id"],
            base_revision=0,
            patch={
                "operations": [
                    {
                        "type": "set_atom_position",
                        "atom_id": "H1",
                        "xyz_angstrom": [2.6, 0.0, 0.0],
                    }
                ]
            },
            user_text="Move H1 and hot-load the current revision in Materials Studio.",
            execution_mode="execute",
            open_in_gui=True,
            take_snapshot=False,
            export_view_audit=True,
            working_dir=str(tmp_path),
        )
        assert patch_execution_ready.wait(timeout=10.0)
        snapshot_future = executor.submit(
            server.material_studio_gui_snapshot,
            "high_level_patch_blocker",
            created["project_id"],
            1,
            str(tmp_path),
        )
        assert capture_started.wait(timeout=10.0)
        release_patch_execution.set()
        try:
            assert contention_observed.wait(timeout=10.0)
            assert patch_future.done() is False
            assert len(backend.opened) == initial_open_count
        finally:
            release_capture.set()
        snapshot_result = snapshot_future.result(timeout=30.0)
        patch_result = patch_future.result(timeout=30.0)

    assert snapshot_result["ok"] is True
    assert patch_result["ok"] is True
    assert patch_result["revision"] == 1
    assert len(backend.opened) == initial_open_count + 1
    assert backend.opened[-1].suffix == ".stp"
    snapshot_transaction = snapshot_result["gui_action_transaction"]
    patch_transaction = patch_result["gui_action_transaction"]
    assert snapshot_transaction["path"] == patch_transaction["path"]
    assert patch_transaction["path"] == patch_result["report_write_transaction"]["path"]
    assert patch_transaction["waited_seconds"] > 0.0
    assert patch_transaction["nested_call_count"] == 0
    assert {
        "high_level_hotload",
        "workflow:live_patch",
        "target_window_revalidation",
        "gui_open_structure",
        "report_read_modify_write",
    } <= set(patch_transaction["coverage"])


def test_high_level_patch_revalidates_window_count_after_execution(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    patch_execution_ready = threading.Event()
    release_patch_execution = threading.Event()

    def fake_execute_structured_script(*, store, spec, script, timeout_seconds):
        output = (
            store.project_dir(spec.project_id)
            / "outputs"
            / f"r{spec.revision:03d}"
            / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        )
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text(f"fake revision {spec.revision}", encoding="utf-8")
        if spec.revision == 1:
            patch_execution_ready.set()
            assert release_patch_execution.wait(timeout=10.0)
        return {
            "result": {"success": True, "created_files": [str(output)]},
            "result_metadata_path": str(output.parent / "result_metadata.json"),
        }

    monkeypatch.setattr(server, "_execute_structured_script", fake_execute_structured_script)
    created = server.material_studio_model_create_from_spec(
        load_benzene("high_level_window_drift_proj"),
        working_dir=str(tmp_path),
    )
    loaded = server.material_studio_gui_apply_current_revision(
        project_id=created["project_id"],
        execution_mode="execute",
        take_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert loaded["ok"] is True
    initial_open_count = len(backend.opened)
    drift_enabled = threading.Event()
    original_list_windows = backend.list_windows
    extra_window = WindowInfo(
        handle=999,
        title="Unexpected - Materials Studio",
        pid=backend.window.pid,
        rect=(20, 20, 1024, 768),
    )

    def drifting_list_windows(pid: int | None = None) -> list[WindowInfo]:
        windows = original_list_windows(pid)
        if drift_enabled.is_set() and (pid is None or pid == extra_window.pid):
            windows.append(extra_window)
        return windows

    monkeypatch.setattr(backend, "list_windows", drifting_list_windows)
    with ThreadPoolExecutor(max_workers=1) as executor:
        patch_future = executor.submit(
            server.material_studio_live_update_with_patch,
            project_id=created["project_id"],
            base_revision=0,
            patch={
                "operations": [
                    {
                        "type": "set_atom_position",
                        "atom_id": "H1",
                        "xyz_angstrom": [2.7, 0.0, 0.0],
                    }
                ]
            },
            user_text="Move H1 and hot-load it in Materials Studio.",
            execution_mode="execute",
            take_snapshot=False,
            working_dir=str(tmp_path),
        )
        assert patch_execution_ready.wait(timeout=10.0)
        drift_enabled.set()
        release_patch_execution.set()
        patch_result = patch_future.result(timeout=30.0)

    assert patch_result["ok"] is False
    assert patch_result["result"]["success"] is True
    assert patch_result["single_window_hotload_block"]["reason"] == "single_window_policy_violation"
    assert patch_result["single_window_hotload_block"]["single_window_violation_reasons"] == [
        "multiple_matstudio_windows_detected"
    ]
    assert "gui_open" not in patch_result
    assert len(backend.opened) == initial_open_count
    transaction = patch_result["gui_action_transaction"]
    assert transaction["path"] == patch_result["report_write_transaction"]["path"]
    assert "target_window_revalidation" in transaction["coverage"]
    persisted_report = json.loads(Path(patch_result["report_json_path"]).read_text(encoding="utf-8"))
    assert persisted_report["ok"] is False
    assert persisted_report["gui_open"] is None
    assert persisted_report["modeling_report"]["live_readiness"]["state"] == "blocked"


def test_high_level_patch_does_not_hotload_revision_superseded_during_execution(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    first_patch_execution_ready = threading.Event()
    release_first_patch_execution = threading.Event()

    def fake_execute_structured_script(*, store, spec, script, timeout_seconds):
        output = (
            store.project_dir(spec.project_id)
            / "outputs"
            / f"r{spec.revision:03d}"
            / f"{spec.project_id}_r{spec.revision:03d}.xsd"
        )
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text(f"fake revision {spec.revision}", encoding="utf-8")
        if spec.revision == 1:
            first_patch_execution_ready.set()
            assert release_first_patch_execution.wait(timeout=10.0)
        return {
            "result": {"success": True, "created_files": [str(output)]},
            "result_metadata_path": str(output.parent / "result_metadata.json"),
        }

    monkeypatch.setattr(server, "_execute_structured_script", fake_execute_structured_script)
    created = server.material_studio_model_create_from_spec(
        load_benzene("high_level_revision_drift_proj"),
        working_dir=str(tmp_path),
    )
    loaded = server.material_studio_gui_apply_current_revision(
        project_id=created["project_id"],
        execution_mode="execute",
        take_snapshot=False,
        working_dir=str(tmp_path),
    )
    assert loaded["ok"] is True
    initial_open_count = len(backend.opened)

    with ThreadPoolExecutor(max_workers=1) as executor:
        first_patch_future = executor.submit(
            server.material_studio_live_update_with_patch,
            project_id=created["project_id"],
            base_revision=0,
            patch={
                "operations": [
                    {
                        "type": "set_atom_position",
                        "atom_id": "H1",
                        "xyz_angstrom": [2.6, 0.0, 0.0],
                    }
                ]
            },
            user_text="Move H1 and hot-load it in Materials Studio.",
            execution_mode="execute",
            take_snapshot=False,
            working_dir=str(tmp_path),
        )
        assert first_patch_execution_ready.wait(timeout=10.0)
        superseding_patch = server.material_studio_live_update_with_patch(
            project_id=created["project_id"],
            base_revision=1,
            patch={
                "operations": [
                    {
                        "type": "set_atom_position",
                        "atom_id": "H2",
                        "xyz_angstrom": [-2.7, 0.0, 0.0],
                    }
                ]
            },
            user_text="Move H2 and keep the newer revision as preview.",
            execution_mode="preview",
            open_in_gui=False,
            take_snapshot=False,
            working_dir=str(tmp_path),
        )
        assert superseding_patch["ok"] is True
        assert superseding_patch["revision"] == 2
        release_first_patch_execution.set()
        first_patch = first_patch_future.result(timeout=30.0)

    assert first_patch["ok"] is False
    assert first_patch["revision"] == 1
    assert first_patch["result"]["success"] is True
    execution_transaction = first_patch["execution_transaction"]
    assert execution_transaction["execution_started"] is True
    assert execution_transaction["execution_completed"] is True
    assert execution_transaction["current_revision_at_start"] == 1
    assert execution_transaction["current_revision_after_execution"] == 2
    assert execution_transaction["current_revision_still_current"] is False
    persisted_result = json.loads(
        Path(first_patch["result_metadata_path"]).read_text(encoding="utf-8")
    )
    assert persisted_result["execution_transaction"] == execution_transaction
    block = first_patch["current_revision_hotload_block"]
    assert block["reason"] == "current_revision_advanced_during_execution"
    assert block["target_revision"] == 1
    assert block["current_revision"] == 2
    assert block["recommended_tool"] == "material_studio_live_project_status"
    assert "gui_open" not in first_patch
    assert len(backend.opened) == initial_open_count
    assert "current_revision_revalidation" in first_patch["gui_action_transaction"]["coverage"]
    current = server.material_studio_model_get_current(
        created["project_id"],
        working_dir=str(tmp_path),
    )
    assert current["revision"] == 2
    persisted_report = json.loads(Path(first_patch["report_json_path"]).read_text(encoding="utf-8"))
    assert persisted_report["execution_transaction"] == execution_transaction
    assert persisted_report["current_revision_hotload_block"]["current_revision"] == 2
    assert persisted_report["gui_open"] is None


