def test_live_orchestration_publishes_final_report_inside_gui_transaction(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal.",
        views=["top", "front", "isometric"],
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert created["ok"] is True
    assert created["execution_mode"] == "preview"

    original_persist = server._persist_modeling_report
    persist_calls: list[dict[str, object]] = []

    def tracked_persist(store, spec, response):
        active = server._ACTIVE_GUI_ARTIFACT_REPORT_TRANSACTION.get()
        persist_calls.append(
            {
                "workflow": response.get("workflow"),
                "revision": spec.revision,
                "transaction_active": active is not None,
                "transaction_revision": (
                    (active or {}).get("transaction", {}).get("revision")
                    if isinstance(active, dict)
                    else None
                ),
            }
        )
        return original_persist(store, spec, response)

    monkeypatch.setattr(server, "_persist_modeling_report", tracked_persist)

    shown = server.material_studio_live_modeling_request(
        "Show the current model in Materials Studio.",
        project_id=created["project_id"],
        views=["top", "front", "isometric"],
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert shown["ok"] is True
    assert persist_calls == [
        {
            "workflow": "show_current",
            "revision": 0,
            "transaction_active": True,
            "transaction_revision": 0,
        }
    ]
    assert "workflow:show_current" in shown["gui_action_transaction"]["coverage"]
    assert "workflow:gui_apply_current_revision" not in shown["gui_action_transaction"]["coverage"]
    shown_report = json.loads(Path(shown["report_json_path"]).read_text(encoding="utf-8"))
    assert shown_report["workflow"] == "show_current"
    assert shown_report["modeling_report"]["workflow"] == "show_current"

    persist_calls.clear()
    patched = server.material_studio_live_modeling_request(
        "Make a 2x1x1 supercell and hot-load it in Materials Studio.",
        project_id=created["project_id"],
        views=["top", "front", "isometric"],
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert patched["ok"] is True
    assert persist_calls == [
        {
            "workflow": "patch",
            "revision": 1,
            "transaction_active": True,
            "transaction_revision": 1,
        }
    ]
    assert "workflow:patch" in patched["gui_action_transaction"]["coverage"]
    patched_report = json.loads(Path(patched["report_json_path"]).read_text(encoding="utf-8"))
    assert patched_report["workflow"] == "patch"
    assert patched_report["modeling_report"]["workflow"] == "patch"

    persist_calls.clear()
    rolled_back = server.material_studio_live_modeling_request(
        "Undo the last change and hot-load it in Materials Studio.",
        project_id=created["project_id"],
        views=["top", "front", "isometric"],
        working_dir=str(tmp_path),
        take_snapshot=False,
    )
    assert rolled_back["ok"] is True
    assert persist_calls == [
        {
            "workflow": "rollback",
            "revision": 2,
            "transaction_active": True,
            "transaction_revision": 2,
        }
    ]
    assert "workflow:rollback" in rolled_back["gui_action_transaction"]["coverage"]
    rollback_report = json.loads(
        Path(rolled_back["report_json_path"]).read_text(encoding="utf-8")
    )
    assert rollback_report["workflow"] == "rollback"
    assert rollback_report["modeling_report"]["workflow"] == "rollback"


def test_atomic_report_publish_failure_preserves_committed_report(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(
        server,
        "_gui_controller",
        lambda working_dir=None: MaterialsStudioGuiController(
            working_dir,
            backend=backend,
        ),
    )
    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    report_path = Path(created["report_json_path"])
    committed_report = report_path.read_bytes()
    management = created["gui_status"]["window_management"]
    original_replace = store_module.os.replace

    def fail_report_replace(source: str | Path, destination: str | Path) -> None:
        if Path(destination).resolve() == report_path.resolve():
            raise OSError("simulated report publish interruption")
        original_replace(source, destination)

    monkeypatch.setattr(store_module.os, "replace", fail_report_replace)
    failed = server.material_studio_gui_record_visual_confirmation(
        project_id=created["project_id"],
        revision=created["revision"],
        source="computer_use",
        note="must not replace the committed report",
        expected_window_handle=management["target_window_handle"],
        expected_window_title=management["target_window_title"],
        working_dir=str(tmp_path),
    )

    assert failed["ok"] is False
    assert "simulated report publish interruption" in failed["error"]
    assert report_path.read_bytes() == committed_report
    assert not list(report_path.parent.glob(f".{report_path.name}.*.tmp"))


def test_live_entry_records_only_window_bound_visual_confirmation(monkeypatch, tmp_path: Path) -> None:
    backend = ProjectWindowFakeGuiBackend()
    monkeypatch.setattr(server, "_gui_controller", lambda working_dir=None: MaterialsStudioGuiController(working_dir, backend=backend))

    created = server.material_studio_live_modeling_request(
        "Build silicon diamond semiconductor crystal and hot-load it in Materials Studio.",
        working_dir=str(tmp_path),
    )
    assert created["ok"] is True
    project_id = created["project_id"]
    revision = created["revision"]
    window_management = created["gui_status"]["window_management"]
    window_handle = window_management["target_window_handle"]
    window_title = window_management["target_window_title"]
    history_before = server.material_studio_project_history(project_id, working_dir=str(tmp_path))["history"]
    report_path = Path(created["report_json_path"])

    rejected = server.material_studio_live_modeling_request(
        "Record the Computer Use visual observation for the current MS viewport.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
        visual_confirmation={
            "source": "computer_use",
            "model_visible": True,
            "note": "The expected model is visible in the Materials Studio viewport.",
            "expected_revision": revision,
            "expected_window_handle": window_handle + 1,
            "expected_window_title": window_title,
        },
    )
    assert rejected["ok"] is False
    assert rejected["response_mode"] == "compact"
    assert rejected["status"] == "visual_confirmation_rejected"
    assert "observed_window_handle_mismatch" in rejected["visual_confirmation_binding"]["rejection_reasons"]
    assert json.loads(report_path.read_text(encoding="utf-8"))["gui_visual_confirmation"] is None

    recorded = server.material_studio_live_modeling_request(
        "Record the Computer Use visual observation for the current MS viewport.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
        visual_confirmation={
            "source": "computer_use",
            "model_visible": True,
            "note": "The expected model and unit cell are visible in the single Materials Studio viewport.",
            "expected_revision": revision,
            "expected_window_handle": window_handle,
            "expected_window_title": window_title,
        },
    )

    assert recorded["ok"] is True
    assert recorded["response_mode"] == "compact"
    assert recorded["workflow"] == "gui_visual_confirmation"
    assert recorded["revision"] == revision
    assert recorded["revision_created"] is False
    assert recorded["visual_confirmation"]["model_visible"] is True
    assert recorded["visual_confirmation_binding"]["status"] == "verified_current_wrapper_window"
    assert recorded["live_gui_acceptance"]["external_visual_confirmation_ok"] is True
    assert recorded["diagnostic_export_requested"] is False
    assert recorded["normality_check_requested"] is False
    assert recorded["gui_evidence_reaudit"]["evidence_request_context_provided"] is True
    assert recorded["gui_evidence_reaudit"]["evidence_request_diagnostic_export_requested"] is False
    assert recorded["gui_evidence_reaudit"]["evidence_request_normality_check_requested"] is False
    assert recorded["gui_evidence_reaudit"]["effective_normality_check_requested"] is False
    assert "evidence_request" not in recorded["gui_evidence_reaudit"]
    assert "modeling_report" not in recorded
    assert recorded["report_write_transaction"]["scope"] == "project_revision"
    assert recorded["report_write_transaction"]["domain"] == "gui_artifact_report"
    assert recorded["report_write_transaction"]["path"].endswith(
        "gui_artifact_report.lock"
    )
    assert recorded["gui_action_transaction"]["path"] == recorded["report_write_transaction"]["path"]
    assert recorded["gui_action_transaction"]["nested_call_count"] == 1
    assert {
        "target_window_revalidation",
        "visual_confirmation_binding",
        "report_read_modify_write",
    } <= set(recorded["gui_action_transaction"]["coverage"])
    assert len(json.dumps(recorded, ensure_ascii=False).encode("utf-8")) < server.COMPACT_RESPONSE_MAX_BYTES
    history_after = server.material_studio_project_history(project_id, working_dir=str(tmp_path))["history"]
    assert len(history_after) == len(history_before)

    persisted = json.loads(report_path.read_text(encoding="utf-8"))
    assert persisted["gui_visual_confirmation"]["model_visible"] is True
    assert persisted["gui_visual_confirmation"]["window_binding"]["ok"] is True
    assert persisted["normality_check_requested"] is False
    assert persisted["modeling_report"]["normality_check_requested"] is False
    assert persisted["gui_evidence_reaudit"]["prior_explicit_intent_preserved"] is True
    assert persisted["gui_evidence_reaudit"]["evidence_request"] == (
        "Record the Computer Use visual observation for the current MS viewport."
    )
    assert persisted["modeling_report"]["gui"]["external_visual_confirmation_ok"] is True

    explicitly_checked = server.material_studio_live_modeling_request(
        "Record the current MS viewport and check whether the model is normal.",
        project_id=project_id,
        working_dir=str(tmp_path),
        response_mode="compact",
        visual_confirmation={
            "source": "computer_use",
            "model_visible": True,
            "note": "The current model remains visible while normality diagnostics are requested.",
            "expected_revision": revision,
            "expected_window_handle": window_handle,
            "expected_window_title": window_title,
        },
    )
    assert explicitly_checked["ok"] is True
    assert explicitly_checked["diagnostic_export_requested"] is True
    assert explicitly_checked["normality_check_requested"] is True
    explicit_reaudit = explicitly_checked["gui_evidence_reaudit"]
    assert explicit_reaudit["prior_normality_check_requested"] is False
    assert explicit_reaudit["evidence_request_normality_check_requested"] is True
    assert explicit_reaudit["effective_normality_check_requested"] is True
    assert "evidence_request" not in explicit_reaudit
    persisted_after_explicit_check = json.loads(report_path.read_text(encoding="utf-8"))
    assert persisted_after_explicit_check["normality_check_requested"] is True
    assert persisted_after_explicit_check["modeling_report"]["normality_check_requested"] is True


