    assert defect["undercoordinated_neighbor_count"] == 2
    assert result["modeling_health"]["checks"]["semiconductor_vacancy_count"] == 1
    assert result["modeling_health"]["checks"]["semiconductor_surface_dangling_bond_estimate"] == 0
    assert any("vacancy/defect leaves under-coordinated neighbors" in warning for warning in result["modeling_health"]["warnings"])
    assert Path(result["view_bundle_files"]["semiconductor_surface_termination_csv"]).exists()
    assert Path(result["view_bundle_files"]["semiconductor_surface_polarity_csv"]).exists()
    assert Path(result["view_bundle_files"]["semiconductor_defects_csv"]).exists()
    assert result["modeling_report"]["gui"]["hot_loaded"] is True
    assert backend.opened[-1].suffix == ".cif"


