        assert diagnostic_focus_plan == result["modeling_report"]["change_receipt"]["diagnostic_focus_plan"]
        assert diagnostic_focus_plan == result["live_summary"]["diagnostic_focus_plan"]
        assert diagnostic_focus_plan["recommended_focuses"] == recommended_focuses
        assert diagnostic_focus_plan["unrequested_recommended_focuses"] == unrequested_focuses
        assert diagnostic_focus_plan["template_default_focuses"] == default_focuses
        assert diagnostic_focus_plan["recommended_tool"] == "material_studio_model_export_view_bundle"
        assert diagnostic_focus_plan["safe_to_call_without_confirmation"] is True
        assert diagnostic_focus_plan["needs_user_confirmation"] is False
        assert diagnostic_focus_plan["payload_hint"]["project_id"] == result["project_id"]
