def test_live_modeling_request_rejects_unsupported_free_text(tmp_path: Path) -> None:
    result = server.material_studio_live_modeling_request(
        "Build a completely unspecified new material with many atoms.",
        working_dir=str(tmp_path),
    )

    assert result["ok"] is False
    assert result["nl_plan"]["kind"] == "unsupported"
    assert "ModelSpec" in result["required_next_step"]
    contract = result["live_modeling_contract"]
    assert contract["ok"] is False
    assert contract["status"] == "unsupported_request"
    assert contract["nl_plan_kind"] == "unsupported"
    assert contract["workflow_stages"]["status"] == "blocked"
    assert contract["workflow_stages"]["failed_required_stages"] == ["request"]
    assert contract["workflow_stages"]["stages"]["request"]["ok"] is False
    assert contract["current_model_context"]["available"] is False
    assert contract["followup_edit_capabilities"]["available"] is False
    assert contract["followup_edit_capabilities"]["status"] == "blocked_before_modeling"
    assert "crystal_vacancy" in contract["followup_edit_capabilities"]["supported_command_ids"]
    assert contract["hotload"]["attempted"] is False
    assert contract["semiconductor"]["available"] is False
    assert contract["diagnostic_artifacts"]["available"] is False
    assert contract["normality"]["can_claim_model_normal"] is False
    assert "unsupported_request" in contract["normality"]["must_not_claim_normal_reasons"]
    assert contract["next_action"]["recommended_tool"] == "material_studio_live_modeling_request"
    assert contract["next_action"]["recommended_action"] == "provide_model_spec_or_semantic_patch"
    assert contract["next_action"]["payload_hint"]["accepted_payloads"] == ["spec", "patch"]
    assert contract["next_action"]["payload_hint"]["capabilities_tool"] == "material_studio_live_capabilities"
    hint = result["capabilities_hint"]
    assert hint["capabilities_tool"] == "material_studio_live_capabilities"
    assert "benzene" in hint["new_structure_template_ids"]
    assert "set_bond_type" in hint["patch_command_ids"]
    assert Path(hint["schemas"]["model_spec"]["path"]).exists()
    assert Path(hint["schemas"]["semantic_patch"]["path"]).exists()


